/* 全库分片 6/43，共 1000 首（chinese-gushiwen / chinese-poetry）*/
window.QUAN_KU_PART_5 = [
  {"t":"京都","p":"","d":"元代","a":"周权","c":["水入金河滟玉虹，填街车马拥尘红。九重天近风云壮，万雉城高鼓角雄。", "花底催朝冠佩列，酒边听曲绮罗丛。太平光景春台乐，物物薰陶圣化中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刘生","p":"","d":"隋代","a":"弘执恭","c":["英名振关右，雄气逸江东。游侠五都内，去来三秦中。", "剑照七星影，马控千金骢。纵横方未息，因兹定武功。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红 其二","p":"","d":"清代","a":"奭良","c":["正气凌云，遥下拜、歌声未歇。想昔日、背嵬军盛，如火烈烈。", "一旅倘挥天外剑，九州共奉王正月。奈生来、偏值小朝庭，空翘切。", "许都郡，组练雪。洞庭寇，烟灰灭。正壮心未已，唾壶都缺。", "儒将自宜教礼乐，纯臣岂敢私毛血。看画图、玉貌甚雍容，疑朝阙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"永遇乐（和钱处和上元）","p":"","d":"宋代","a":"王之望","c":["元夜风光，上都灯火，辉映春色。鳌冠仙山，龙衔瑞烛，银阙凌空碧。紫烟深拥，黄云孤起，人喜乍瞻天日。□云里，□□□□，侍臣□□鹄立。", "雾收霞卷，珠帘开遍，翠暮娉婷争出。倾国丛中，钧天合处，忽听鸣清跸。貂裘小帽，随车信马，犹忆少年豪逸。如今对，山城皓月，但余叹息。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百一十七首 其七十八","p":"","d":"宋代","a":"释绍昙","c":["十二峰前傀儡棚，尽由行主线抽牵。编排科段无新旧，歌舞秋风乐管筵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蚕","p":"","d":"宋代","a":"谢枋得","c":["养口资身赖以桑，终成王道泽流长。", "吐丝不羡蜘蛛巧，饲叶频催织女忙。", "三起三眠时化运，一生一死命天常。", "待看献茧盆缫后，先与吾皇织衮裳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和伯氏包山观桃花韵","p":"","d":"宋代","a":"胡仲参","c":["因访桃花到岑根，御林春色此平分。", "千株示数栽唐观，一幅犹堪画晋源。", "仙在云间无处觅，人行风外有香闻。", "笙箫隐隐宫城隔，立尽黄昏更断魂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋日在梧桐","p":"","d":"宋代","a":"王安石","c":["秋日在梧桐，转阴如急毂。", "冥冥蔽中庭，下视今可暴。", "高蝉不复嘒，稍得寒鸦宿。", "百绕有衰翁，行歌待春绿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中口占","p":"","d":"宋代","a":"舒邦佐","c":["拂枕投床鼻息鸣，邻鸡报午梦还惊。一春已过半春了，十日曾无五日晴。", "唤客难同藉草饮，隔墙虚认卖花声。十年前忆西湖上，柳荫苏堤取次行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏至夜宿海幢僧阁","p":"","d":"明代","a":"梁以壮","c":["隔江灯火坐中看，四面潮声欲上栏。山月鹿归双角解，寺钟龙听一珠蟠。", "河南书屋人何在，岭上松风石自寒。无限幽怀不能写，抱琴清绝水云端。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吴门秋怀八首 其三","p":"","d":"明代","a":"邓云霄","c":["宦薄能令侠骨尊，西风客思满秋原。久居泽国谙吴语，每向江枫吊楚魂。", "暗里含沙犹射影，时来孤鹤忽乘轩。少年日逐专诸巷，袖有鱼肠未报恩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"野人","p":"","d":"当代","a":"陈忠平","c":["野人疏大志，端居一水浔。青眸谁顾惜，明月自升沈。", "鸥点秋沙白，烟笼春梦深。有时无所事，万籁共长吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"入冬半月馀二麦未种忽然一雨","p":"","d":"宋代","a":"丘葵","c":["村庄三日雨，清晓怯凭栏。洒地纷纷白，随风阵阵寒。", "不愁客衣薄，且为老农欢。已有芃芃意，来春岁计宽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"叠前韵悼物理学家兼诗人黄克孙先生三首 其三","p":"","d":"当代","a":"伯昏子","c":["今剩蔷薇插玉壶，从兹挥手白云孤。他年若遇青藤下，但执天钧问有无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游独孤城下作","p":"","d":"宋代","a":"张嵲","c":["利成山百丈，直下独孤城。", "事往岁月积，长江依旧清。", "昔人经过地，我辈复此行。", "但见竹树稠，石崖如削成。", "乔木晚未凋，青青发余荣。", "天寒远峰澹，日晏长川明。", "时危怀古意，岁暮羁旅情。", "一室寄绝岸，全家托柴荆。", "晨炊饭脱粟，似此田涧氓。", "群盗正猖獗，深居且偷生。", "反念故园日，默默何由平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"泊临清州二首 其二","p":"","d":"清代","a":"夏孙桐","c":["秋潦残堤水势宽，城闉隐起暮烟寒。一行远雁连霜树，数点昏鸦立电竿。", "行旅方知关吏贵，灾区还念赈需难。嗷嗷中泽严冬迫，谁向监门画里看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浪淘沙","p":"","d":"清代","a":"冒广生","c":["梦雨了无痕。零落琴樽。一春情绪怕黄昏。还要凄凉心上影，添个销魂。", "何处莫愁村。旧曲桃根。思量谁与共温存。闲煞月明花满地，独自关门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"随缘吟","p":"","d":"宋代","a":"邵雍","c":["得路青霄正好冲，休贪粮稻恋深笼。", "要无为后须还朴，好自由时莫厌穷。", "百计用心终上错，一场大梦到头空。", "生涯澹澹随缘过，未肯将身入彀中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题安成刘伯深爵瑞里报德堂上白爵图","p":"","d":"宋代","a":"杨万里","c":["君不见书台之北爵瑞里，", "安成令君旌孝子。报德堂前松造天，", "卜宅浩然老居士。居士元无一物遗，", "子孙只有牙签三万存。郎君饭此三万轴，", "落纸云烟动埸屋。雪中负土成先茔，", "感得路人双涕零。更傅雪爵云上随，", "天表孝子蹈雪行。即看黄告来告弟，", "是时雪爵应再至。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉炉中","p":"苏幕遮","d":"元代","a":"高道宽","c":["玉炉中，烧丹药。锻炼三成，最上真个妙。海底龟蛇勤收捉。纳在壶中，炼就圆明觉。照无边，光灼灼。顺手拈来，直下长生勺。功行十分凭戒约。一对芒鞋，穿上踏云脚。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"送春","p":"","d":"宋代","a":"陆游","c":["新叶张翠幄，落花作红茵。", "山蔬旨且柔，家酿清而淳。", "以我垂老境，送此将归春。", "我固惜流年，春亦记陈人。", "江山处处佳，风月日日新。", "蹇驴度松冈，短楫横烟津。", "兰亭人已远，遗韵犹清真。", "却下木栅市，天风吹角巾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重阳日次荆南路经武宁驿","p":"","d":"唐代","a":"崔橹","c":["茱萸冷吹溪口香，菊花倒绕山脚黄。家山去此强百里，", "弟妹待我醉重阳。风健早鸿高晓景，露清圆碧照秋光。", "莫看时节年年好，暗送搔头逐手霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶题","p":"","d":"宋代","a":"李流谦","c":["小沟溶漾可涉，彩舫夷犹不惊。", "晚酌忽逢名酒，当时打破愁城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"全上人之仰山","p":"","d":"宋代","a":"释子益","c":["集云峰下四藤条，千载谁知恨未销。", "去去全身担荷得，石龙依旧碧岧嶢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"回望峡山二首","p":"","d":"宋代","a":"杨万里","c":["浪喜出峡来，峡亦何曾出。", "两岸只无山，依旧江刻屈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"事白后再上疏乞骸承伯玉司马以二诗慰问有感问答 其二","p":"","d":"明代","a":"王世贞","c":["飞章万里叩天阍，乞得闲身是主恩。已荷圣朝宽毁骨，可烦词客为招魂。", "行逢车马心先折，语到渔樵道便尊。依约十年栖隐处，软莎新竹护柴门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梁武帝","p":"咏史下","d":"宋代","a":"陈普","c":["戒舍工夫老未员，百双鸡子送残年。", "一生般若成何事，赢得江头载荻船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闺怨一百二十首 其三十九","p":"","d":"明代","a":"孙蕡","c":["月斜风细梦初回，日掩重门夜却开。花影乱中人影过，失惊原是小琼来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水乐洞","p":"","d":"清代","a":"弘历","c":["水乐探幽洞，鍧铿果异常。尽消诸虑处，繁会八音场。", "非竹还非革，中宫亦中商。妙张洞庭趣，何必问东阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"北山别业三十八咏 其二十七 水亭","p":"","d":"元代","a":"陈樵","c":["少凤穿花照水盟，水禽冲浪动轩楹。云从薜荔衣中起，雨向玕琪树上生。", "曲水傍人流白羽，娇花无语荅黄莺。涧中日与山中日，同上晴窗各自行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨中溪行杂诗 其一","p":"","d":"明代","a":"顾璘","c":["十日溪中舟，格格响溪石。孤篷过鸣雨，忽失沙上脊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"草","p":"","d":"宋代","a":"丁谓","c":["葭茁迎春早，山芮得地高。", "堪书同细带，入咏似青袍。", "弱力绵绵葛，微香蓼蓼莪。", "王孙何处在，楚思遍江皋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和紫虚丹房二十首 其五","p":"","d":"明代","a":"程通","c":["退朝行殿侍吟坛，剪烛吟诗到夜残。一胆信知如斗大，寸心还欲似天宽。", "文章李杜齐名易，勋业伊周接踵难。深荷国恩无以报，几回兴念几忘餐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读书","p":"","d":"宋代","a":"吕本中","c":["老去有馀业，读书空作劳。时闻夜虫响，每伴午鸡号。", "久静能忘病，因行得出遨。胡为良自苦，膏火自煎熬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"邢侍郎居敬挽章","p":"","d":"明代","a":"程敏政","c":["楚节随恩侍紫清，棹歌声里独魂惊。空馀易学传三辅，无复官名署两京。", "清白已堪书太史，经纶应未了平生。相如老去人争羡，分赐无缘及露茎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登天柱峰次路北村院长旧韵","p":"","d":"明代","a":"顾璘","c":["天柱峰高白日晴，华嵩相对最分明。扶桑倒射东溟影，银汉平流上界声。", "空里金宫陈帝座，云边铁锁度人行。不缘旌节巡方岳，孤负尘埃过此生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"楞伽山诗","p":"","d":"清代","a":"周龙藻","c":["先王定秩祀，赫赫祭义悬。岂容淫昏鬼，得以非族干。", "世衰道始丧，恢诡滋神奸。咄哉楞伽山，蒙诟数百年。", "冈峦非不美，有孽凭于巅。其事俚且诞，意出妖巫传。", "公然饰屋宇，金碧穷芳妍。木偶杂男女，佩玉而纡鬟。", "部卒侍两帝，肖象青红填。遂令无知辈，瞽聋自欺谩。", "石湖水清驶，什五排画船。牲牢必脩洁，箫鼓仍喧阗。", "虽值风雨夕，奔走惧少延。妇人尤噂𠴲，语恶不忍宣。", "心邪乘隙入，梦寐生狂颠。动云神所致，祷赛宜加虔。", "妖巫既得志，吠声益狺狺。鼓舞数邑民，真如蝇慕膻。", "每当婚礼成，先期陈几筵。乡村真可笑，立庙溪谷边。", "高广仅盈尺，尊奉同帝天。屈指百里中，日费千金钱。", "岂惟膏脂竭，风俗因之迁。阴霾蔽白日，沈痼无由痊。", "自昔守土吏，往往多名贤。逡巡惮摘发，半为祸福牵。", "汤公中州起，绝学今伊川。仗节抚吴下，变俗以身先。", "痛兹淫祀炽，能使民德愆。上章罗罪状，正气回两间。", "一朝纶綍降，尽取投深渊。震雷忽破蛰，荒秽快洗湔。", "山灵亦生色，草木增葱芊。政成甫期月，玺书徵何遄。", "一老天不遗，骑箕归星躔。我闻公去后，群小复煽言。", "望祭伺昏夜，稍稍酒食骈。死灰偶不戒，虐焰恐再然。", "我愿献此诗，片石山头镌。庶几百怪息，公德永不刊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观物","p":"","d":"明代","a":"李贤（原德）","c":["闲来观物到园东，天理流行在在同。方沼雨晴看跃鲤，层霄云净见飞鸿。", "春畦苗长随宜绿，晓树花开任意红。并育宣明情固适，还将此道细研穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五君咏 其二 萧君云门","p":"","d":"清代","a":"方仁渊","c":["一尉山西去，为贫去不回。呕心吟秀句，作意写寒梅。", "儿女随芳草，田园转劫灰。宁知萧寺酒，竟作别离杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆扬州天宁寺竹","p":"","d":"清代","a":"玄烨","c":["久别金焦十一年，依稀寒暑递推迁。此君有意虚心待，叹我徒劳幽思牵。", "雁逐西风何处问，云回北地竟谁传。翠筠晚节饶苍箨，远寄宸章梵宇前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄郑谷","p":"","d":"唐代","a":"王贞白","c":["五百首新诗，缄封寄去时。只凭夫子鉴，不要俗人知。", "火鼠重收布，冰蚕乍吐丝。直须天上手，裁作领巾披。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和傅山父喜雨韵二首","p":"","d":"宋代","a":"李曾伯","c":["柔金老火苦相鏖，千里骎骎地不毛。", "忽遂所祈欣欲舞，举蒙其利润於膏。", "昭苏田畯禾千顷，饱满舟人水一篙。", "我老发挥无好句，须拈健笔付诗豪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三学山盘陀石上刻诗","p":"","d":"唐代","a":"佚名","c":["拔地山峦秀，排空殿阁斜。云供数州雨，树献九天花。", "夜月摩峰顶，秋钟彻海涯。长松拂星汉，一一是仙槎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次徐谢韵还江公诗卷","p":"","d":"宋代","a":"朱松","c":["大条祠官闲日月，绝知圣处着功深。", "荣枯举世争卢白，枉直何人较尺寻。", "身比香山差得计，诗看正始有遗音。", "应容下客游东阁，要话朱游夙昔心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"投曾秀州逢四首 其一","p":"","d":"宋代","a":"赵蕃","c":["我向茶山得屡行，至今人说老先生。九原不作吾安仰，宗武宗文贤弟兄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月时","p":"忆秦娥","d":"宋代","a":"翁元龙","c":["三月时。杨花飞尽无花飞。无花飞。不教春去，争得春归。高楼望断黄金羁。绿窗眉黛伤新离。伤新离。好将别後，长做归时。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"宁退耕岩维石隆湖隐皆尝有德於余图报未能而","p":"","d":"宋代","a":"释文珦","c":["吾生素无宠禄愿，自向空林灰百念。", "但存心地如砥平，不道人间有崖堑。", "皇天幸能念无辜，脱我险难归夷涂。", "天定胜人乃其证，纷纷谮舌胡为乎。", "四方交朋盈什百，反眼如同不相识。", "岂唯袖手不能援，多若苍蝇变白黑。", "独有空门三老人，或未褒面非交亲。", "奋身为余直其枉，恻隐如此宜称仁。", "思欲报之苦无力，但有此心匪石席。", "今日为异世人，俛仰存亡三太息。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿毛村","p":"","d":"明代","a":"吴与弼","c":["扁舟旅泊暂天涯，一夜归心又梦家。行李但教西路稳，东篱计日咏黄花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日南湖汎舟因过琼华园六首 其一","p":"","d":"宋代","a":"张镃","c":["淡日轻阴晒麦天，水边閒唤木兰船。不游东港西陂熟，争得人知是散仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"灯花","p":"","d":"明代","a":"陶安","c":["卷然铁如意，红粟结葳蕤。十瓣团葩出，孤根密缕垂。", "寒风吹不动，光燄照书帷。黄昏至夜半，有喜报人知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"出御史台","p":"","d":"宋代","a":"郑侠","c":["万险千艰六出身，如今刀得避嚣尘。", "须知从此寒原上。有个行歌拾穗人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠翰古清","p":"","d":"元代","a":"郑元祐","c":["虞公借榻宗镜堂，四众乡仰不暂忘。古清上人独见取，赠以金薤之琳琅。", "公时目眚视贸贸，文成欲写难成行。殒星著纸废属读，风襟露带斜低昂。", "中言上人善幻化，神龙千丈一钵藏。蜿蜒委蛇各有态，擘云掣电金蛇光。", "海涛翻山霹雳碎，怒捲河汉如壶浆。世人蒿目不敢觑，师独摩抚如驯羊。", "神膏点鳞翠鬣舞，金篦刮瘼星芒张。珊瑚千树宫室秘，献以耆婆未睹之药方。", "师哀其诚为摹写，风旗雷车雨脚霶。点睛未了便飞去，砚坳有墨空淋浪。", "愿师骑之上帝都，为问苍生谁短长？凫眠鹤翥且莫辨，伽那定里松花香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂二百零五首 其一一九","p":"","d":"宋代","a":"释正觉","c":["一人之父，百王之师。道机有馀兮，动若四时。寿域无疆兮，量同二仪。", "大功不宰，至化无为。妙兮虽喻，智也不知。权挂垢衣云是佛，却装珍御复名谁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次苏平仲编修北山记游韵二十四首 其三","p":"","d":"明代","a":"童冀","c":["丞相祠堂一径深，百年宰木尚阴阴。朝端又见新黄阁，天上长悬旧羽林。", "祖逖中原应有恨，孔明梁父谩长吟。神州在望空回首，落日青山澹暮岑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜雨口号九首呈潘侯","p":"","d":"宋代","a":"刘克庄","c":["虽拥朱幡只泽臞，孕鱼丹荔免苞苴。", "未应旱魃无分别，更把秋阳懊恼渠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"仙门洞次苏大禹参君韵","p":"","d":"明代","a":"佘翔","c":["共有寻真兴，林峦望里微。朝乘青雀舫，暮叩白云扉。", "涧水寒侵榻，岩花香扑衣。僧来分乞食，信宿欲忘归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"百亩中庭半是苔","p":"浣溪沙","d":"宋代","a":"王安石","c":["百亩中庭半是苔。门前白道水萦回。爱闲能有几人来。", "小院回廊春寂寂，山桃溪杏两三栽。为谁零落为谁开。"],"tags":["写景", "抒情"],"z":"","y":"","s":"","k":"词"},
  {"t":"广陵岸送北使诗","p":"","d":"南北朝","a":"阴铿","c":["行人引去节。", "送客{舟羲}归舻。", "即是观涛处。", "仍为郊赠衢。", "汀洲浪已息。", "邗江路不纡。", "亭嘶背枥马。", "樯啭向风乌。", "海上春云杂。", "天际晚帆孤。", "离舟对零雨。", "别渚望飞凫。", "定知能下泪。", "非但一杨朱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮 灯夕次韵","p":"","d":"元代","a":"善住","c":["当年老子逢佳节。万户华灯连皓月。和气满江城。喧喧队子行。掩关聊共坐。静对沉香火。一笑尽君欢。闲心无两般。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮 偃师道中","p":"","d":"元代","a":"宋＊","c":["北芒古冢纷无数。崔嵬罗列成山阜。何处断碑横。无人知姓名。今坟如蚁垤。回首成磨灭。今古两堪哀。停骖酹绿苔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"右山茶 其四 水仙","p":"","d":"明代","a":"胡应麟","c":["泠泠冰玉姿，独立潇湘岸。恍似薛家娘，寒涛披素练。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟泊岳州城下登岳阳楼晚眺","p":"","d":"近代","a":"唐群英","c":["君山突起水萦回，山色湖光照眼开。不访纯阳大仙吕，何当共我醉三回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵乐著作天庆观醮","p":"","d":"宋代","a":"苏轼","c":["浊世纷纷肯下临，梦寻飞步五云深。", "无因上到通明殿，只许微闻玉佩音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怜愚诗四十二首 其三十九","p":"","d":"明代","a":"宋应星","c":["人到无能始贷金，子钱生发向何寻？厉词追索弥年后，生计萧条起绿林。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送春拟韩致光","p":"","d":"清代","a":"林旭","c":["循例作诗三月尽，眼遭飘落太惊心。拆成片片思全盛，缀得疏疏祝久禁。", "肯记帽檐曾竞戴，无情屐齿便相侵。冬郎谩把伤春酒，早日池塘已绿阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苦脾泄在告因饮白酒一杯小愈魏倅有诗已而病","p":"","d":"宋代","a":"王炎","c":["羸老畏风湿，河鱼将奈何。", "玉友岂不佳，终难护天和。", "数息谩吐纳，链形空按摩。", "自笑来日短，残漏鸣铜荷。", "吏事如衣垢，濯之费挼挲。", "养痾谅非宜，山林归兴多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"连日灌畦莳菜废作诗","p":"","d":"宋代","a":"葛立方","c":["莫问新来额插犀，了无魂梦到金闺。", "平头上尾慵搜句，重后轻前且灌畦。", "正自无人尝鼎脔，不如有客办萍虀。", "庾郎三九同刍豢，野荠从教施五溪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偕少云观永乐班女伶四首 其四","p":"","d":"近代","a":"连横","c":["玉楼春帐可怜宵，剑影箫声慰寂寥。一种倾城倾国恨，桃花扇底话南朝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水口感事","p":"","d":"清代","a":"符兆纶","c":["依旧春山叫画眉，小楼无语卷帘时。五更寒雨酴醾梦，三月东风杨柳枝。", "早已伤心到金粉，忽惊满眼是旌旗。再来门巷知何似，莫问飘零沈亚之。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游丁次翁筼筜园期次翁不至","p":"","d":"宋代","a":"陈傅良","c":["径蹊曲折屋参差，半是天成半自治。修竹万竿人独立，我来搔首菊花期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日郊行","p":"","d":"清代","a":"玄烨","c":["节变春方去，清和助麦秋。蔚林乘早夏，茂草接新流。", "柳絮堤边起，荷钱水上浮。风光殊旧日，此意未曾休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"文太仆之京过定山言别诗以赠之 其二","p":"","d":"明代","a":"庄昶","c":["一笑曾蒙旧雨知，相留今果得吾师。平生邵学心徒切，老去凡庸拜悔迟。", "灯火定山聊我榻，草鞋天目更何时。白头但恐还相弃，写在溪云赠别诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荷花","p":"","d":"宋代","a":"江万里","c":["结亭临水似舟中，夜雨潇潇乱打篷。", "荷叶晓看元不湿，却疑误听五更风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"马上口占二首 其二","p":"","d":"宋代","a":"秦观","c":["霜风棱棱万木枯，梅花破萼犹含须。田家往往事游猎，追逐狐兔相号呼。", "微茫山中起狂烧，隐约林梢低日车。马头渐觉有佳趣，勿厌阡陌多萦纡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"零卉集百首 其九十七","p":"","d":"当代","a":"陈永正","c":["一梦何堪醒夕曛，馀情眷眷复成云。风凄卷幔香何在，啼笑而今渐不分。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和徐季功墨梅 其一","p":"","d":"宋代","a":"王之道","c":["閒想窥池倒影，戏成落笔斜枝。纵涅难淄玉质，细看何似当时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"凤岫春雨","p":"","d":"清代","a":"陈廷璧","c":["膏雨油然洒，名山淑景新。浮青凌碧落，含翠媚芳春。", "岫霭云根湿，天和巘影真。锦屏怜竹后，万卉净无尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留守相公移镇汉东","p":"","d":"宋代","a":"欧阳修","c":["周郊彻楚坰，旧相拥新旌。路识青山在，人今白首行。", "问农穿稻野，候节见梅英。腰组人稀识，偏应邸吏惊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小游仙词 其六","p":"","d":"元代","a":"张翥","c":["五岳真官立帐前，露芜香霭落琼筵。夜深醮罢各归去，一一马声嘶上天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠林倅","p":"","d":"宋代","a":"许应龙","c":["元是清都紫府仙，出为名世应半千。发矢两科俱中的，英名烜赫斗横天。", "鄞水富沙典芹泮，黜浮崇雅文风焕。沙阳之政宽而明，吏不忍欺民不玩。", "双飞凫舄造皇州，三台八座俱挽留。辞荣避宠姑别驾，恬退高节前无俦。", "千里提封勤赞理，恕以待人严律己。一轮秋月照无私，百尺春潭清见底。", "须知作善天降祥，俾耆而艾寿而臧。萱闱朱颜映苍鬓，诜诜兰玉如鸾翔。", "匪伊丹诏日边至，策足乌台陟端揆。年年衮绣舞莱衣，瑶池屡献蟠桃瑞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚望","p":"","d":"宋代","a":"张栻","c":["独上荒亭数过帆，横林疎处见苍湾。", "固知不入豪华眼，送与凫鸥自在看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天 乙未农历闰重三作","p":"","d":"近代","a":"龙榆生","c":["宿雨初乾雀语檐。历头喜见闰重三。回黄老树阴逾密，绣地馀花色转严。", "春昼永，午风恬。情知蔗味老来甜。颊间偎著狸奴暖，隐几攲眠懒下帘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠王介甫","p":"","d":"宋代","a":"段缝","c":["溪桥久废湮，竹树半攲侧。梦寻六代尘，老构一椽宅。", "谁知江令门，犹倒山公舄。霸气消旧朝，歌声慨陈迹。", "鼎族昔繁华，荒径今岑寂。愿言辟榛芜，重与开景色。", "石叠云自生，渠凿流不息。我幸卜公邻，望衡步咫尺。", "晨夕惬素心，把臂共悦怿。西崦带烟樵，南埭钓水食。", "底事忧怦怦，相将爱惕惕。或筑吟诗坛，或设谈经席。", "焉知才不才，聊各适其适。岸帻豁眼界，挥麈吐胸臆。", "陇晴许扶鸠，水涨可𣏾鹢。嗒然得丧忘，往事莫凄恻。", "佳会不可常，岁月岂抛掷。蒙庄赖妻贤，渊明空子责。", "弱木手自栽，勿徒嗟立壁。滋培待其成，斧削工师职。", "更为广轩亭，左右支图籍。钟山挹爽来，烟鸟纷若织。", "绿菘篱下采，金尊池上涤。此盟更岁寒，一笑星发白。", "箸力如未尽，尚能越阡陌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丰乐楼","p":"","d":"清代","a":"李符","c":["霜天正排字雁，恋樵林钓渚。典裘醉、孙楚楼头，华夫吟屐曾住。", "忆同溯、冰潮挂席，君归四百烟峰去。为寒梅，琼萼东风，乱零无主。", "我亦西游，鸟道束马，满青袍瘴雨。点苍客、才整蛮装，洞庭红照烽橹。", "纵题书、禽衔不到，黯凝睇、珊瑚洲树。著秋衣，香叠芙蓉，采兰何处。", "凌波军散，便拨荪桡，秣陵寄倦旅。画船有、比肩人载，月姊应是，笔格梳函，锦鲛绡护。", "东田翠麓，松扉堪结，漫伤前度吹箫偶。更闲寻、细草钿车路。", "离箱乍启，且翻叶叶银钩，几卷岭外新语。", "凫花一盏，蜜炬双条，话别情最苦。对寂寞、山川如此，忍听空江，拍浪声中，又催津鼓。", "残星浦口，藤鞭茸帽，诗腰鞍背人影瘦，觅金门、饥朔神仙侣。", "重来还约明年，柳碧卢沟，那时记否。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"活死人窝，为番阳胡道玄赋","p":"","d":"元代","a":"郑元祐","c":["我尝梦登天，身乘帝青云。下视六合大，死人何纷纷！", "尸行鬼走不知丑，天跳鬼踔无由分。首戴髑髅蒿两目，肠悬题凑空孤坟。", "自谓策神智，可以干明君。自谓雕纂组，可以成华文。", "自谓昭旗常，可以铭前勋。形如枯株心强活，气如湿灰耳强闻。", "哀哉腥腐窟，何以能超群？天孙为余言，此皆不足云。", "累累白骨成飞尘，安知中有不死人？眉厖喉结目如电，挥呵风雨走百神。", "塌额玉陛下，自称小兆臣。臣之形骸与众等，久断荤血腐肉皴。", "言臣不死诚谬妄，固有不死丹元君。丹元君，在何处，泥丸真人且延驻。", "一曲鸾笙五百年，死人窝里翻身去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望雨","p":"","d":"明代","a":"卢龙云","c":["入夏愁多雨，无端旱亦随。阴阳时未若，调燮事堪疑。", "蒿目忧田畯，斋心问雨师。恒旸当有尽，甘澍应无私。", "实颖将盈亩，蕃滋可后时。泽由天地泰，功薄桔槔施。", "待取禾三百，还看穗两岐。风云即欲合，草木已先知。", "幸及如时化，何言靡孑遗。题诗催雨至，却异雨催诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水月宫","p":"","d":"明代","a":"朱学熙","c":["为探灵嚣迹，先寻水月宫。慧香连斗极，花雨漫瑶空。", "犬吠白云外，僧禅翠霭中。十年迷下界，聊此息微躬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵朋元久雨","p":"","d":"宋代","a":"范成大","c":["谁酿愁霠玉宇间，都缘梅子要斓斑。", "腾腾困思午犹梦，扰扰奔云风未还。", "休问满城骑马滑，不妨长日闭门闲。", "今朝晴色熹微似，乾鹊飞来语屋山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"投梭女","p":"杂咏一百首","d":"宋代","a":"刘克庄","c":["琴挑何曾动，梭投未免惭。", "女郎循古礼，元不解清谈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水调歌头 其二 红梅","p":"","d":"宋代","a":"曹冠","c":["造物巧钟赋，新腊报花期。江梅清瘦，只是洁白逞芳姿。", "我欲超群绝类，故学仙家繁杏，秾艳映横枝。朱粉腻香脸，酒晕著冰肌。", "玉堂里，山驿畔，最希奇。谁将绛蜡笼玉，香雪染胭脂。", "好向歌台舞榭，斗取红妆娇面，偎倚韵偏宜。羌管莫吹动，风月正相知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和游金山","p":"","d":"宋代","a":"秦观","c":["江流会扬子，汹汹东南骛。", "海门划前开，金山屹中据。", "鼓锺食万指，金雘栖千柱。", "夜庭游月波，晓观抟香雾。", "天清猿鸟哀，风暗鱼龙怒。", "云物横古今，涛波阅晨暮。", "三州气色来，上下端倪露。", "伟哉元气间，此胜知谁聚。", "念昔憩精庐，登临辄忘去。", "汲新试团月，饭素羹魁芋。", "妙兴入芳藤，真境在芒屦。", "别来景暑换，寤寐经从处。", "忽蒙珠璧投，了与云峦遇。", "幽光炯肝肺，爽气森庭户。", "区中多滞念，方外饶奇趣。", "寄语山阿人，泠然行复御。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别饰道二十弟","p":"","d":"宋代","a":"晃冲之","c":["少传傅三朝气老，文章壮九州。", "赋诗资政殿，赐字太清楼。", "拔烛辞轩陛，簪花近冕旒。", "庆门吾老矣，华国汝能不。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梦中歌 其二 为白面少年歌","p":"","d":"唐代","a":"张生妻","c":["劝君酒，君莫辞。落花徒绕枝，流水无返期。莫恃少年时，少年能几时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古冈八景和叶六桐明府韵 其一 黄云樵笛","p":"","d":"明代","a":"李之世","c":["閒听风林笛一声，飞花片片递林轻。樵人指点云生处，石齿参差路未平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂七十一首 其七十","p":"","d":"宋代","a":"释了惠","c":["生于秽土，不受点污。目顾四方，周行七步。看来步步讨便宜，落水也要占乾处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题高寺丞竹","p":"","d":"明代","a":"吴宣","c":["虚怀延伫半生心，寥廓相逢恨转深。云合洞庭鱼鸟散，弦鸣清庙管鼗沉。", "吴刚月殿鸾空舞，丁令辽阳鹤错寻。馀慨欲论犹未得，天涯别后听遐音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暗香 壬子寄巢云","p":"","d":"清代","a":"陈曾寿","c":["旧痕凄断，是年时携手，虎坊桥畔。愁护暮鸦，芳树阴阴后堂见。", "还踏天街月影，乍忘了、西风冰簟。谁管他、如叶青衫，弦底玉龙怨。", "争羡，御香染。尽夜夜露痕，襟袖难浣。几时清浅，赢得铜仙泪空满。", "重觅剪灯心事，除付与、梦中庭院。却又怕、寻去也，梦中都换。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"柴关","p":"","d":"清代","a":"陈肇兴","c":["清泉白石锁柴关，豪气销残梦寐间。屈指百年惊渐老，回头万事不如閒。", "悠悠落日牛羊下，策策空林倦鸟还。唯有丹心依旧在，浮云望断海中山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南川别墅四首 其四","p":"","d":"明代","a":"林光","c":["勒马斜阳渡汉川，风波回首信天缘。身随蜀相躬耕后，心出羲爻未画前。", "玉粒香粳添日膳，草茵松榻饱宵眠。儿曹更祝公强健，尽道今年胜旧年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八月十五夜月有五色华晕二首 其二","p":"","d":"明代","a":"黄省曾","c":["满月漾昭回，澄辉穆气催。望宫华缀幕，飞镜彩妆台。", "作晕龙文杂，为图凤色开。凉风寒殿早，天锦定应裁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"姑苏馆上元前一夕陪使客观灯之集","p":"","d":"宋代","a":"杨万里","c":["节物催人又一年，银花莲炬照金尊。", "麝鎚官样陪公讌，粉茧卿风忆故园。", "何似儿孙谈草草，不妨灯火半昏昏。", "人生行止谁能料，今夕苏州看上元。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和南质张学士敏之见赠七首 其七","p":"","d":"元代","a":"耶律楚材","c":["衣龙钟，鬓飘萧，穹庐停烛坐寒宵。翰林遣介赠佳句，虿芒鸟迹书生绡。", "既倒狂澜再扶起，昔有谪仙原姓李。今日龙庭忽见君，谁道当年太白死。", "文章气象难形容，腾龙翥凤游秋空。笔力万钧神鬼泣，雷轰电掣驱疾风。", "馀裕喜君能绰绰，鼓舞为君予矍铄。解读奇字笑扬雄，识厌张华能物博。", "与君握手天山边，举觞相嘱望青天。他年雅社结白莲，林泉杖屦冲云烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄人","p":"","d":"宋代","a":"胡楚","c":["不见当年丁令威，", "年来处处是相思。", "若将此恨同芳草，", "犹恐青青有尽时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢张提学惠薏苡仁","p":"","d":"明代","a":"邵宝","c":["辟湿初闻薏苡仁，涯翁诗里见来真。东风吹送台端贶，活火山泉共作春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词","p":"","d":"宋代","a":"王仲修","c":["景阳钟动趁严妆，奉帚追随过未央。", "月落金门才放钥，御衣初试百花香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"恭次家大人初抵季弟海陵官舍之韵","p":"","d":"宋代","a":"孙应求","c":["食贫宁问肉如陵，且喜官曹简事程。", "千里平淮随地阔，一江远水照水明。", "几我怀古登临意，时作搔头讽咏声。", "酬唱敢希朱树秀，粗分菽麦异周兄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晨兴","p":"","d":"近代","a":"黄假我","c":["已成诗句墨痕干，肠热终难压胆寒。马足车尘由世路，鸡声灯火误儒冠。", "却无可却三年艾，精益求精百尺竿。一笑开轩迎杲杲，万枫叶老竞舒丹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"凭栏人","p":"","d":"元代","a":"张可久","c":["小玉栏杆月半掐，嫩绿池塘春几家。鸟啼芳树丫，燕衔黄柳花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题徐庆超春波洗砚图 其一","p":"","d":"清代","a":"梁章钜","c":["楼船横海纪殊勋，缓带轻裘又见君。一片绿波朝涤砚，满堂红烛夜论文。", "传来去病真无敌，写入丹青更不群。燕颔虎头奇相在，凌烟褒鄂漫风云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙","p":"","d":"清代","a":"汪东","c":["残绿庭阴罥䋞丝。凌晨寒雨湿阶泥。水沈笼罢更添衣。", "药铫常温妻病久，茶铛閒置客来稀。寂寥情味晚秋时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读曹明贤君蜀鹃诗稿二首 其一","p":"","d":"近代","a":"张秉衡","c":["炉灭灯残不寐时，枕旁一卷晓陶诗。老夫也是悲观派，爱听蜀鹃入夜啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庚戌九月自吴返越嘉禾道中 其二","p":"","d":"清代","a":"王拯","c":["犹有残蝉挂别枝，纺车声乱豆花篱。蘋乡又听新蛩语，寒女功裘待上机。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自题国朝诗正气集","p":"","d":"清代","a":"张应昌","c":["忠孝节义事，史传志乘详。咏叹兴感易，重此歌诗章。", "所以载笔者，联珠标群芳。英辞鼓正气，岂惟阐幽光。", "往古难尽数，断自今虞唐。醇化二百载，盛碑碣祠坊。", "但计歌诗篇，万首罗琳琅。所见择尤雅，阙者待补亡。", "一读一击节，其气至大刚。比日星河岳，如芝兰鸾皇。", "教痒塾妇孺，播管弦宫商。油然孝弟生，幡然顽懦良。", "胜彼志传文，长吟沁肝肠。愿传万本读，振世扶纲常。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闲游","p":"","d":"唐代","a":"李建勋","c":["携酒复携觞，朝朝一似忙。马谙频到路，僧借旧眠床。", "道胜他图薄，身闲白日长。扁舟动归思，高处见沧浪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙 元夕","p":"","d":"明代","a":"黄淮","c":["忆昔帝城三五夜，簪缨曾侍宸游。山移鳌背对龙楼。", "一天星斗下，万文瑞光浮。", "箫鼓声中催赐饮，归来月在帘钩。而今白发叹淹留。", "寒窗灯影里，飞梦绕瀛洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和所盘风字韵","p":"","d":"宋代","a":"丘葵","c":["二十四番花信风，到头谁白又谁红。", "寻春不用苦我感，有酒且须时一中。", "吾辈於人长落落，浮生虽梦亦匆匆。", "未知今岁沧浯上，握手论心几度同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"壬子仲冬上京族中弟侄送过石门而别 其二","p":"","d":"明代","a":"祁顺","c":["南北舟中两渺茫，相思情与海天长。隔篷侵晓闻人语，犹讶诸君在耳傍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题南国风光画册十六首 其六 停织暴衣","p":"","d":"清代","a":"吴妍因","c":["贱卖番麻贵买纱，鸳机不解织云霞。衣成且喜能勤浣，挈出清波无点瑕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"至正戊子下第南归与同贡黄章仲珍雷燧景阳同","p":"","d":"明代","a":"陶安","c":["凤城酒美燕姬歌，禁花红飘金水河。", "雨香翠岛春昼暖，鱼龙陆海扬风波。", "天门咫尺到不得，奈此飙摧云翼何。", "时乎未至应有待，壮年不必伤蹉跎。", "君看松柏成大材，历岁雪霜谁见过。", "拂衣南出指归路，回首京阙山嵯峨。", "日高原头红雾散，潮平沽口青铜磨。", "牵船溯流狂吹逆，登车避闸飞尘多。", "黄楼凭河远眺望，身如冥鸿超网罗。", "客涂笑语浣羁思，词锋捷出如挥戈。", "天生人才必用世，岂无文藻宣金科。", "鸾台凤阁总华要，不然玉署聊鸣珂。", "丈夫小挫未为辱，正气耿耿非有它。", "匣中古砚助神变，铜蟾饱水手屡摩。", "随身亦有勋业镜，依然照我颜色酡。", "与君今日动高兴，买酒共酌浇天和。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送郑尚书守建安十首 其八","p":"","d":"宋代","a":"彭龟年","c":["从此褰帷去帝乡，闾阎辛苦足平章。皂囊若有新丰奏，才过龙团第一纲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖州 其一","p":"","d":"宋代","a":"戴表元","c":["山从天目成群出，水傍太湖分港流。行遍江南清丽地，人生只合住湖州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"涵碧亭","p":"","d":"宋代","a":"葛洪","c":["雨歇留蒸湿，明来得翳凉。", "双嬉鱼欲动，万个竹添长。", "景到烦诗答，叹多厄日忙。", "兹游端胜绝，不是学高阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"嗅梅","p":"","d":"宋代","a":"范成大","c":["雪意勒花愁未解，背阴一朵寒先退。", "东风还是去年香，不比人心容易改。", "宿酒瞢腾正耐春，花枝人面两时新。", "相看好作风流伴，只恐花枝却妒人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"桂林岁晚忆钟尚书","p":"","d":"宋代","a":"乐雷发","c":["尘满湘翁薜荔衣，江湖岁晚鬓成丝。桂州杨五今何处，雪片梅花枉费诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居诗 其一","p":"","d":"明代","a":"明河","c":["东溪信非遥，咫尺篱门外。桥头看落花，昨日莺声在。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"释惠崇","c":["寒灯催臘尽，晓角唤春归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其五","p":"","d":"宋代","a":"曾纡","c":["苔侵垂磴蔓，竹隐断岩花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和刘工部钦谟无题韵 其二","p":"","d":"明代","a":"童轩","c":["金殿萤流月半沈，谩思当日宠恩深。风清香箧捐秋扇，露冷空闺急暮砧。", "别院频翻鹅管玉，长门深锁兽环金。可怜碧海青天外，谁识姮娥夜夜心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿华清宫次日又续前调寄怀","p":"浪淘沙","d":"当代","a":"吴禄贞","c":["征马歇临潼。唐代离宫。贵妃几度浴春风。遥忆沉香秋夜月，花影朦胧。", "皓月照庭中。睡梦溟濛。悲鸣寒夜怨秋鸿。想到美人离别恨，身世飞蓬。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"胡伯玉隐趣图四咏 其一 蜀锦屏","p":"","d":"元代","a":"陈樵","c":["朝看花中仙，颜色媚且鲜。暮看花中仙，颜色忽己蔫。", "红芳不足恃，青春政堪怜。人生宇宙中，寿无金石坚。", "百岁等瞬息，业火徒熬煎。何如鍊金液，返本得长年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题鬼趣图十五首 其十五","p":"","d":"近代","a":"寇梦碧","c":["逐鹿将焉托蕉叶，战龙旋复入槐根。此中安得王延寿，为我挥刀斩梦魂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五鼓才成","p":"行香子","d":"元代","a":"王哲","c":["五鼓才成，土德行香。偏能将、四象包藏。如今尽显，聚在中央。没白归青，红归黑，不归黄。已证空虚，便出昆冈。金童来、秘语宣扬。天皇赐韶，授与风狂。永处清闲，常清静，得清凉。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"木兰花慢","p":"","d":"元代","a":"王丹桂","c":["叹滔滔苦海，任群迷，恣漂游。被有限形躯，无涯爱欲，一向拘囚。", "空生万千计较，况百年、短景不常留。贪为名深利切，岂期水远山悠。", "如流。岁月相催，宜省悟，觅抽头。向太一峰前，双林树下，早把心收。", "从来既知是错，待番番、放下便休休。撒手纵横无碍，状同不系之舟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百一十七首 其三十九","p":"","d":"宋代","a":"释绍昙","c":["独坐大雄峰，临机多弄险。遭虎口杀活不分，脱狐身真假难辨。", "那堪创立清规，平地深深坑堑。结成不共戴天雠，烧炷枫香解释休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过田中有感","p":"","d":"明代","a":"朱诚泳","c":["小人不可用，用则妨善良。稂莠不可容，容则嘉谷伤。", "所以田家父，耘锄日皇皇。四体苦胼胝，仅得充饥肠。", "奈何治家国，而不谨其防。悠悠感前史，披书徒自伤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辟疆书然弟病中语览之泫然","p":"","d":"清代","a":"王易","c":["檐霜檽雨放秋回，短景难消蚁磨催。袖手江湖天更迥，惊心骨肉梦成灰。", "似随飞鸟去无迹，欲上高山呼不来。坏壁应多旧题在，劳君偏写喘丝哀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题项处士山堂二首 其二","p":"","d":"宋代","a":"陈造","c":["久安楚俗眠云屋，又向吴侬倒药囊。出处无心俱乐地，世间何处不山堂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"疏影 梅景书屋","p":"","d":"清代","a":"吴湖帆","c":["春温绣幄。有暗香冉冉，霏雾轻扑。莫道珍禽，明月来时，于中消收清福。", "绿窗却展横斜影，任合指、癯仙铃索。纵一枝、觅取幽芳，不似喜神浓馥。", "休羡牙签万轴，凭肩且笑语，孤本双读。午梦初回，额上花痕，依旧翻新妆束。", "冰姿绰约苕川谱，映雪里、可人如玉。问几生、修到同心，好贮阿娇金屋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汪扶晨六十有赠 其二","p":"","d":"明代","a":"屈大均","c":["老友稀江左，年龄尽与君。无才真大药，有道总浮云。", "得草麑相命，逢花鹤不分。未知潜口路，多少桂丛薰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵杨柳枝词","p":"","d":"明代","a":"杭济","c":["东风袅袅拂朱阑，万树千条露未干。", "玉涘声中人不见，倚楼烟雨正春寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙（梅菁山遇雪）","p":"","d":"宋代","a":"李洪","c":["矢矫翔鸾谿上峰。飘萧雪霰打船篷。天花凌乱水晶宫。", "飞透纸窗斜取势，吹回谿面舞因风。身游水墨画图中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮 其十七","p":"","d":"当代","a":"黄绮","c":["晓来微雨藤花紫。黄莺不语东风起。独立思江天。岸平多草烟。", "闲云无定貌。乡思巢枝鸟。云水是天涯。未应伤物华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋蕊香","p":"","d":"宋代","a":"佚名","c":["眼也生应哭破。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"衡永之间山路艰涩薄晚吏卒鬨云渐近祁阳路已平夷皆有津津之色","p":"","d":"宋代","a":"范成大","c":["朝登赤土岭，暮入黄泥谷。春江弄花月，归梦恍在目。", "觉来行路难，杜宇叫高木。凹中泥没踝，凸处石齧足。", "坐舆我尚病，想见肩舆仆。衡阳复祁阳，可暂不可宿。", "晚来出前冈，路坦亭堠促。将士走相贺，喜色如膏沐。", "人生本无闷，逆境要先熟。不从忧患来，安识平为福。", "夷涂不常遇，历险始知足。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西湖","p":"朝天子","d":"元代","a":"徐再思","c":["里湖，外湖，无处是无春处。真山真水真画图，一片玲珑玉。宜酒宜诗，宜晴宜雨，销金锅锦绣窟。老苏，老逋，杨柳堤梅开墓。"],"tags":["写景", "西湖", "喜悦"],"z":"","y":"","s":"","k":"诗"},
  {"t":"苍龙吟","p":"","d":"元代","a":"周巽","c":["江潭月冷流清音。紫竹吹作苍龙吟。含商引徵曲意深。", "曲意深，泪沾襟。关山远，何处寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"翠凉","p":"","d":"宋代","a":"胡仲弓","c":["各章古木影萧森，未必山林如许深。", "才见眼前成绿暗，一年又负种花心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送殷孝章之咸阳教谕","p":"","d":"明代","a":"秦约","c":["西上长安跋涉劳，三千里外朔风号。地连渭水秦川近，山接终南泰华高。", "故国总消龙虎气，断碑犹打骆驼膏。一官莫笑儒林选，曾捧琅函觐赭袍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿悦斋李先生","p":"","d":"宋代","a":"程公许","c":["君不见温公崇福十五年，上下千载书法岩。", "又不见蜀公静退不待耄，钟律制成天一笑。", "乐则行之忧则远，出处无非圣之时。", "一朝都人拥马首，留相天子不得辞。", "颍昌胡为几不动，各以就去揭榘仪。", "悦斋先生天下士，琬琰琮璜国镇瑞。", "盛名姱节耀古今年内，岁晚松阶犹候对。", "时台剧谈锯蜚屑，志堂析疑{上竹下氐}启钥。", "夜归风雨一龛灯，目电窥书光烁烁。", "禹贡山川如指掌，漆园之解无郭象。", "更将次五订箕畴，不妨后觉勤鑽仰。", "年来岷峨殊怆悽，公与洁斋名德齐。", "长康磊配晓月，士有司命国蔡蓍。", "卧架诗书差足乐，凭高忍见楚氛恶。", "岂不望公勇拂衣，正恐百姓须公活。", "愿公相业追无佑，以一至诚服雄狡。", "愿公眉寿如东轩，黄发皤皤国元老。", "云蒸雨族沛作霖，贤以类聚治乃兴。", "卷舒在公亦何心，四海矫首四山岑。", "薰风自南一披襟，起舞称寿千黄金。", "洗耳五弦虞氏琴，为公缓轸歌嗣音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莫宪使补官楚臬继参梁岳奉赠","p":"","d":"明代","a":"皇甫汸","c":["闻道除书下紫宸，沧江猿鹤恋征轮。共怜潘令閒居久，可讶山公荐启频。", "湘浦兰芳违赠远，河阳花色待行春。汉廷典礼须君草，讵作梁园授简人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"适得滷颇佳遣饷菊坡因记曾作蛤子诗有文身吴","p":"","d":"宋代","a":"郑清之","c":["文身太伯甘斥卤，缄口铜人舌微吐。", "借资墨客富濡沫，骨醉唇香登燕俎。", "半熟含酒老饕赋，此翁仅可闯堂户。", "班班隽永带神液，入室真味翁未睹。", "菊坡风裁黄豫章，如食蝤蛑江{摇扌换虫}柱。", "盘餐尽废太瘦生，格远调高自清苦。", "子蛤遣汝到眉案，努力去为酒中虎。", "末下鹹豉有何好，犹侣莼羹傲伧父。", "海之介夫此小儿，鸡肋见笑杨德祖。", "前身曾作水解仙，飞入珠宫饮甘露。", "能令齿吻策余烈，一鼎松风漱寒乳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暮春苦雨即事","p":"","d":"清代","a":"德日","c":["年来惟有感伤多，九十春光总浪过。镜里容颜空自老，梦中诗句为谁哦。", "飞花满院销银蜡，细雨空帘锁黛蛾。可惜繁华零落尽，香残酒冷奈愁何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"癸酉除夜呈邻舍刘秀才","p":"","d":"宋代","a":"郭祥正","c":["六十明朝是，今年此夜除。劳生一樽酒，陈事数行书。", "腊逐灯缸尽，春回律管初。不愁家信断，安稳藉邻居。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪中寄令狐相公，兼呈梦得","p":"","d":"唐代","a":"白居易","c":["兔园春雪梁王会，想对金罍咏玉尘。", "今日相如身在此，不知客右坐何人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送卢章侯年丈罗定应试","p":"","d":"明代","a":"张嗣纲","c":["弯孤策杖耀威风，名冠时流自不同。幕府定应虚左席，诸曹何敢望前戎。", "拟将长技穿杨绿，况复精忠贯日红。此去纪昌知遇早，看君千骑即飞雄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洞仙歌","p":"","d":"当代","a":"卢青山","c":["少年意气，只爱登楼阅。何事悲凉为飘叶？趁悠閒、先生不欲孤行，正无奈、随挽人间秋色。", "拈诗如吐纳，留亦奚为？散与西风争扯拽。此心到处悠然，醉卧东篱，问谁识、庄生蝴蝶？", "到醒处一身露如淋，又懒整青衫，浩歌带月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"灵芝寺避暑因携茶具汎湖共成十绝","p":"","d":"宋代","a":"张镃","c":["城里今年热异常，出城肃寺未全凉。", "发毛吹尽人间暑，除是芙蕖十里香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其八","p":"","d":"明代","a":"胡应麟","c":["九折王阳道，千秋大隐庐。云山容负笈，宇宙碍驱车。", "业岂门人尽，名犹国士馀。凭将一掬泪，遍洒越山隅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐","p":"","d":"宋代","a":"刘翰","c":["萋萋芳草。怨得王孙老。瘦损腰围罗带小。长是锦书来少。", "玉箫吹落梅花。晓寒犹透轻纱。惊起半屏幽梦，小窗淡月啼鸦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"午睡","p":"","d":"宋代","a":"舒邦佐","c":["博山烟断懒重添，屋角无声雀去檐。午梦欲成鸡唤醒，卧看修竹映疏帘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饮振之馆限韵","p":"","d":"明代","a":"顾璘","c":["高馆临槐柏，清筵引桂觞。淮南秋望迥，江左故欢长。", "气色琼枝映，词华翰墨香。只应今夕会，星聚比陈乡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"静观楼成众山忽见","p":"","d":"明代","a":"王鏊","c":["山居尽日不见山，楼上山来自何处。中峰独立群峰随，头角森森出林树。", "澄湖万顷从中来，浪捲三山欲飞去。得非奋迅从地出，无乃飞腾自天下。", "我来楼上何所为，长日观山与山语。东风吹醉还吹醒，山自为宾我为主。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"越王楼送高梓州入朝","p":"","d":"唐代","a":"薛逢","c":["乘递初登建外州，倾心喜事富人侯。让当游艺依仁日，", "便到攀辕卧辙秋。容听巴歌消子夜，许陪仙躅上危楼。", "欲知恨恋情深处，听取长江旦暮流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沁园春 眉","p":"","d":"清代","a":"孙云凤","c":["纤似蛾儿，翠分螺子，柳叶半弯。忆锦屏娇倚，月横秋水，绣衾慵起，雾锁春山。", "翻谱鲜新，入时深浅，女伴端详可否间。消魂处、向碧纱窗下，画了重看。", "含情醉拨幺弦。觉红泛桃腮黛更妍。但倾城一笑，舒来堪爱，捧心无语，颦亦增怜。", "秀衬风鬟，长侵云鬓，昔日文君欲比肩。风流甚，怕脂凝粉污，淡扫朝天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谒郭道冲唐师德登台偶作","p":"","d":"唐代","a":"朱长文","c":["冲寒步郊原，烟水照林薄。", "雪余山色佳，浦浚湖波落。", "静可钓纶垂，清欲尘缨濯。", "相逢两俊友，辞义富金臒。", "携手登高台，谈笑有真乐。", "寸眸周远近，幽思腾寥廓。", "逝将飞片帆，直泛洞庭脚。", "絷维阻并游。搔首向城郭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗","p":"","d":"宋代","a":"吕陶","c":["夕阴敛层空，素月出西海。寥寥俯仰间，杳不见纤霭。", "清光信可掬，璀璨掌握内。虚庭纵远目，中夜如有待。", "念我金石交，轻别己十载。德音响球琳，道味芬兰茝。", "悠然阻声容，况复接言诲。幽怀愿一写，四顾多泛爱。", "回头自珍惜，欲显不如晦。赖此秋蟾魄，千里共光彩。", "思贤摇去意，对景慕良会。此夕虽圆明，清赏君何在。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"昼寒亭","p":"","d":"宋代","a":"韩元吉","c":["月里琼宫不禁寒，谁令白昼堕人间。", "阴风淅淅来深谷，晴雪霏霏溅雨山。", "静爱飞流聊洗耳，坐看绝磴可怡颜。", "红尘势客那知此，赤脚青松意自閒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"家园卧疾毕太祝曜见寻①","p":"","d":"唐代","a":"孟浩然","c":["伏枕旧游旷，笙歌劳梦思。②", "平生重交结，迨此令人疑。", "冰室无暖气，炎云空赫曦。③", "隙驹不暂驻，日听凉禅悲。", "壮图哀未立，斑白恨吾衰。④", "夫子自南楚，缅怀嵩汝期。⑤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题画","p":"","d":"明代","a":"庄昶","c":["远山青两峰，老树红一叶。我怀不可羁，空江下明月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日诸季散处长乐外邑怅然有怀二首 其一","p":"","d":"宋代","a":"李纲","c":["去岁初从海上回，重阳相与醉高台。那因寇盗迁南土，阻插茱萸共一杯。", "老矣但思情话切，跫然更望足音来。黄花也解知人意，故向篱边未肯开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂咏遣怀六首 其四","p":"","d":"明代","a":"苏葵","c":["怀中明月何曾暗，意里阳春不□寒。三十六宫天地迥，自家来往自家看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋得吴王送女潮歌，送李判官之河中府","p":"","d":"唐代","a":"皎然","c":["见说吴王送女时，行宫直到荆溪口。溪上千年送女潮，", "为感吴王至今有。乃知昔人由志诚，流水无情翻有情。", "平波忽起二三尺，此上疑与神仙宅。今人犹望荆之湄，", "长令望者增所思。吴王已殁女不返，潮水无情那有期。", "溪草何草号帝女，溪竹何竹号湘妃。灵涛旦暮自堪伤，", "的烁婵娟又争发。客归千里自兹始，览古高歌感行子。", "不知别后相见期，君意何如此潮水。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高骈、薛涛","p":"","d":"唐代","a":"佚名","c":["口，有似没量斗。（高骈）", "川，有似三条椽。（薛涛）"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"普缘塔","p":"","d":"明代","a":"何景明","c":["石盖凌空起，丹梯出翠微。云从珠顶覆，灯转镜中辉。", "雁沼波涛涌，龙宫日月围。何能攀绝顶，一览汉邦畿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"客珠崖怀罗浮寄山中诸子三十韵 其六","p":"","d":"明代","a":"成鹫","c":["溪山非舌亦非身，久去重来见益亲。四百峰中开别院，三千里外结芳邻。", "苔生碧砌青如染，镜锁明窗净不尘。为报诸方参学者，罗浮深处近无人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆秦娥 其一 梅","p":"","d":"明代","a":"俞彦","c":["春寒熟。溪梅已绽枝头玉。枝头玉。照人明媚，殢人芬馥。", "东皇为我怜幽独。小楼细雨眠初足。眠初足。一番花信，一番裀褥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题西湖亭子寄徐复初简校","p":"","d":"元代","a":"乌贝勒图","c":["芙蓉花开一万顷，钱塘最好是湖边。晓风得酒更留月，春水到门还放船。", "笙引凤凰天上曲，赋裁鹦鹉座中贤。令人却忆徐公子，深阁焚香日晏眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江上","p":"","d":"宋代","a":"释文珦","c":["无柰春芳损客心，每於江上独行吟。", "朝朝莫莫寒潮水，不似归愁一度深。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"论语绝句一百首","p":"","d":"宋代","a":"张九成","c":["谦抑从来不务争，於人唯恐的真情。", "若於礼义愆违处，安得区区学面朋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荔枝","p":"","d":"宋代","a":"张舜民","c":["柳江六月水如汤，江边荔枝红且黄。", "摘时须是带枝叶，满盘璀璨堆琳瑯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"相见欢","p":"","d":"清代","a":"濮文绮","c":["匆匆又过清明。月黄昏。那处绿杨庭院、落花深。", "已别去。总无计。苦叮咛。可是六朝春梦、未醒人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岁残风雨满腹牢骚，拈笔长吟藉舒沈闷二首 其一","p":"","d":"清代","a":"王德爵","c":["西风残柝满城哀，挑尽青镫百感来。绿柳何堪经雨雪，紫云深悔出蓬莱。", "此生事业惟酬梦，来世天公莫派才。自愿无知如草木，和烟和雨老黄埃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪消","p":"","d":"明代","a":"陶望龄","c":["柔姿能耐几时消，况是春来腊后飘。", "晓幕薄寒飞旋湿，夜窗多恨滴无憀。", "风前赵女愁堪诉，老去郎颜鬓易凋。", "惟有山梅解相惜，深崖铁干锁冰条。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山园示游人","p":"","d":"明代","a":"王世贞","c":["携酒看花不碍频，唯求酒后护残春。", "不辞树树凭攀折，孤却明朝花下人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"铅山道中","p":"","d":"宋代","a":"李纲","c":["行李踰江峤，风烟接武夷。地灵嘉木秀，天阔暝云垂。", "泉石日相乐，雪霜寒自迟。寄声山下士，扫壁待题诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"屈指归来日效白体七首 其六","p":"","d":"明代","a":"毕自严","c":["屈指归来日，荒园满绿苔。夷犹堪得句，放浪可衔杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"对瀑","p":"","d":"清代","a":"弘历","c":["昨夜秋雨飞千山，湢湱飒沓喧冈峦。隔窗檐溜已落瀑，真瀑翻在想像间。", "今朝快霁澄浮烟，是声皆寂惟瀑悬。乃知幻者有作歇，何如真者恒当前。", "我每对瀑率得句，欣兹会心有别趣。四柱虚亭百尺崖，让他常住无来去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"定林院昭文斋","p":"","d":"宋代","a":"王安石","c":["定林斋后鸣禽散，只有提壶守屋檐。苦劝道人沽美酒，不应无意引陶潜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题清风岭王氏烈女祠","p":"","d":"明代","a":"李昱","c":["犹闻虎旅下天戈，庙宇经年长薜萝。玳瑁簪斜蛛网密，石榴裙短燕泥多。", "即于白刃全吾操，为至清风奈尔何。赖有篇诗畹血迹，清名不废逐江波。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"诸虫名呼被于人事因据为义者凡八物各赋一章 其二 猾","p":"","d":"明代","a":"倪元璐","c":["从无肉离骨，可信是甘柔。蝮子贻蛇患，桃虫通鸟谋。", "智囊瘿是毒，警枕梦如流。想见李林甫，蜂脂铸镯镂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"明月池","p":"","d":"清代","a":"敖启潜","c":["尔雅台前月，流光到墨池。苔痕相映碧，犹忆注经时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙 其二","p":"","d":"当代","a":"周燕婷","c":["羞向人前说脊令，惊风吹散旧时情。当时有月透窗棂。", "落尽梨花怜寂寞，难为枫叶耐飘零。圆圆晴月又当庭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟夜不寐怀直夫","p":"","d":"清代","a":"唐树义","c":["几年踪迹赋江蓠，四海论交说共谁。别后更无诗可读，近来惟有月相随。", "曾游五岳君真健，不负千秋我所思。记取长安风雨夜，一樽清对数吟髭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮　 其五 回文","p":"","d":"清代","a":"丁澎","c":["数重花幔穿金缕。缕金穿幔花重数。愁处是高楼。楼高是处愁。", "凤钗横压梦。梦压横钗凤。通梦两心同。同心两梦通。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"邢州别于鳞 其一","p":"","d":"明代","a":"王世贞","c":["西来天地坼，无恙太行城。二子狂歌发，千山秋思生。", "世人殊黯淡，何物与纵横。不独文章在，兼齐拙宦名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖村八景 其二 绮岫云来","p":"","d":"清代","a":"徐搢珊","c":["先人卜筑意何深，常与南山共古今。翠嶂遥观时独坐，白云相对寄长吟。", "从龙变化非无志，护鹤勾留恰有心。更喜游行情似我，不嫌日日到西林。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洪参戎和平大捷喜而有赠 其二","p":"","d":"明代","a":"叶春及","c":["飞将分符出，提戈奏凯回。裹尸真国士，推毂岂时才。", "列队蛇矛动，前驱鹭鼓催。汉庭多宠渥，陆贾是功魁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长亭怨","p":"","d":"清代","a":"谭献","c":["看春老、飞花飞絮。燕子来时，绿窗朱户。不浣闲愁，漫煎离恨奈何许。", "妾魂销矣，最恨是、沙头树。相送客舟行，却不道、天涯从此。", "欲暮。想征衫乍解，双袖泪痕无数。玉环锦带，是纤手、背人亲付。", "算此后、步步关情，似花发、空阶无主。更不遣、分明凄断，柔肠一缕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"孟夏雨后寄黍谷弟园居 其一","p":"","d":"清代","a":"钱陆灿","c":["缅想前贤咏五君，同堂能不感离群。礼无大树留三宿，诗有长城张一军。", "独夜完完心上月，相思袅袅望中云。传言二子非凡鸟，我马玄黄日易曛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渔家傲 其二 闲居","p":"","d":"明代","a":"梁清标","c":["朝霁窥窗三径晓。草堂昼静闻啼鸟。插懂编篱随意好。", "云自到。落英一任西风扫。", "啜茗摊书尘事少。开残黄菊寒催早。蚁战蜂围何日了。", "青门道。回头不满山人笑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜行溪谷间梅花迎路香影离离可爱","p":"","d":"元代","a":"柳贯","c":["暝投村径绕羊肠，离立江梅似雁行。冷蕊微开初的皪，繁枝乱插更凄凉。", "苍烟挂树多疑梦，淡月窥林稍觉香。正为先生行役苦，故留皴玉荐奚囊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日闲居并序","p":"","d":"魏晋","a":"陶潜","c":["世短意恒多，斯人乐久生。日月依辰至，举俗爱其名。", "露凄暄风息，气澈天象明。往燕无遗影，来雁有馀声。", "酒能祛百虑，菊解制颓龄。如何蓬庐士，空视时运倾！", "尘爵耻虚罍，寒华徒自荣。敛襟独闲谣，缅焉起深情。", "栖迟固多娱，淹留岂无成？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乌鲁木齐杂诗之风土 其二","p":"","d":"清代","a":"纪昀","c":["万家烟火暖云蒸，销尽天山太古冰。腊雪清晨题牍背，红丝砚水不曾凝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠拆字嗅衣相士","p":"","d":"宋代","a":"文天祥","c":["水水坎离紫阳怪，滑波皮骨长坡骇。", "解州得解解中胶，费家封铺同一解。", "唫字从金诗反穷，贝何为分田何同。", "黄绢幼妇我自乐，竹犬多事鸦鹤翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏海棠","p":"","d":"宋代","a":"于倞","c":["和风春满园，草木皆芳薰。", "君看十八叶，具与凡卉群。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"张助甫席上同吴峻伯白伯伦再饯朱主客南还赋得江飞兢渡日草见踏青心十韵 其三","p":"","d":"明代","a":"宗臣","c":["夜夜歌阳春，青皇失其柄。君携瑶草归，蘼芜孰敢兢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望宸阁雪后","p":"","d":"宋代","a":"韩琦","c":["重阴初释六花残，试倚危栏一望看。魂爽顿如居物外，句新难得上毫端。", "酒收豪席珊瑚碎，风刮仙盘沆瀣乾。化就兜罗绵世界，鹫宫高插白云寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乐隐为尹克俊赋","p":"","d":"明代","a":"萧镃","c":["行爱溪中水，坐爱溪上山。富贵非所愿，悠然心自闲。", "地偏轮鞅稀，蓬门昼常关。清风天外来，入我窗牖间。", "岂无一尊酒，可以销忧颜。叶落惊秋徂，鸟啼知春还。", "既忘是与非，宁复虞险艰。雅志固如此，高踪可安攀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"罗浮何君祐夫相访惠诗又出所作水墨鱼戏题卷末","p":"","d":"宋代","a":"李昴英","c":["山头钓引千钧鱼，铁桥曾逢稚川奴。风波平地误点额，戏取墨汁翻模糊。", "纵观濠上契妙趣，浩浩胸次涵江湖。墨云忽从砚池起，拨剌跳出形模殊。", "大鱼腾骧撼风雨，小鱼琐碎游荇蒲。技如元放几许奇，金盘一个松江鲈。", "试张亭前涨波影，舂锄飞下傍睢盱。世间画史少活笔，描写终类鲋肆枯。", "文溪一湾浮钓徒，欠得龙眠为严濑羊裘图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哀淮人","p":"","d":"清代","a":"严允肇","c":["驱车适海岱，日暮行人愁。饿夫相枕藉，老弱罗道周。", "挥涕前致词，淮楚是吾州。渠穿广陵道，水纳黄河流。", "舳舻来吴会，东北通咽喉。一朝河岸决，漫衍东南陬。", "百万为鱼鳖，何论田与畴！窜身来此方，苟活同蜉蝣。", "此方又荒旱，赤地谁锄耰？官吏责富户，朘削如仇雠。", "财赋一以空，猗顿皆黔娄。两地总困厄，一死夫何尤。", "听此肠寸结，泪下不可收。寄语当路子，闭籴非良谋。", "嗷嗷累千万，生理真可忧。昔闻富郑公，劝民贮乾糇。", "所在发廪给，去往俱自由。公私虽两困，危急庶有瘳。", "万邦苦饥溺，安饱亦足羞。何时灾沴息，躬耕乐行休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"斋居偶作","p":"","d":"唐代","a":"白居易","c":["童子装炉火，行添一炷香。老翁持麈尾，坐拂半张床。", "卷缦看天色，移斋近日阳。甘鲜新饼果，稳暖旧衣裳。", "止足安生理，悠闲乐性场。是非一以遣，动静百无妨。", "岂有物相累，兼无情可忘。不须忧老病，心是自医王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题画四首 其二 新水","p":"","d":"金朝","a":"王寂","c":["徐郎生别一酸辛，破镜还将泪粉匀。纵使三年不言笑，祇应学得息夫人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和子瞻濠州七绝 浮山洞","p":"","d":"宋代","a":"苏辙","c":["洞府元依水面开，秋潮每到洞门回。幽人燕坐门前石，长看长淮船去来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"泉州北藏院见初荷华","p":"","d":"宋代","a":"蔡襄","c":["初华才过小荷身，晓露沾红点点匀。", "莫为愁心偏倚望，清江元有未归人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"白鹭鹚","p":"","d":"唐代","a":"李白","c":["白鹭下秋水，孤飞如坠霜。心闲且未去，独立沙洲傍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秦楼月（咏睡香）","p":"","d":"宋代","a":"赵彦端","c":["香蔌蔌。小山丛桂烘温玉。烘温玉。酒愁花暗，沈腰如束。", "烦君剩与阳春曲。为君细拂衾罗馥。衾罗馥。一春幽梦，与君相续。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大人筑室将毕道祖亦作宅基治园作四诗示道祖 其三","p":"","d":"宋代","a":"葛立方","c":["两第屹相向，幽园卑辟彊。君方林上坞，吾亦沼横洋。", "凿翠辟窗户，入天栖栋梁。东屯寒月夜，老杜只茅堂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"田侍郎 其七","p":"","d":"唐代","a":"王建","c":["笳声万里动燕山，草白天清塞马闲。触处不如别处乐，可怜秋月照江关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"贫居自述 其八十四","p":"","d":"明代","a":"李孔修","c":["欲从何处避风波，倚竹依松结草窝。两字利名羁不得，一生贫窭奈无何。", "酒当欢处忘资少，诗到难吟逸兴多。烟水云山从我乐，渔歌唱罢唱樵歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂七十六首","p":"","d":"宋代","a":"释师观","c":["蓦然平地一声雷，惊得蟭螟眼豁开。", "是圣是凡俱不立，何妨随处舞三台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜坐因观杨伯虎和春字韵诗偶成五绝再寄 其二","p":"","d":"宋代","a":"张镃","c":["案上因翻简铁堆，亲朋何日和诗回。高怀剩得清閒力，满纸溪山秀色开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送士昂蒋主事","p":"","d":"明代","a":"陈琏","c":["九载稽勋政已成，缙绅祖饯出都城。钟山雨过云无迹，沧海潮来江有声。", "行见庙堂膺重寄，要期竹帛著芳名。久知献纳才华盛，伫听朝阳有凤鸣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠王韬庵二首 其二","p":"","d":"近代","a":"杨寿杓","c":["昨夜高轩过，今朝李贺诗。论文知己少，怀刺谒君迟。", "词赋哀中岁，千戈累昔时。风尘一掬泪，挥洒莫相疑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送傅越石都官归越州待阙","p":"","d":"宋代","a":"梅尧臣","c":["越客舟从真定至，夜夜镜湖生梦寐。", "晓度吴江百尺船，洗眼重看会稽翠。", "买臣负薪樵径荒，伯鸾赁舂苔臼弃。", "绿橘黄柑带叶收，白粳紫蟹侵霜馈。", "食蟹易美粳易饱，绿橘佐酒柑佐醉。", "莫论仕宦远与近，布袍练袍何所利。", "君恬不忍乞丐为，且返故庐聊以迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠范子","p":"","d":"明代","a":"皇甫汸","c":["在昔纪高士，遐哉举逸民。始知弓旌代，乃有岩壑人。", "范子秉兹尚，非病自云贫。结庐灵山曲，垂竿胥水滨。", "绪年习道论，游方狎隐沦。披裘忽过夏，采药已载春。", "雨漂庭下麦，风落甑中尘。为颂幽贞吉，庶宣皇化淳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庚辰春沪上行赠温泽远师弟","p":"","d":"当代","a":"张海鸥","c":["温公廊庙具，气宇最轩昂。辽海青春好，申城岁月忙。", "小白长红女，飘作澳洲香。青浦年年柳，长亭岁岁霜。", "浩荡孤鸿志，江畔独彷徨。幸有数编书，夜夜慰衷肠。", "南园旦复旦，师友觞复觞。论道常写意，清歌总绕梁。", "苏州觅书苦，饥渴坐路旁。大言今古事，小店乞清汤。", "心富乾坤大，囊羞雅趣长。沧桑惜日月，我辈重文章。", "人间忽如梦，樽酒细细尝。且将千种意，聊寄小白杨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋草四首 其四","p":"","d":"近代","a":"杨味云","c":["霜风吹到寸心枯，一碧如烟淡欲无。逋客北山羞薜荔，骚人南国怨蘼芜。", "荒陵冷落虾蟆鼓，旧院飘零蛱蝶图。昔日繁华都阅尽，青袍颜色也模糊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陪徐渊子使君登白雪楼约各赋一诗必以宋玉石","p":"","d":"宋代","a":"戴复古","c":["楼名白雪因词胜，千古江山春雨馀。", "宋玉遗踪两苍石，莫愁居处一荒墟。", "风横烟艇客呼渡，水落沙洲人网鱼。", "借问风流贤太守，孟亭添得野夫无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乌夜啼","p":"","d":"清代","a":"王时翔","c":["斜月斜风庭院，轻寒轻暖时光。闲行踏遍空阶藓，暗忆杜秋娘。", "一霎吹兰低语，柳金梨雪花房。乳莺啼破东阑，梦尽勾换凄凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与同馆戏续前韵 其七","p":"","d":"元代","a":"吴当","c":["尘眼争看楚俗傩，书灯独对汉时驼。歌声无复渔家傲，处处金章换绿蓑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吴子珍登仕避地大宁示诗赓韵以谢","p":"","d":"宋代","a":"何文季","c":["雁行声价压朋俦，凛凛词锋炯二矛。宝剑神光埋不住，夜冲星斗落旄头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王孟箕明府之留都水部次日逢重九同曾时甫凤栖岩登高四首 其四","p":"","d":"明代","a":"林熙春","c":["圣世乘槎客，凭陵作赋才。人间九月节，天上一封来。", "舄履寒霜湿，登临曙色开。青山陪去棹，长啸且徘徊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答清源林生","p":"","d":"明代","a":"卢龙云","c":["凤凰鸣昆丘，太液奋鸿鹄。鸒斯蒿下飞，羽翼何局促。", "人生各有志，小大随所欲。古来贤达流，振响遗空谷。", "昔余在弱龄，抗志薄时俗。旅游二十春，蹉跎守雌伏。", "南北万里遥，风尘徒仆仆。燕赵齐鲁墟，周行至海曲。", "政简讼还稀，幸不迷按牍。公暇寡所营，游神辄汗竹。", "探讨多会心，俯仰意恒触。微吟但自舒，何知炫群玉。", "羡子志不凡，千古慕芳躅。匪我平生亲，声气特相属。", "持论迥时流，摛文复纷郁。倾盖义已投，稽疑念弥笃。", "寡陋愧前闻，于尔何能淑。淡交惟若斯，相期善自勖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"住芨芨台，大风雪，呈乐彦亭将军","p":"","d":"清代","a":"杨炳坤","c":["大雪满弓衣，劳人塞上归。朔风号万窍，冷月晕重围。", "白首神偏旺，丹心愿讵违。龙泉犹在匣，破壁几时飞？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀亦好园钓矶寄仲文季直二弟","p":"","d":"宋代","a":"喻良能","c":["磬湖雨过漾清波，古岸秋来长薜萝。", "问讯石君无恙否，试烦著手为摩挲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蕃女怨 其二","p":"","d":"清代","a":"毛奇龄","c":["胡腾起作石国语。愁杀番女。罽靴尖，铜带软。蹴踏宛转。", "回头忽忆旧安西。两眉低。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又次徐仲宗通判韵","p":"","d":"宋代","a":"楼钥","c":["老龙破蛰斩幽关，乱滴天飘不复悭。", "可但甘霖驱旱魃，自然凉气满人寰。", "民心徒切焦熬甚，神力毋劳指顾间。", "遥想清都应表贺，紫宸轩陛晓催班。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别岁","p":"","d":"宋代","a":"释德洪","c":["新岁压已至，旧岁去不迟。我尚留不住，石火那能追。", "不知岁所在，凫雏喧水涯。父老相邀迓，年年知此时。", "梅花只落尽，又见春水肥。我本无欣喜，何尝有戚悲。", "想见君饮酣，一举时一辞。春容尚能老，此身那不衰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东武怀古 其四","p":"","d":"明代","a":"周亮工","c":["嵯峨岩壑苦跻攀，大海南遵第几湾。客况驼头东莞郡，归心雁背穆陵关。", "琅玡赤映方升日，泰岱青分未了山。老鬓羞惭霜雪满，长淮路近不知还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"樱花花下作 其四","p":"","d":"清代","a":"郑孝胥","c":["看到繁枝处处开，韶光骀荡锦成堆。春归沧海刚三月，骨醉东风又一回。", "花气连云收暮雨，涛声催昼送轻雷。道人摩眼空吟望，无复当年侧艳才。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大风连夜起七首 其七","p":"","d":"清代","a":"吴妍因","c":["大风连夜起，草阁欲鹏飞。盍展垂天翼，逍遥复北归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"欲再过子进昆仲舟人绐以迷路既远不能复也怅然怀之","p":"","d":"宋代","a":"赵蕃","c":["数亩湖边宅，千篇海内诗。机心谢鸥鸟，乐事付埙篪。", "艇子思重过，流行竟莫知。吾侪俱老矣，怅望复来期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏蛱蝶","p":"","d":"明代","a":"释今沼","c":["春色日芳菲，逍遥邻院归。扑竹添新粉，飞花点素衣。", "随风过别浦，曝日向南枝。暗惜双飞处，芳华今未稀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆故园 其八","p":"","d":"明代","a":"苏升","c":["玉河桥畔柳条析，翠色依稀欲染人。安得竹林行乐者，暂时相赏一相亲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望湘人 二十八岁生日","p":"","d":"当代","a":"汪岳尊","c":["指碧阴庭角，又坠桐花，年芳匆匆如许。短墨闲磨，长萧懒和，怕触隔年悲绪。", "树静惊风，楼高泣月，问天无语。把幽忧、消向愁吟，青剩鬓丝几缕。", "休话良辰欣度。愧悬弧壮志，而今都负。念猿鸟心情，只合林泉容与。", "一樽浅醉，双扉低掩，坐对孟光荆布。倚修竹、自谱清词，忘却忍见溽暑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南都妙峰亭","p":"","d":"宋代","a":"苏轼","c":["千寻挂云阙，十顷含风湾。", "开门弄清泚，照见双铜钚。", "池台半禾黍，桃李余榛菅。", "无人肯回首，日暮车班班。", "史君非世人，心与古佛闲。", "时邀声利客，来洗尘埃颜。", "新亭在东阜，飞宇临通阛。", "古甃磨翠壁，霜林散烟鬟。", "孤云抱商丘，芳草连杏山。", "俯仰尽法界，逍遥寄人寰。", "亭亭妙高峰，了了蓬艾间。", "五老压彭蠡，三峰照潼关。", "均为拳石小，配此一掬悭。", "烦公为标指，免使勤跻攀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书感","p":"","d":"宋代","a":"杨再十一","c":["枫江渡口草凄凄，桃浦桥边夕照低。", "惟有旧家双燕子，年年飞绕绿杨隄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵和周大书事绝句","p":"","d":"宋代","a":"晁说之","c":["终日寒斋咏小招，故人轩槛俯溪桥。", "可怜不得宣城郡，白日消来恨未消。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨后江上绿","p":"江南春","d":"宋代","a":"陈与义","c":["雨后江上绿，客悉随眼新。", "桃花十里影，摇荡一江春。", "朝风迎船波浪恶，暮风送船无处泊。", "江南虽好不如归，老蔼绕墙人得肥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自金山泛舟至焦山饮吸江亭","p":"","d":"宋代","a":"赵文昌","c":["金山据上流，怒挟汀声东。焦山护海门，坐折千里冲。", "两山势欲合，盛气薄苍穹。解纷谁巨擘，赖有疏凿功。", "至今买馀勇，角立相长雄。两皋汗漫游，目击大块中。", "手持一杯酒，浇尔磊块胸。鱼龙出鼓舞，摩荡青莲宫。", "山灵自不凡，感激欣相从。因笑魏与吴，乾坤两鸡虫。", "悠然一带水，往事寻无踪。夜深何处笛，呜呜起西风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苏幕遮 秋闺","p":"","d":"清代","a":"束蘅","c":["绿窗闲，人已静。玉兔初升，银烛光摇冷。倦倚画楼栏自凭。", "庭院深深，墙角花枝映。小池新水明如镜，霜打残荷，几点无多剩。", "瘦减腰肢力不胜。无奈伤秋，愁绝鸳鸯病。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春夏之交风雨弥间耳目所触即事十绝","p":"","d":"宋代","a":"汪莘","c":["野水平桥细浪生，柴门草长断人行。", "园林霁后春如在，燕雀鸣时夏正清。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"相和歌辞。拔蒲歌","p":"","d":"唐代","a":"张祜","c":["拔蒲来，领郎镜湖边。郎心在何处，莫趁新莲去。", "拔得无心蒲，问郎看好无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题董邦达山水十二幅 其十一 云泉涧阁","p":"","d":"清代","a":"弘历","c":["溪头架阁倚层椒，水态山光入绮寮。只可相携漆园吏，此间促膝注逍遥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"近榆亭 其六","p":"","d":"宋代","a":"陈造","c":["摭华复食实，果部谁称伯。兄桃柰其弟，无若此眉白。", "三玄信殊禀，五沃擅嘉殖。藏核待东归，分供橘奴帛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自武宁舍舟度岭投宿南山寺","p":"","d":"宋代","a":"李彭","c":["水落晚滩涩，云生寒岭昏。舍舟步崎峰，郁萝陟松门。", "孤烟望墟落，浮林自一源。野杓方屡渡，槿篱时扣阍。", "弄孙何许翁，夷面复鸟言。问津了不解，路穷斜谷分。", "暝投古兰若，钟磬清尘根。犹疑武陵客，误宿桃花村。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"碧云洞","p":"题灵岩各景","d":"宋代","a":"元勋","c":["踏流逆风寒，危径仅可伛。", "中空遂闳深，翠润欲垂雨。", "人间知何时，石乳观万古。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春雷 其一","p":"","d":"当代","a":"姚佳","c":["嘉澍因风分外清，霆霓似剑匣中鸣。酒犹可醉荼蘼色，春不能眠鶗鴃声。", "事到眼前天注定，名于身后日生成。何妨步武闻连鼓，无碍摊书拥百城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"白伯伦仪部移居夜阶助甫司封访之席上赋得卜居赤甲迁居新两见巫山楚水春十四韵 其四","p":"","d":"明代","a":"宗臣","c":["龙剑削芙蓉，十载闭其匣。壮士为尔开，满地走鳞甲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"松二首","p":"","d":"宋代","a":"石延年","c":["菌生枝上雨，龙起穴中雷。", "怪影漫溪侧，寒根缠石回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答董天隐推官","p":"","d":"宋代","a":"李复","c":["日月沄沄不可追，神奇腐臭略无遗。", "一丘一壑能谁过，相煦相濡莫我知。", "强聒睢盱何所补，雄夸凌厉亦奚为。", "秋来春去寻常事，安得乾坤独尔私。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"跋山谷书范滂传帖","p":"","d":"宋代","a":"柴中守","c":["小春昼日如春晚，饮罢披图清兴远。夜光照屋四座惊，金薤银钩真墨本。", "当年太史谪宜州，肠断梅花栖戍楼。拾遗不逢东道主，翰林长作夜郎囚。", "蛮烟瘴雨森鈇钺，更值韩卢搜兔窟。老色上面欢去心，惟有忠肝悬日月。", "郡丞嗜好殊世人，投笺乞字传儿孙。平生孟博是知己，笔下写出精神骞。", "兴亡万古同一辙，党论到头不堪说。刊章下郡汉道微，清流入河唐祚绝。", "先朝白昼狐亦鸣，正气消尽邪气生。殿门断碑仆未起，中原戎马来纵横。", "生蛟入手不敢玩，往事凄凉重三叹。兰亭瘗鹤徒尔为，好刻此书裨庙算。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岁暮还家杂诗 其二","p":"","d":"近代","a":"洪存恕","c":["腊尽远还乡，亲朋情话长。深杯嫌日短，缓步看人忙。", "纸马家迎灶，泥牛邻筑墙。乞儿歌竹版，细雨立昏黄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"官舍小池有鸂鶒遗二小雏二首 其二","p":"","d":"宋代","a":"苏辙","c":["清池定谁至，鸂鶒自来驯。知我无伤意，怜渠解托身。", "桥阴栖息稳，岛外往来频。勿食游鱼子，从交长细鳞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋日闲作 其七","p":"","d":"当代","a":"卢青山","c":["荡荡天宇清，觉夜如静日。嫦娥骑玉车，缓鞭天牛力。", "烂齑天孙锦，飞光撒太极。河水深几何？其深不可测。", "潜鲸莫能波，虞渊未可及。我欲结纸舟，长为河中客。", "向旭与河沉，向暮戏河液。七夕久已过，中秋望在即。", "吴刚善桂醑，玉兔勤捣汁。将攀桂花树，一与嫦娥识。", "饮此香酣酒，食彼不老粒。长共天人居，永谢红尘国。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春阴应秦王令（时在山西）","p":"","d":"明代","a":"徐贲","c":["云花鳞鳞山漠漠，重城平障芳阴薄。", "腻雨轻吹飞复停，勾引东风到帘幕。", "草滋微湿沾芳尘，陇头不见寻花人。", "桃英梅萼同懊恼，水纹满涨金河春。", "柳丝暝蒙烟不醒，辘轳暂辍银瓶绠。", "新莺未换谷中声，游蜂竟失阑前影。", "丁香百结蕉有心，绡屏六曲春沉沉。", "香抽翠缕火长续，余寒扑锦笼朱琴。", "江南春好多芳树，林园半是看花处。", "明朝重整小红车，风光满路行春去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天章精舍释奠礼成示诸生 其二","p":"","d":"清代","a":"全祖望","c":["瑰奇多学数琼台，底事三原忽见猜。力毁石翁尤可诧，瓣香姑舍莫相推。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同家德清侍尚书杨宝学山行先过上岩访家谐季","p":"","d":"宋代","a":"程公许","c":["鹤书杳杳上岩云，锦里安车忽暮曛。二陆久当为世瑞，一夔留与护香芸。", "中春涧壑晴如暝，亭午松萝气自薰。倚槛欲歌招隐赋，客尘痼我不成文。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"章丘张虞部子发考绩便道归寿其父母为成古体应之","p":"","d":"明代","a":"王世贞","c":["我昔游阳丘，其土秀而丰。近有女郎山，远有丈人峰。", "蒸为芝与兰，扬芬于帝宫。凤皇从北来，口衔紫泥封。", "云霞光照耀，山峰对巃嵷。堂上双和鸣，音声何雍雍。", "制锦为彩衣，割禄充朝饔。俱称千金寿，行乐浩无终。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"好事近 拟东泽","p":"","d":"清代","a":"周岸登","c":["愁眼送东风，泪点溅花红湿。指顾河山残照，幻暮云金碧。", "麴尘如幂卷高城，城下醉春色。折尽丝丝烟柳，听露桥吹篴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观镫谏","p":"咏史乐府十二章","d":"清代","a":"程盛修","c":["乾元楼，瞩神京，乐熙攘，庆太平。太平有象张镫宴，君乐须教民乐遍。", "焉得绮罗筵前千万镫，照见九州蔀屋鹄鸠形。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"四叠图字韵，和丽子令长子小剑在世时曾为予摄影","p":"浣溪沙","d":"当代","a":"汪岳尊","c":["谁幻先生笠屐图。南归早幸例髯苏。吉祥天遣护文殊。", "熙甫记亭翁悼子，谪仙爱月女名奴。古今人倘许相如。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"十八滩 其五","p":"","d":"清代","a":"顾文渊","c":["烟中捩舵水倒冲，千篙争力怖杀侬，森森石齿排剑锋。", "人言险滩最天柱，水底白日蟠蛟龙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中惊雨起作二首 其一","p":"","d":"当代","a":"卢青山","c":["枕头残卷拄床龟，病卧犹持竹节杯。梦似奇虹辉夜立，雨驱瀚海泼天飞。", "起看世界沉都没，随抚灵台有亦微。他处犹存他客否，茫茫如我坐摧颓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初冬快晴陪宣卿叔夏游石头庵过三生藏穷深极","p":"","d":"宋代","a":"胡寅","c":["茂樾初无一鸟鸣，晴曦参错昼阴清。", "枫林霜后未全赤，岩菊冬来主自荣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮 其十四","p":"","d":"清代","a":"陈步墀","c":["菱花簇照盘龙髻。朝来无限钿窗媚。一笑语仙郎。钗添金凤凰。", "为郎閒理发。背影浓香亵。不分鬓如银。双夸镜里春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"席间和向辟之元夜 其二","p":"","d":"宋代","a":"韦骧","c":["无愧涂人即可欢，□□□□□□□。月华莹澈通春夕，民气融和却暮寒。", "捃摭肴蔬成曲会，扶携老稚任环观。邑侬他日逢今日，往往应能话旧官。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元日有感","p":"","d":"宋代","a":"洪皓","c":["不见朝正秖自愁，展亲弗逮兖州囚。席重摇忆谈经会，酒噀宁知救火谋。", "内热空持白羽扇，峭寒且著黑羔裘。履端醽醁何时赐，落笔高歌洒泪休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和添酒中六咏。酒杯","p":"","d":"唐代","a":"皮日休","c":["昔有嵇氏子，龙章而凤姿。手挥五弦罢，聊复一樽持。", "但取性淡泊，不知味醇醨.兹器不复见，家家唯玉卮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"定风波","p":"","d":"宋代","a":"欧阳修","c":["把酒花前欲问伊。问伊还记那回时。黯淡梨花笼月影。人静。画堂东畔药阑西。", "及至如今都不认。难问。有情谁道不相思。何事碧窗春睡觉。偷照。粉痕匀却湿胭脂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"达奚司空像","p":"","d":"明代","a":"释今沼","c":["树老庭荒不记春，天朝裳服俨遗身。空悲乡国生翰鸟，似立朝门待舌人。", "灯火青荧通晦夜，廊龛寂历罥丝尘。从今断却当年恨，海舶无因过此津。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"劝酒","p":"","d":"唐代","a":"白居易","c":["劝君一盏君莫辞，劝君两盏君莫疑，劝君三盏君始知。", "面上今日老昨日，心中醉时胜醒时。天地迢遥自长久，白兔赤乌相趁走。", "身后堆金拄北斗，不如生前一樽酒。君不见春明门外天欲明，喧喧歌哭半死生。", "游人驻马出不得，白舆素车争路行。归去来，头已白，典钱将用买酒吃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莲池潭","p":"","d":"清代","a":"张湄","c":["莲瓣芹丝一气香，天然泮水绕宫墙。林端不许飞鸮集，山势高骞拱凤皇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登五层楼","p":"","d":"明代","a":"张家珍","c":["缥缈层楼连碧汉，白云积翠入空微。东回古寺钟初动，南绕长江水一围。", "返照半含沧海日，远帆斜没钓鱼矶。登临一笑成今古，怪底王生便赋归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日皇甫司勋见过余出小鬟以筝琶侑觞司勋为赋三绝句率尔奉答 其二","p":"","d":"明代","a":"何良俊","c":["歌珠历落本清圆，更遣流泉乱拂弦。好取使君留一顾，故将误曲唱当筵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感寓 其六","p":"","d":"明代","a":"朱诚泳","c":["吾闻帝王世，人文日以宣。间尝读其书，抚卷思茫然。", "三王莫之尚，五帝不可前。征伐与禅让，仁义岂偏全。", "光明烛幽远，心法垂简编。群生乐熙皞，九州无倒悬。", "帝王日以远，明哲徒拳拳。恭惟我皇祖，绳武三千年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其六","p":"","d":"元代","a":"黄溍","c":["双鹤冲天岁月多，至今香火压嵯峨。刘郎不是无兄弟，奈此丹鸡白犬何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山村夜坐","p":"","d":"清代","a":"梁颀","c":["俯仰空庭四宇清，浮云扫尽晚烟轻。梨花皓月原同色，风竹流泉不辨声。", "深谷人閒春亦寂，短墙水近冷先生。却思城市喧阗处，箫鼓楼头听二更。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"邓尉山中","p":"","d":"清代","a":"华士芳","c":["不是探梅日，空山气更清。上方寻古寺，下界听钟声。", "野鸟自呼侣，闲花不问名。诸天稍昏黑，回看暮云平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"瞿塘两崖","p":"","d":"唐代","a":"杜甫","c":["三峡传何处，双崖壮此门。入天犹石色，穿水忽云根。", "猱玃须髯古，蛟龙窟宅尊。羲和冬驭近，愁畏日车翻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送谢从义知杭州分题岳王坟","p":"","d":"明代","a":"陈汝言","c":["荒坟秋树影萧萧，只有孤僧伴寂寥。", "二帝游魂归不得，百年枯骨恨难消。", "山空永夜愁寒雨，江阔悲风起暮潮。", "若到钱塘逢故老，伤心切莫问前朝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉檄赴古北口军次祀軷有期书示同志 其四","p":"","d":"清代","a":"蒋曰豫","c":["绝塞风云接大荒，谁敲铜斗韵伊凉。鸡声夜醒千门月，虎迹秋盘万岭霜。", "客惯渐忘尘梦换，官卑也要国恩偿。镫前独抱龙渊啸，影烂芙蓉忍善藏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送何令归江右","p":"","d":"明代","a":"陶安","c":["故山猿鹤正相招，非是渊明懒折腰。想见章江门外柳，待君归系木兰桡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和陈教授庆煌博士龟山朝日二绝句元玉 其二","p":"","d":"当代","a":"林恭祖","c":["万古蓬莱镇海东，朝暾浴罢碧波红。群贤此日兰阳会，吟到龟山句更工。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杜鹃花","p":"","d":"明代","a":"屈大均","c":["子鹃魂所变，朵朵似燕支。血点留双瓣，啼痕渍万枝。", "开当寒食后，人正断肠时。望帝春心在，花含万古悲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"君家玉雪花如屋","p":"菩萨蛮","d":"宋代","a":"辛弃疾","c":["君家玉雪花如屋。未应山下成三宿。啼鸟几曾催。西风犹未来。山房连石径。云卧衣裳冷。倩得李延年。清歌送上天。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"四圣赞","p":"","d":"宋代","a":"释师体","c":["稽首普贤，不可思议。", "出头露面，开言吐气。", "拍盲担板，忘恩断义。", "事无寸长，熏天炙地。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐　题金纤纤砚拓小像","p":"","d":"近代","a":"寇梦碧","c":["春星小谪，瘦影和愁拓。帘外素馨花欲落，今日东风犹恶。", "清吟曾伴兰闺，研螺写上红梅。惆怅水天梦断，通词拟托㛙妃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"明皇贵妃上马图","p":"","d":"明代","a":"张璨","c":["七宝妆鞍蜀锦堆，黄门扶控踏红埃。", "君王只顾蛾眉笑，末路谁知到马嵬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天远星飘渺","p":"贺新郎","d":"现代","a":"顾随","c":["天远星飘渺。", "漏声残、月轮高挂，尘寰静悄。", "南北东西都何处，着我情怀懊恼。", "况岁暮、天寒路杳。", "欲织回文长万丈，问愁丝恨缕长多少。", "空自苦，赚人笑。", "半生真似墙头草。", "侭随风、纷披摇荡，东斜西倒。", "万岁千秋徒虚语，眼看此身将老。", "且点检、残篇断稿。", "说到文章还气馁，算个中事业词人小。", "清泪滴，到清晓。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"绝命诗 其一","p":"","d":"清代","a":"黄玹","c":["乱离滚到白头年，几合捐生却未然。今日真成无可奈，辉辉风烛照苍天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游仙都观五首 其二","p":"","d":"宋代","a":"吴芾","c":["策杖行行入翠微，步虚山下久忘归。幽栖宜有中林士，何事斯人近世稀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈六十九首 其三十五","p":"","d":"宋代","a":"释道宁","c":["焚香提起经来读，便是拈华付嘱心。此外别求玄妙解，悠悠千古少知音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感鹤","p":"","d":"明代","a":"何吾驺","c":["一往穿云入汉游，长风吹断送沧洲。谁传华表千年恨，鳷鹊无情不共愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜坐即事","p":"","d":"宋代","a":"胡仲参","c":["午夜空庭寂，心闲坐亦忘。", "竹间风动静，云里月行藏。", "惊鹊出幽树，寒螀语废廊。", "瓯茶聊当酒，清气入诗肠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜月怀明卿二首 其一","p":"","d":"明代","a":"宗臣","c":["逐客音书久不闻，天风吹断楚江云。相思惟有长安月，拾得婵娟难寄君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日怀陈洛南尚书","p":"","d":"明代","a":"庞尚鹏","c":["艳阳池馆夏生寒，偏喜清时共挂冠。夜雨高吟频遣寄，稻田新熟愿加餐。", "交游转觉蓬山远，魂梦犹惊蜀道难。最是故园风景好，满天明月似长安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"到四安","p":"","d":"宋代","a":"陈著","c":["雨中行数日，今日得新晴。", "山到浙閒秀，船从海上行。", "市腥逢海错，人语带京声。", "此去总佳景，坡仙曾细评。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和李端叔大夫从参寥子游许昌 其八","p":"","d":"宋代","a":"李廌","c":["梦为蝴蝶恣飞飞，飞入花丛处处迷。不是提壶强呼起，尚应栩栩展江西。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春末夏初闲游江郭二首","p":"","d":"唐代","a":"白居易","c":["闲出乘轻屐，徐行蹋软沙。观鱼傍湓浦，看竹入杨家。", "林迸穿篱笋，藤飘落水花。雨埋钓舟小，风飏酒旗斜。", "嫩剥青菱角，浓煎白茗芽。淹留不知夕，城树欲栖鸦。", "柳影繁初合，莺声涩渐稀。早梅迎夏结，残絮送春飞。", "西日韶光尽，南风暑气微。展张新小簟，熨帖旧生衣。", "绿蚁杯香嫩，红丝脍缕肥。故园无此味，何必苦思归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"淳化中朝会二十三首 其二 群臣初举酒毕作《化成天下》。","p":"","d":"宋代","a":"郊庙朝会歌辞","c":["圣德比陶唐，千年祚运昌。茂功虽不宰，鸿业自无疆。", "极塞成清谧，齐民益阜康。文明同日月，遐迩仰辉光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八月一日","p":"至和杂书五首","d":"宋代","a":"蔡襄","c":["淮天过尽入吴渠，兰亭晚日光疏疏。", "金桃傅粉好颜色，绿醽泛滟深车渠。", "觥巡屡卷明星出，花翘零落随衣裾。", "幺弦不动凝古意，春容浅破长眉舒。", "庭院帘帷一齐下，红蜡阴沈霜满瓦。", "鸡头软热七月终，举手分传玉盈把。", "席前碧瓮覆瑶浆，一秋愁泪风前洒。", "云中宝晕万重高，付与轻绡藏冰麝。", "孤城寒柝夜迢遥，谁道刘郎有天马。", "归来却问东海桑，海浪漫漫彩虹挂。", "红丝萦脍晓刀鸣，双龙笑断梦中惊。", "莫将团扇掩尘匣，曾障清歌十数声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"云溪山人歌","p":"","d":"当代","a":"卢青山","c":["天下至穷云溪谷，中有至穷天下屋。云溪山人非世居，随风飘至相狎熟。", "熟即为家家本寄，山人安辨其华朴。相倚觳觫书橱四，二案一椅供卧伏。", "白壁森森如白眼，五年睨我背弓矗。杂纸堂皇相推挽，屋如旷野纸蒿簇。", "有时寻人人不见，开茅剔草蚿而缩。亦有似屋冬来时，风为主人人客宿。", "隐几神游不可惊，为客为家两难卜。绕屋之山趋奔驰，脉浪如海之雕塑。", "千秋固是此中人，穷隅秃岭味如肉。披岚冲霭飞寒霖，耸肩屈颈如峰麓。", "当春绚烂仍踽踽，万花丛中一粪曝。山不嫌余粲其颜，峨冠者来其美蹙。", "留余驱人何为也，山其与余为心腹。云溪山人之所有，有此山屋两穷物；", "山屋之穷何所状，唯有一月相照覆。流泽于林林无声，修眉如画画窗幅。", "洞牖趺坐四围趋，万人来拥生公肃。行则髫童逐我影，立则粲者偎颔淑。", "山人至此安求哉，中宵独乐常哧卟。山屋月成三皮匠，相聚岂非诸葛属？", "胸如丘壑月如心，屋贮二者并山人，岂非天下至富足？", "谁使可人扣门来，相与口舌卧游读？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和董伯玉不向东山久韵","p":"","d":"宋代","a":"吴芾","c":["我暂出山去，常忧蕙帐空。", "闻君东山乐，爱君古人风。", "日暮君不来，碧云蔽高穹。", "凌晨戒僮仆，驾言将租东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十六日开船值北风大作复泊北门","p":"","d":"元代","a":"陈基","c":["风急江难渡，天寒雪更飘。济川虽有楫，跨海恨无桥。", "使节辞吴近，官军去楚遥。北门仍系缆，山雨夜萧萧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题玉泉溪","p":"","d":"唐代","a":"湘驿女子","c":["红叶醉秋色，碧溪弹夜弦。", "佳期不可再，风雨杳如年。"],"tags":["写景", "抒情", "愁苦"],"z":"叶：一作“树”。\n碧溪：绿色的溪流。\n佳期：美好的时光。\n杳（yǎo）：昏暗、遥远，没有尽头。","y":"红叶片片沉醉于动人的秋色，碧溪潺潺在夜里弹奏起琴弦。\n美好的日子逝去不可能再来，凄风苦雨无限让人度日如年。","s":"","k":"诗"},
  {"t":"东坝以里沿岸人家皆对门植苇于小屿不晓其旨漫成四绝 其三","p":"","d":"宋代","a":"岳珂","c":["北都旧产无淇竹，见说园池芦苇多。涨绿不妨夜来雨，更须别浦听鸣荷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈六十九首 其五十一","p":"","d":"宋代","a":"释道宁","c":["有利无利，不离行市。师子嚬呻，象王游戏。洎乎检点将来，未是衲僧巴鼻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杨花曲","p":"","d":"近代","a":"孔凡章","c":["荔枝湾上波声急，瑽琤似鼓湘灵瑟。月涌澄潭镜影清，星临平野珠光出。", "闻道江山数百年，不拘一格降婵娟。书窗隐约杨花影，吟稿商量柳叶笺。", "南冥有女凌波立，万卉凝香扑裙叶。小字呼来却唤鱼，新妆理就能羞蝶。", "羊城巾帼擅雄风，水国生涯巧笑中。玉树修名双美具，珠江灵气一身钟。", "豆蔻芳华刚十六，生逢蜗角争蛮触。剑舞难消意气豪，弦歌不觉光阴倏。", "神京新起妙高台，羽檄星驰选俊才。未解功名将脱颖，剧怜成败尚猜枚。", "澄澜划破明珠溅，彩云一线驰如箭。大地风雷决死心，中天日月开生面。", "华清池水漾芳温，鲛女销残帝子魂。风里落花春有梦，雨中飞燕水无痕。", "嫣红上颊匀轻晕，闲人浪惹失颜愠。妩媚犹存虢国风，温柔莫向杨家问。", "银杯镂字赠双成，十里天衢揽辔行。江左枣梨镌姓字，岭南桑梓羡恩荣。", "神州隔海春雷震，又报邻邦开远运。黄种图强肯后人，红颜崛起争先奋！", "岛国风情漫惹愁，此行宁为事芳游？请缨小试沧浪水，抽剑思裁日夜流。", "驰道频催金勒马，英雄未许淆真假。战火燃眉黯日星，狂澜攘臂惊夷夏。", "飞塔鸣钟日未曛，旗开万国鼎三分。雪骢蹴笛凝香雾，风鸽牵罗化锦云。", "碧波无复清澄底，鱼龙溷迹风涛里。破阵兰陵仗女兵，先驱柳浪同儿戏。", "红妆禹甸迥无伦，番女蛮娃尽后尘。九州讴咏归名下，一代丹青照海滨。", "百战归来名字重，万人空巷春城动。红缨耀日剑光寒，翠帜摇风花气拥。", "凤鼓龙箫殷若雷，游人都是看花来。日边弄影输红杏，雪里清标识素梅。", "急流勇退谈何易，忽听笙歌喧北地。铁骑遥颁露布来，玉人更把云裳理。", "江城南翼拱京师，十万明灯夜不知。全胜萧墙方北定，窥边胡马又东驰。", "莫道女郎殊吉士，读书喜断兴亡事。霄汉常存木铎心，云泥不懈长缨志。", "涉世才知万事非，难凭肉食仗安危。东林有石天方醉，北阙无书梦已灰！", "歌声夜彻浔阳岸，江头蹀躞空肠断。此役惟遗画虎讥，官场那敢燃犀看。", "先是：重瀛奏凯初，芳声遍播海东隅。已借鲤鱼通贡水，更随鸿雁上匡庐。", "后来邺下流言起，流言竟中云英姊。浇俗相传未必真，采风纪事翻成史。", "庐山高处接云烟，开府洪都尚少年。百诺传呼新富贵，万方多难此留连。", "偶际春人来逆旅，羽衣如雪飘飘举。紫塞烟尘警寇氛，兰桥谣诼谐仙侣。", "侠骨柔肠未解羞，从来家国重恩仇。八驺只擅谋身计，百炼何劳绕指柔。", "还君一束梅花结，九州铸错真成铁！小妹犹虚玉镜盟，使君自有金钗列。", "春池吹皱漫相干，蜚语飞来涤污难。防川自写陈情表，拜月谁诬乞巧盘？", "骓欲逝兮时正利，涛笺暗托飞鸿寄。春花秋月岂君凡，白石青松知妾意。", "含嗔江上泛轻航，一夜鸣筝沸建章。眉黛不描时式样，口碑偏满少年扬。", "寂寞昭陵陵下路，一朝车骑喧如堵。宝瑟新调静女诗，瑶池正看天魔舞。", "蝶拥莺围意不禁止，几人修竹进曹箴。执鞭孰遣樊迟御，行路犹知司马心。", "播音直使诸公愧，蛾眉解滴新亭泪。髫龄爱诵木兰诗，长大心萦荀灌骑。", "肯俯幽兰就草莱，可怜鹓鹭枉追陪！朱门棨戟心无睹，钿盒隋珠意不回。", "结束铅华归去好，东风让与闲花草。翠袖轻辞白下门，香旌遥指春申道。", "春申仕女本多情，雷走香车夹路迎。舞榭花酣银管酽，歌筵珠啭玉杯莹。", "画舫连桡东去久，高桥堤上千人走。横海英风逐鹿姿，伏波妙技降龙手。", "皓腕纷飞星眼融，青丝斜挽浪花浓。情深绿水身难主，力尽清波泪欲融。", "春江水冷罗衣薄，故园待践归来约。惊鸿掠影入潇湘，小凤留芳重京洛。", "春申江上水悠悠，泛起人间万斛愁！青鬟岭外音书杳，黄耳夭涯道路遒。", "风华自昔终尘土，花开花谢无人主！何似新词付五弦，倘留佳话传千古。", "枉抛心力军名姝，二十华年此故吾。才愧江东名士鲫，诗成南国美人鱼。", "村讴呕哑难为读，韩潮苏海惭枵腹。唱彻诗坛下里声，可怜腾笑杨花曲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"漳河疑冢","p":"","d":"宋代","a":"京镗","c":["疑冢多留七十馀，谋身自谓永无虞。不知三马同槽梦，曾为儿童远虑无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"祷雨宿九曲池上三首","p":"","d":"宋代","a":"晁补之","c":["同辇笙歌地，荒池风露天。", "无心更怀古，凉夜正甘眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"希之小扇","p":"","d":"宋代","a":"韩淲","c":["野水寒烟洗岸沙，萧萧风苇净霜华。无人独立飞来鹭，冷落心情一倍加。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题陈举善山水图小景四首为蒋志明赋 其四","p":"","d":"明代","a":"刘崧","c":["山暝啼猿外，江平落雁中。几时将小艇，来问钓鱼翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵回叔经","p":"","d":"宋代","a":"陈藻","c":["从来剽窃为场屋，直是无繇识古书。", "屈指罕能官显达，到头剩得腹空虚。", "君今身计非谋禄，地有人耕免荷锄。", "高适学诗看更晚，才名何患不相如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苕上","p":"","d":"清代","a":"徐永宣","c":["青山澹澹水茫茫，半面蒹葭半面桑。都有绿阴维钓艇，断云微漏夕阳黄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中寄武公望二首 其一","p":"","d":"宋代","a":"廖行之","c":["四十馀年尚转蓬，渠论南北与西东。但知爱子三迁教，不办谋生一亩宫。", "北海可怜真意广，步兵良苦漫途穷。人生择术须循分，鹏鴳逍遥自不同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"代乐府三首 其三 双桐生空井","p":"","d":"南北朝","a":"萧纲","c":["季月双桐井，新枝杂旧株。晚叶藏栖凤，朝花拂曙乌。", "还看西子照，银床系辘轳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"悲老宫人","p":"","d":"唐代","a":"刘得仁","c":["白发宫娃不解悲，满头犹自插花枝。", "曾缘玉貌君王宠，准拟人看似旧时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重午王文辅送米食张云卿送新酒来因成绝句","p":"","d":"宋代","a":"邹浩","c":["水团粽子恰登门，白酒持来更满樽。节物人情总堪醉，况归田里已承恩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"塞下曲 其二","p":"","d":"清代","a":"顾炎武","c":["一从都尉生降去，夜夜魂随塞雁芦。陛下宽仁多不杀，可能生入玉门无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"钱舜举捕鱼图","p":"","d":"明代","a":"董纪","c":["脱蓑挂船尾，鼓枻坐船头。得鱼既换酒，欸乃扬中流。", "妻儿冒短篷，喜无风雨忧。日暮向何处，白鹭古时洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题富贵祥宜侯砖砚","p":"","d":"当代","a":"姜军","c":["砚出江东透古芒，墨池窥牖等天苍。从今视古人鹏异，重向西湖觅晏方。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆秦娥（初冬）","p":"","d":"宋代","a":"赵长卿","c":["寒萧索。征鸿过尽离怀恶。离怀恶。江空天迥，夜寒枫落。", "有人应误刀头约。情深翻恨郎情薄。郎情薄。梦回长是，半床闲却。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二十三日使风","p":"","d":"宋代","a":"赵蕃","c":["江行已属北风权，此去宁忧上水船。", "卧听招呼帆转脚，起看飞溅水平舷。", "鸥乘逸气沿仍溯，雁怯惊吹断复连。", "玄妙未穷天籁说，雄豪诗读快哉篇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题画 其一 垂钓图","p":"","d":"清代","a":"缪公恩","c":["门对空江水接天，翠屏倒影浸云烟。一竿风月无人管，閒数沙鸥倚钓船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登万寿阁望华山","p":"","d":"清代","a":"王熊伯","c":["巍峨西岳镇西京，杰阁朝凭爽气清。五里雾披三辅晓，半空云卷万峰晴。", "芙蓉彩翠窗前落，海日光华掌上生。见说玉姜犹不死，御风何处正吹笙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和荆公何处难忘酒诗","p":"","d":"宋代","a":"郑侠","c":["何处难缄口，熙宁政失中。", "四方三面战，十室九家空。", "见佞眸如水，闻忠耳似聋。", "君门深万里，安得此言通。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送周德涵","p":"","d":"明代","a":"陈恭尹","c":["便作天涯别，重逢未可期。快闻经世论，兼读过庭诗。", "骐骥宜千里，鹪鹩且一枝。野人头已白，不复问当时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"更漏子","p":"","d":"清代","a":"孙云鹤","c":["绿阴浓，红雨乱。无奈春归人远。梁燕去，塞鸿来。闲阶生暗苔。", "长亭路。分襟处。惆怅画屏烟树。流水远，夕阳沉。倚栏千里心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐 二阕 其一","p":"","d":"清代","a":"姚燮","c":["更无佳鸟。但有鸣蛩扰。莫怨秋风催鬓早。心已春风催老。", "楼前淡月疏星。楼中淡月疏檠。要睡不能多睡，隔墙送过鸡声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答季仲宜","p":"","d":"宋代","a":"王十朋","c":["我昔从君伯氏游，短素长笺日唱酬。凌云健笔驱山丘，欲追李杜参曹刘。", "子今又复振风流，可人一气真吾俦。明珠白璧蒙暗投，自揣无堪但增羞。", "君家棠棣才俱优，吾知徐公百不忧。更能勉力追前修，俯舍青紫何须求。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和知府右丞秋贡燕士席上所赋","p":"","d":"宋代","a":"吕陶","c":["应书群彦称旁求，劝驾贤公礼数优。名出士林当赫赫，诗歌鹿野自呦呦。", "云霄去路程皆远，杞梓良材干尽脩。登却龙门须变化，夺标人已在船头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"慈恩寺九日应制","p":"","d":"唐代","a":"薛稷","c":["宝宫星宿劫，香塔鬼神功。王游盛尘外，睿览出区中。", "日宇开初景，天词掩大风。微臣谢时菊，薄采入芳丛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登北固山游甘露寺","p":"","d":"清代","a":"金武祥","c":["危峰独立迥淩虚，万里苍茫眼界舒。第一江山推北固，千秋形势壮南徐。", "孤亭直欲超云表，铁塔犹存历劫馀。说到沧桑增感慨，寺门凭眺意何如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答潘文叔见寄予十月尝访文叔许来而犹未也","p":"","d":"宋代","a":"孙应时","c":["别离一何久，迢递阻音形。", "重上君子堂，相见眼终青。", "君颜尚冰玉，我鬓已星星。", "借问十载间，风波两蓬萍。", "岭剑各万埯，心目多所经。", "归来且强健，怳然真梦醒。", "可怜万修竹，清音玉珑玲。", "萧条媚寒日，约略环翠屏。", "相携复一笑，芝兰有余馨。", "孤云自舒卷，野鹤来青冥。", "平生阅群彦，十八九凋零。", "吾徒亦何愿，毕景依林坰。", "种秫令可酿，储粟常满瓶。", "琴书奉娱玩，足以陶性灵。", "千载伐木篇，此意神所听。", "往来亦奚惮，江浦堪扬舲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郊行见有陆上舟居者口占二绝 其一","p":"","d":"近代","a":"许家惺","c":["浮家半世苦迁流，从此风波永不愁。一样闾阎尘扑地，任他西北有高楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵彭青老咏雪三绝句 其二","p":"","d":"宋代","a":"王庭圭","c":["天公剪水散花林，试比江梅色浅深。梁苑词人能赋咏，终篇不作苦寒吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"诗偈 其一八○","p":"","d":"唐代","a":"庞蕴","c":["惭愧好意根，无自亦无他。无自身无垢，无他尘不加。", "常居清静地，知有不能过。旧时恶知识，总见阿弥陀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚晴独酌二首","p":"","d":"宋代","a":"杨万里","c":["冷落杯盘下箸稀，今年淮白较来迟。", "异乡黄雀真无价，稍暖琼酥不得时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"听鹤亭和韵 其一","p":"","d":"明代","a":"霍与瑕","c":["小山曾见省南东，寓远翛翛倚碧空。岂谓微垣施巧匠，亦移蓬岛入新丰。", "双凫晓浥花间露，独鹤时鸣竹外风。最是仙郎无一事，洗心高坐玉壶中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其三","p":"","d":"宋代","a":"释祖可","c":["怀人更作梦千里，归思欲迷云一滩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金山岭","p":"","d":"宋代","a":"范成大","c":["阪峻身频偃，崖深首屡回。", "云浮平地出，路拂半天来。", "但阅关山过，都忘岁月催。", "湘南初上马，犹插早春梅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄家菽园孝廉","p":"","d":"清代","a":"丘逢甲","c":["韩苏笔力不到处，石破天惊自著书。未悔居夷从凤鸟，真看横海掣鲸鱼。", "河山烟点齐州外，文字雷屯草昧初。闻说鸡林争购集，百蛮齐拜孝廉车。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送曹倅岩山官满归里","p":"","d":"宋代","a":"文天祥","c":["春陵光霁落苍苔，葛水神仙立翠槐。", "万里云霞麒骥路，三年风月凤凰台。", "兴同老子复不浅，歌曰先生归去来。", "庾岭梅花开渐遍，一枝就与寄蓬莱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"歌者十二首 其九","p":"","d":"唐代","a":"司空图","c":["白云深处寄生涯，岁暮生情赖此花。蜂蝶绕来忙绕袖，似知教折送邻家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谒夏忠靖周文襄新祠","p":"","d":"明代","a":"沈周","c":["水利克脩财赋举，二公戮力惠吴民。祀行今日欣成典，爱寓斯邦合妥神。", "肖貌堂堂快星凤，功名在在认麒麟。山川悠久贵同德，蕉荔殷勤系后人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感事","p":"","d":"明代","a":"祁敕","c":["五亩溪园锁绿阴，红尘何事恰相侵。人生安得尽如意，世事但求无愧心。", "却喜他山真有石，休言同舍误持金。重裘著罢春寒退，静掩书斋抱膝吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"潇湘八景诗 其一 潇湘夜雨","p":"","d":"宋代","a":"张经","c":["终夜雨潇潇，闷杀孤舟客。滴滴打蓬声，错讶灵妃瑟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和粹伯七夕韵 其一","p":"","d":"宋代","a":"曾协","c":["常时泪雨久涟洳，准拟晴窗叫勃姑。报答月华思善画，便和风露入新图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀靳师道","p":"","d":"明代","a":"欧大任","c":["铁瓮城边路，怀人径寸心。夕鸿前浦远，春雨大江深。", "笔札留东观，风云在上林。游閒知爱客，飞盖日相寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙 夏夜偶成用宋词韵","p":"","d":"清代","a":"杨芸","c":["袅袅轻风吹竹树，依稀天际闻笙。未秋先已送秋声。", "愁人偏易感，无语怨深更。", "捲起疏帘看夜色，一钩残月空庭。银河淡淡断云横。", "蕉衫烟漾碧，凉影闪流萤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"嘉定己巳立秋得膈上疾近寒露乃小愈十二首 其八","p":"","d":"宋代","a":"陆游","c":["小诗闲淡如秋水，病后殊胜未病时。自剪矮笺誊断稿，不嫌墨浅字倾攲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"即事","p":"","d":"宋代","a":"楼钥","c":["十日阴寒雪不成，腊残春近更霜晴。", "深山高卧如春暖，绕鬓飞蚊自在鸣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"扇子诗 其七十九","p":"","d":"宋代","a":"李石","c":["爱他国色艳倾城，老衲心城百万兵。便使有情何足动，幻花况是本无情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归自南华诗","p":"","d":"宋代","a":"朱翌","c":["众绿扬新楚，初晴中薄寒。", "行山无阔步，陟巘有遐观。", "蕨紫拳犹小，松黄粉渐乾。", "无嫌一马瘦，径度两重滩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送刘善长归北安省亲","p":"","d":"宋代","a":"洪皓","c":["九龄颖悟已惊人，乃父分茅善抚民。", "郑忽身为周室质，贾生议屈汉庭臣。", "行攀郄桂荣三斧，暂著莱衣省二亲。", "勿讶班荆歌陟屺，小人有母在江宾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"见赵章泉","p":"","d":"宋代","a":"姚镛","c":["秉芳独向章泉老，四海儿童以字传。特诏难更高士服，好诗多入贾人船。", "行窝冷落熙宁后，放鹤风流景祐前。一代典刑能几见，愿从几杖阅耆年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王岱麓李三洲携酒过访诗以谢之三首 其二","p":"","d":"明代","a":"王渐逵","c":["古人重倾盖，那惜相知新。去者日以隔，来者日以亲。", "何意白首交，乃作行路人。远迹爱丛莽，养痾越台滨。", "曲肱阅尘鞅，于今得见君。庭荫列嘉树，日夕谛玄文。", "粗疏多谬误，所愿在率真。四海皆兄弟，何必比与邻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"午日江上","p":"","d":"明代","a":"区怀年","c":["笙歌十里酿闲愁，水郭凉风五月秋。双桨玉壶供野酌，六衢香粉翳中流。", "搴芳日丽芙蓉浦，听技云生翡翠舟。幽况早同渔父适，钓竿无恙狎沙鸥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过隐者庄","p":"","d":"明代","a":"田登","c":["幽轩停白昼，心古万缘轻。春壑花争放，澄潭浪不生。", "云山当近户，风雨望高城。归去渊明社，欣欣木正荣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望江南","p":"","d":"清代","a":"顾贞观","c":["江南好，秋水晚平桥。千顷绿沉菱叶雨，十分香散藕花潮。", "人倚木兰桡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"真止堂","p":"","d":"宋代","a":"吴芾","c":["我有虚堂号真止，坐来万虑清如水。", "君今更以止名堂，想见了无尘念起。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"至普安察院合溪道长复留一诗见候次韵","p":"","d":"明代","a":"张羽（凤举）","c":["归路依微取次寻，前山日日厌登临。寒经索岭霜林静，瘴入盘江昼雾深。", "古驿荒凉惊岁晚，野云容易结秋阴。驱车纵猎输谁子，蔓草斜坡羡获禽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赵縠阳太史东归赠寄","p":"","d":"明代","a":"霍与瑕","c":["春风春日送仙槎，珠海芳尊共物华。帝里九重同恋阙，师门八十讲通家。", "玩馀樵岭清秋月，冲碎罗浮古洞霞。此去不妨呤弄在，蓬莱仍有万年花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次陈平甫提干晚春韵","p":"","d":"宋代","a":"释元肇","c":["莫云岂特看江东，朋旧如今四海中。花落不禁三日雨，颜衰消得几春风。", "檐前雏竹娟娟粉，阶下樱桃滴滴红。辛苦广骚将底用，弋人何处慕冥鸿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与薛十二过寿宁精舍得歌字","p":"","d":"元代","a":"李延兴","c":["鸣雨过青嶂，飞烟绕碧萝。庭空留鹤迹，江静听渔歌。", "长夏迎人少，高年礼佛多。飘飘飞锡处，千里又相过。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和友人游仙杂诗 其一","p":"","d":"清代","a":"戴亨","c":["年来踪迹但支离，世味人情老渐知。材与不材堪自处，道非常道觅吾师。", "鸾音鸿爪同消息，老屋荒江阅岁时。笑看蚍蜉尘垢里，熙熙攘攘欲奚为。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荆州公馈酒 其一","p":"","d":"明代","a":"宋登春","c":["菱叶青青水荇齐，绕篱黄蝶菜苗肥。夕阳谁送山人醉，坐看儿童跨犊归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"滴滴金","p":"","d":"宋代","a":"晁端礼","c":["庞儿周正心儿得。眼儿单、鼻儿直。口儿香、发儿黑。脚儿一折。", "从来薄命多阻隔。未曾有恁相识。除非烧香做功德。且图消得。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"禅坐四首 其四","p":"","d":"明代","a":"郭之奇","c":["净极明通处，慈云妙覆时。浮生如幻化，真地果琉璃。", "弹指销荣悴，冥心出险夷。何年依锡止，笑尔鹤飞迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居午睡起弄花三首 其二","p":"","d":"宋代","a":"杨万里","c":["数片荷花漾水盆，忽然相聚忽然分。从教压捺沉盆底，依旧浮来无水痕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"斋宿和韵 其一","p":"","d":"明代","a":"庄昶","c":["老隔垂帘病亦侵，梦回西阁漏沈沈。报酬主上平生分，对越青天此寸心。", "布絮不温粗被冷，朝衣端坐烛花深。相应郊祀寒仍在，昨夜圜丘雪尚阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"孤吟","p":"","d":"当代","a":"程滨","c":["吾诗谁读取，昔有失之堂。评品斯人倦，行吟独自狂。", "愁云笼缜密，哀玉叩清扬。更觅销魂句，愔愔入锦囊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚过邻曲","p":"","d":"宋代","a":"陆游","c":["阳狂跌宕送年华，信步来寻野老家。", "浅濑水清逢立鹭，横林叶尽数栖鸦。", "书生一饱依耕耒，壮士孤愁入戍笳。", "王绩但思酣美酝，葛洪不复问丹砂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题水月 其二","p":"","d":"宋代","a":"苏舜钦","c":["积翠湖心迤逦长，洞台萧寺两交光。鸟行黑点波涛白，枫叶红连橘柚黄。", "人我绝时隈树石，是非来处接帆樯。如何遂得追游性，摆却营营不急忙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送杭州使君苏内相先生某用先生旧诗方丈仙人出渺茫高情犹爱水云乡为韵作古诗十四首 其七","p":"","d":"宋代","a":"李廌","c":["周公非汲汲，仲尼岂皇皇。吾道无若人，孰能相维纲。", "古今异伦轨，英风自相望。下民今喁喁，造物太茫茫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽范丞相忠宣公六首 其六","p":"","d":"宋代","a":"毕仲游","c":["挥泪西原上，晴云为我阴。谁知如望岁，竟不复为霖。", "主圣空撝己，民思未绝吟。已休还一恸，非但哭知音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"追和王常侍登郡楼望山","p":"","d":"宋代","a":"邵雍","c":["四贤当日此盘恒，千百年人尚寻颜。", "天下有名难避世，胸中无物漫居山。", "事观今古兴亡后，道在君臣进退间。", "若蕴奇才必奇用，不然须负一生闲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题徐训导廷献魁山旧隐","p":"","d":"明代","a":"王绂","c":["人品如瞻斗，山名合应魁。地灵知孕秀，天赋肯淹才。", "笔阵惊同列，文光烛上台。高攀蟾窟桂，勇跃禹门雷。", "已作鹍鹏化，空令猿鹤猜。经横芹泮静，琴弄杏花开。", "宦志云霄待，乡心岁月催。黄残松径菊，绿遍石田苔。", "若便寻归驾，移文恐劝回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水头","p":"","d":"宋代","a":"孔平仲","c":["荒湾斗转河如束，千古痴龙卧空谷。公然收水入毫芒，万里昆崙倾不足。", "春妍睡醒鳞甲开，顷刻已放波头来。冲梢掠操何迅速，喷云溅雪争崔嵬。", "舟人传呼隘两岸，骇若百蛰逢惊雷。连桩系缆犹恐脱，不尔船碇俱倾颓。", "须臾水面如平掌，客子棹歌船下上。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观鹤舞","p":"","d":"清代","a":"永珹","c":["幽人惯调鹤，散步临前墀。兴来观其舞，开笼无常期。", "胎仙若解意，小立修容仪。徐焉顿修趾，双翮俄参差。", "暂离芳春地，不上乔松枝。徘徊弄逸态，宛转矜殊姿。", "惊鸿方振迅，翔凤偏威垂。烟雾隐芝圃，风雨生瑶池。", "讵嫌心目眩，祇觉精神移。轩翥亦已久，敛翼还自持。", "横空骋天步，华表忘归时。顾念驯养恩，云外凭招之。", "低徊同戏彩，不愧林家儿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"泊苍梧","p":"","d":"明代","a":"何绛","c":["重过苍梧客，扁舟一夜心。山川犹昨日，难对在高深。", "芳草绿新恨，春风吹旧林。岂无同旅泊，谁识此宵吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与生公游石窟山","p":"","d":"唐代","a":"张九龄","c":["探秘孰云远，忘怀复尔同。日寻高深意，宛是神仙中。", "跻险构灵室，诡制非人功。潜洞黝无底，殊庭忽似梦。", "岂如武安凿，自若茅山通。造物良有寄，嬉游乃惬衷。", "犹希咽玉液，从此升云空。咄咄共携手，泠然且驭风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"皇帝阁春帖子","p":"","d":"宋代","a":"许应龙","c":["东风昨夜扫氛埃，四表咸欣寿域开。", "都护已飞三捷奏，凌烟同上万年杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百六十首","p":"","d":"宋代","a":"释宗杲","c":["夜来兔子赶大虫，天明走入无何有。", "月下珊瑚长数枝，万象森罗齐稽首。", "拄杖子，不唧{左口右留}，", "渠侬却善分妍丑。李公烂醉绝倒时，", "元是张公吃村酒。报诸人，", "急回首，切忌疾狂外边走。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"残冬展假病榻消寒聊当呻吟语无伦次录存十六章 其三","p":"","d":"清代","a":"查慎行","c":["茫茫大地托根孤，只道烟霄是坦途。短袖曾陪如意舞，长眉难画入时图。", "移镫见蝎宁防毒，误笔成蝇肯被污。窃喜退飞犹有路，的应决计莫踌蹰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"食鲙","p":"","d":"宋代","a":"刘挚","c":["知几张季鹰，归怀托江鲙。鲈鱼今不数，未若鲂鲫最。", "橙齑捣椒兰，芦菔碎珠贝。盈盘玉叶铺，千缕红云碎。", "佐以晚菘羹，玉饭香蔼蔼。饱行惭素餐，扪腹放衣带。", "昨来溪夏乾，市空无可奈。徒有弹铗吟，何能饱幼艾。", "安得东海鲸，不惮生物害。挥刀满金盘，对列酒池外。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵李子建怀归","p":"","d":"宋代","a":"李若水","c":["寸心已老自宜休，误别云山岁几周。", "疏远骤依双凤阙，清贫仅剩一貂裘。", "与人不偶缘方凿，於世无求类直钩。", "何日张帆旋故国，坐呼明月醉江头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和泽民二首","p":"","d":"宋代","a":"吴芾","c":["欲绍家声每自鞭，肯同流俗饮贪泉。", "已将止足安心地，更把吟哦乐性天。", "笑日桃花将献媚，先春梅蕊欲争妍。", "人生会合真难遇，幸有杯觞且共传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢惠笋","p":"","d":"宋代","a":"刘黻","c":["饥肠数日吼，往往茄苋争。", "幽人盼寂寥，饷我慈竹萌。", "斑斑未离绷，白下莫与京。", "寒泉煮青茆，手调玉版羹。", "招僧招不来，贳洒乃独烹。", "茄苋避三舍，纸帐午梦宁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"道傍丛祠榜云老人庙","p":"","d":"宋代","a":"张镃","c":["里俗崇祠想报功，袍鞾包裹雪髯翁。", "休嗟事始无人识，纵有丰碑亦是空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"先生自费城寄书有吾其左衽矣之叹占此奉告","p":"","d":"近代","a":"傅子馀","c":["老向天涯作幸民，一书投我感常新。国危但保东迁地，礼失同为左衽人。", "倘许衡山重拄杖，何如香海共垂纶。莺飞草长当三月，梦断江南草木春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题苏武牧羝图","p":"","d":"清代","a":"戴亨","c":["苏卿奇节古所无，丹青为写当年图。手持汉节节旄落，驱羝就牧阴山枯。", "朔风如刀砭肌骨，瀰漫浩雪埋穹庐。蚩尤愁惨作妖雾，老狐叫啸群邪趋，孤臣万里将何如。", "鸾凤罹笯龙受缚，久𢬵肝脑涂沙漠。阴阳为炭天为炉，险阻巅危笃攻错。", "陶铸伟器撑乾坤，讵比凡材任销铄。终教皓首复归来，千秋万祀声隆赫。", "君不见李陵歌送褰行裾，仰天泣血空欷歔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题也休庵 其二","p":"","d":"宋代","a":"释怀深","c":["唱歌楼上语风流，你既无心我也休。打著郎君心里事，从前恩爱冷啾啾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东归歌送郑子经","p":"","d":"元代","a":"陈旅","c":["北风吹山蕉叶黄，长亭野日寒荒荒。驱车送子归故乡，人生此处堪断肠。", "旧游回首秋山下，醉帽簪花同走马。欢娱如此离别何，华月芳年不堪把。", "子今去矣来何时？翠壶云深那可知。向来亦有燕山期，子今去矣来何时！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"香山","p":"","d":"近代","a":"沙曾达","c":["报道山花次第开，美人曾许采香来。吴王韵事留幽径，喜拥蛾眉醉绿醅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十一月朔与钱国辅江门观涨","p":"","d":"明代","a":"陆深","c":["水槛漂垂钓，江门不掩风。望穷东海若，身拟烂银宫。", "浴日中流急，浮天一苇通。鱼龙吾得免，消息任虚空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜z6公自武陵至","p":"","d":"唐代","a":"齐己","c":["已尽沧浪兴，还思相楚行。鬓全无旧黑，诗别有新清。", "暂憩临寒水，时来扣静荆。囊中有灵药，终不献公卿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赞三宝","p":"","d":"宋代","a":"释印肃","c":["直指人心亲见佛，何劳打瓦作龟爻。", "一片白云横谷口，几多归鸟尽迷巢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"芙蓉","p":"","d":"宋代","a":"释居简","c":["溪痕寒不肥，岸容晚益退。其谁怜婆娑，明霞剪零碎。", "烂烂饱泠露，酣酣俯清濑。宛然古铜碧，嫣然靘妆对。", "又若翠袖薄，瘦立烟渚外。西风仅如许，晚节尚可待。", "遂拜拒霜号，不受断肠浼。亦岂无老成，试请推行辈。", "桂腾小山馥，菊耀东篱采。裳衬芰荷衣，服称陆离佩。", "芳芷雅相乡，宿莽安敢背。花城隔仙凡，俗说信茫昧。", "独有离骚经，名氏得先载。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早秋二绝","p":"","d":"宋代","a":"寇准","c":["一听早蝉响，坐悲芳岁阑。", "新秋空索寞，前事但心酸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冬日","p":"","d":"清代","a":"费墨娟","c":["寒风扑面冷难支，百感营心岁暮时。欲破愁城无别计，围炉煮雪漫敲诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六丑 和天琴","p":"","d":"清代","a":"沈曾植","c":["倚银屏数梦，袅万种春愁如发。三峰夜游，青天通箭筈。", "嘉平仙腊。谁织扶桑瓮，投壶玉女，亸烟鬟月押。东南孔雀楼西北。", "云外惊鸿，阑前斗鸭，长亭柳稊都茁。恨春风婀娜，不到天末。", "青霓谁达，闷琼宫瑶闼。珠箔飘灯夜，双泪蜡。当时照见灵札。", "恁素书沈鲤，玉床眠獭。海霞热，小桃丹靥。总误了春人十载，望春眉睫。", "红心草绿灰飞蝶。向玉京，魂抱离忧诉，碧翁醉煞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙","p":"","d":"当代","a":"陈伟强","c":["一缕春痕浓又淡，水窗渐渐黄昏。缟衣重著对兰熏。", "月华都化雾，海气欲成尘。", "梦入桐花深树里，有人浅笑轻颦。落英万点付朝云。", "玉颜终忘了，难忘旧星辰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜期友生不至","p":"","d":"唐代","a":"姚合","c":["忍寒停酒待君来，酒作凌澌火作灰。", "半夜出门重立望，月明先自下高台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"树头鸦舅鸣","p":"","d":"元代","a":"谢应芳","c":["树头鸦舅鸣，农人起耘苗。问之何尔忙，良田莠骄骄。", "去年耘较迟，草蔓全力寡。稂莠非不除，卒以害吾稼。", "吾闻农人语，猛省天下事。养虎当害人，玩寇亦如此。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄婺州周知录","p":"","d":"宋代","a":"林季仲","c":["不到东阳六七年，干戈身世两依然。", "每思三虑堂中退，径向双溪楼上眠。", "空翠霏微浮酒斝，林烟杳霭没渔船。", "有人问我今何似，头秃昏昏瘴海边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠沈稚咸","p":"","d":"明代","a":"徐熥","c":["爱君蓬荜绿萝閒，住近枫桥第几湾。短屐一春游茂苑，疏钟半夜听寒山。", "门多词客寻诗至，寺有高僧乞画还。数顷烟波满船月，歌声来往水云间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怨辞（二首）","p":"","d":"明代","a":"景翩翩","c":["妾作溪中水，水流不离石。", "君心杨柳花，随风无定迹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜梦一道人见访相与语甚久颇及宗乘中事因戏之曰仙家亦学佛耶其人笑曰仙佛岂有二哉觉而异之作诗纪其事","p":"","d":"宋代","a":"刘才邵","c":["北风吹云肃天宇，蕙帐寒生月当户。颓然就枕睡思浓，魂梦悠悠迷处所。", "仙宫胜士肯见临，促席从容陪软语。自言本事清虚君，学佛求仙两无阻。", "云軿白日降遥空，天衣飘飘袖轻举。方诸宫深云海阔，金碧禅房隔烟雨。", "与君粗有香火缘，聊复东来相劳苦。方游昆阆还无期，君住世间须善为。", "尘劳足厌不须厌，等是实相夫何疑。前身自是尘外人，端为世缘縻此身。", "重闻妙语发深省，若更离尘佛亦尘。方平羽节何时来，道宫佛庙随烟埃。", "未须苦说扬尘事，东海波声正似雷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书座自警四首 其二","p":"","d":"明代","a":"王渐逵","c":["勿尔苗稚，其舒则扬。勿谓暗室，其居则明。淑慎尔正，谑浪匪臧。", "先民有言，贾用是臧。毋弃其庸，维德不爽。维德不爽，神式其享。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清泉兄将赴营口高就葆国兄为其饯行予与士海先生作陪限押京字","p":"","d":"当代","a":"吴金水","c":["别后烟波接北冥，年年六月海潮生。扶摇九万知他日，潋滟千杯尽此情。", "天外长云春浩荡，胸中爽气势纵横。丈夫四海为家惯，何必流连向帝京。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酌别张子元二首","p":"","d":"宋代","a":"李昴英","c":["去冬初去国，逆旅等顺境。", "祸机众危之，沙蜮伺人影。", "拂衣肯同归，荒驿灯夜永。", "幸脱妖蟆口，黑月重磨镜。", "勤君再行役，我愧心耿耿。", "陛下皇明穹，贤聚纤邪屏。", "石渠盛此士，岂复松厅冷。", "胸中贮奇策，可以靖边警。", "平生羞辕驹，看取囊露颖。", "堂堂曲江翁，芳躅在梅岭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送儿沆再之婺","p":"","d":"宋代","a":"陈著","c":["父母生汝期望汝，地阔天宽从著步。", "霜叶飞红橙橘黄，一笠西风正宜路。", "送汝出门不肯行，低头进前出苦语。", "双亲虽安身已高，菽水为欢盍朝暮。", "夏初奉命见两山，往还恨不身生羽。", "如今又为千里行，直是恋慕难轻去。", "有不忍听手抚背，至哉天理人伦处。", "我岂欲汝寸步难，事有乘机恐差误。", "晚年正欲汝有成，此行倘与心相副。", "皱皮瘦骨便精神，当为汝喜非汝惧。", "不妨安稳趁前程，但及梅花时归学莱舞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题百官步","p":"","d":"宋代","a":"李光","c":["晓雨微茫水接天，隔江茅店有炊烟。杖藜独上沙头路，犹记当时赶渡船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又和松碧轩三绝 其三","p":"","d":"宋代","a":"胡寅","c":["新陂剩水沃良苗，想见当时相杵谣。尚有荒馀须快犊，何须塌具更悬腰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋得太湖春水送华以及岁贡","p":"","d":"明代","a":"谢晋","c":["浩浩来天日，溶溶接汉津。光随征棹远，绿染客袍新。", "瑞气初销腊，恩波总是春。明朝禹门外，一跃有谁论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉楼春 夜坐","p":"","d":"近代","a":"丁宁","c":["青灯如死繁音息，意海恬流时起灭。微茫炉火曙天星，寥落门庭秋树叶。", "昏鸦不识中宵月，绕遍空枝还喋喋。几回忍泪嗅残梅，绰约孤芳寒似雪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高邮别子相","p":"","d":"明代","a":"王世贞","c":["回轸出君方，脩途意弥恻。浮云莽互驰，奄然羲轮匿。", "中夜理夙炊，惋恋不能食。往遘岂乏欢，念若遗行迹。", "姣服谐奇慕，安能顾掩抑。举世各自矜，娟情无终极。", "脉脉睹何言，察此眉间色。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"百字令","p":"","d":"近代","a":"顾随","c":["屋山起伏，正沈沈无际，黯淡如铅。向晚阴云低压处，横空几道苍烟。", "冻解长河，冰流春水。减得几分寒。绕廊徐步，隔窗闻弄哀弦。", "见说山水清音，楼台胜境，自古让神仙。争奈自家尘福浅，谁教偏住人间。", "四载明湖，三年东海，二月杏花天。眼前何物，雪花飞上阑干。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"伯量同二弟欲见访湖庄以诗告至褒拂过情辄次其韵 其三","p":"","d":"宋代","a":"曹彦约","c":["年来夺锦马群空，而况君家有八龙。传与乡人经济策，问焉何惜少舂容。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题桃叶渡江图","p":"","d":"清代","a":"王丹林","c":["细雨横塘记昔过，画图开处奈愁何？桃花一簇红无主，春水三篙绿始波。", "解佩清狂馀仿佛，溅裙宿约竟蹉跎。由来兰桨无情物，锦瑟华年送已多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"甘州•舍弟仲由于役幽燕，道经上海，信宿而别","p":"","d":"清代","a":"陈匪石","c":["正潇潇、暮雨作新秋，西风动江城。对当窗明烛，匡床碎语，浊醑深擎。", "别绪丝丝未理，津鼓促征程。帘外飞鸿过，寒阵初惊。", "姜被当年重认，渺故园一角，梦委荒荆。问天涯投老，踪迹几回并。", "望长安、浮云千态，幻海波、愁蔽晚山青。伤高泪，劝须臾忍，休洒新亭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"仙人隐迹 其二","p":"","d":"宋代","a":"吴洞明","c":["长生玄牝门，目击而道存。班班实可考，老涧生云根。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"□李文昭不遇","p":"","d":"明代","a":"张弼","c":["桃径参差曲到门，半湾流水欲成村。主人何处空诗案，花扑晴帘护暖云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀旧三首 其三","p":"","d":"近代","a":"杨赓笙","c":["记得蒲青艾绿时，故交先识顺昌旗。果然入境称张禄，未及成功作范蠡。", "筠岭饱看千个竹，梅关空塞一丸泥。要知军阀倾颓处，全局先输此著棋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大堤曲","p":"","d":"明代","a":"李裕","c":["大堤堤上多杨柳，大堤人家都市酒。纷纷女儿秾艳妆，唱拨琵琶露纤手。", "舟子收帆夜泊堤，少年估客心恋迷。折花酣酒醉不醒，黄金掷尽不能归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水龙吟 其三 落叶","p":"","d":"宋代","a":"王沂孙","c":["晓霜初著青林，望中故国凄凉早。萧萧渐积，纷纷犹坠，门荒径悄。", "渭水风生，洞庭波起，几番秋杪。想重涯半没，千峰尽出，山中路、无人到。", "前度题红杳杳。溯宫沟、暗流空绕。啼螀未歇，飞鸿欲过，此时怀抱。", "乱影翻窗，碎声敲砌，愁人多少。望吾庐甚处，只应今夜，满庭谁扫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵何符山人二首","p":"","d":"宋代","a":"陈造","c":["门下轩裳不转头，何人皮底著阳秋。", "独烦客子冲泥屐，屡到衰翁听雨楼。", "从昔诗声追正始，即今宾友验宣州。", "清篇快读强人意，未觉京尘厌薄游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"济尔哈朗图行宫作 其二","p":"","d":"清代","a":"弘历","c":["纳稼田馀柄穗多，富秋历阅喜无过。一溪流水村前绕，四面晴山户外罗。", "便犒诸藩歌湛露，兼宣翰苑咏卷阿。苏门审势差相似，不约而同安乐窝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"毗陵郡斋追忆卿味","p":"","d":"宋代","a":"杨万里","c":["坐无黄雀牛尾狸，荆溪日日思江西。", "若无鹅梨与海错，江西却恐思荆溪。", "旧居江西不自惜，到得荆溪却追忆。", "明年官满归江西，却忆荆溪难再得。", "江珍海错各自奇，冬裘何曾羡夏絺。", "鹅梨黄雀无不可，荆溪江西不关我。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"省躬诗 其十六","p":"","d":"明代","a":"曹于汴","c":["孟子善养气，此气即此理。禀气人人知，理则远言取。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿谖为辰州李贡士民望作","p":"","d":"明代","a":"符锡","c":["萱草树北堂，谓能忘远忧。如何念慈母，不置天西头。", "楚山高高楚水长，西风晨夕雁南翔。帛书不事慰脩阻，忘忧愿祝寿且康。", "他日拜官来故里，门户光生母心喜。九溪会变作春酒，白发青袍放歌起，何如更向天涯咨陟𡵆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂兴四首","p":"","d":"宋代","a":"于石","c":["屋上青山屋下云，清泉为镜石为屏。", "客来问我谋生计，一卷家传相鹤经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赵总戎见惠巨鳊酬之以诗","p":"","d":"明代","a":"韩雍","c":["缩项鳊鱼味最珍，长江六月尤难得。波涛汹涌风力劲，渔人举网空费力。", "元戎统师百万行，秋毫无犯严戒饬。庖厨空虚河伯知，故遣嘉鱼助鲜食。", "我曹忝陪旌旆行，此味从来不曾识。元戎驰赐捧玉盘，烹来大嚼深感激。", "吁嗟此物成百头，真乃神灵来效职。威声从此收南邦，蜂屯蚁聚休言贼。", "草草题诗谢来意，纸短情长苦相逼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和景仁七十一偶成","p":"","d":"宋代","a":"司马光","c":["心地长闲为己物，年华不驻是天时。", "当时海上乘槎客，维楫都无行所之。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游上野博览会二首 其二","p":"","d":"近代","a":"蔡寅","c":["可怜风月太平年，只许今生海外缘。不忍池边春潋滟，通天桥上客翩跹。", "三千弱水曾经眼，十二琼楼笑拍肩。的的明灯真不夜，万花丛里赛婵娟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冬至宿杨梅馆","p":"","d":"唐代","a":"白居易","c":["十一月中长至夜，三千里外远行人。", "若为独宿杨梅馆，冷枕单床一病身。"],"tags":["古诗里的十二个月"],"z":"","y":"","s":"","k":"诗"},
  {"t":"快亭","p":"","d":"宋代","a":"释德洪","c":["太丘作邑付弦歌，剩得清闲可奈何。满地棠阴惊昼永，小亭诗眼觉天多。", "佳眠夏簟便光滑，醉耳松风喜再过。想见句成书棐几，侍儿浓笑出微涡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次友人张孟善承赠以诗韵","p":"","d":"元代","a":"丁鹤年","c":["去去成长往，悠悠事远游。蹑云双短屐，载月一虚舟。", "江海鱼龙夜，山林鹤鹤秋。诵君佳丽句，慰我别离忧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋夜","p":"","d":"明代","a":"王邦畿","c":["未得平情学，年来积感深。静中知肺病，夜半喜秋霖。", "竹响摇清梦，兰香披素襟。明朝拉朋好，高蹑北山岑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"明堂侍祠十绝 其五","p":"","d":"宋代","a":"杨简","c":["玉佩珊珊出禁扉，金莲分炬散芳菲。祠班咫尺临黄道，惹得天香满袖归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"阮郎归","p":"","d":"宋代","a":"刘子寰","c":["长条袅袅串红绡。无风时自摇。十分娇艳更苗条。殢春情态娇。", "风影舞，露痕潮。买来和蝶饶。故园愁绝楚宫腰。相逢恨怎销。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄家书","p":"","d":"清代","a":"王庭诏","c":["一函游子泪痕封，寄去云山几万重。君到鹤洲江上望，数椽茅屋几株松。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送僧怀善","p":"","d":"宋代","a":"刘摰","c":["独鹤翩无累，孤云晚倦飞。群山带江处，一锡背尘归。", "妙学穷神秘，高怀熟世机。漳滨多病客，空此望岩扉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同心结三章送林德敷赴齐东 其一","p":"","d":"明代","a":"郑善夫","c":["文旗出郭门，念子赴齐东。揽衣起踯躅，叹息不得同。", "凤麟久增逝，爰居亦避风。冥运方险艰，去去随短蓬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠小儿医","p":"","d":"宋代","a":"洪咨夔","c":["忍饥觅句孟东野，守叔草玄杨子云。", "囊有遗收无与读，两家恨不早逢君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"为郭元德题和靖探梅图","p":"","d":"宋代","a":"俞德邻","c":["祥符真人调玉烛，四海八荒春意足。孤山山小不容春，十月梅花破寒玉。", "风流诗老癖爱梅，拂晓骑驴度山曲。呼童忍冻折南枝，香满吟窗伴幽独。", "到今写入画图中，骨冷神清炯双目。荡荡巍巍尧舜天，外臣巢许谁羁束。", "前年我亦访湖山，山色湖光竟尘俗。荒坟三尺走狐狸，那复寒泉荐秋菊。", "真祠并入梵王家，香月亭前马牛牿。水边篱落忽横枝，遥睇犹艰况斤斸。", "鸡园释子皆鹰腾，挟弹扬鞭骤平陆。仓皇走避尚遭嗔，蹇卫何堪共驰逐。", "三百年间一梦同，人与梅花几荣辱。拊图三叹复何言，天外飞来两黄鹄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹊桥仙（为人庆八十席间戏作）","p":"","d":"宋代","a":"辛弃疾","c":["朱颜晕酒，方瞳点漆，闲傍松边倚杖。不须更展画图看，自是个、寿星模样。", "今朝盛事，一杯深劝，更把新词齐唱。人间八十最风流，长帖在、儿儿额上。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"为秦伯未之济画梅繫以截句四首 其一","p":"","d":"清代","a":"曹家达","c":["休将往迹问林逋，老鹤归来觅旧株。除是孤山一卷石，不随春涨过西湖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"折槛行送沈纯父北上","p":"","d":"明代","a":"胡应麟","c":["北风动地捲霜雪，沈子严装候明发。白马银鞍走燕市，天子召见黄金阙。", "忆昔丁丑年中事，呜呼已往难陈说。纲常万古忽如线，沈子旁观眦双裂。", "三年忍蔑父母爱，七尺自与妻儿诀。飞书一夜上明主，百辟苍皇胆俱慑。", "宫闱动色问忠悃，乞得残躯傍南粤。茫茫大海天欲尽，野魅山魈共生活。", "铜柱频更伏波戍，铁衣乱洒羁臣血。桄榔叶底托馀荫，豆蔻枝前赋鶗鴂。", "鬓毛五载凋欲尽，意气千钧莽难折。离骚熟读引斗酒，怒击青萍唾壶缺。", "云雾朝披博罗顶，星斗夜摸空同峡。归来笑拥绿衣女，卢橘杨梅照红颊。", "朝云已去学士还，瘴雨蛮烟护荒碣。精忠大节岂重睹，文藻风流颇颃颉。", "乾纲一振壬午岁，地辟天开走狐孽。徵书九道发燕邸，尽起龙干布朝列。", "是时沈郎奉明诏，长啸扁舟返西浙。逡巡故国拜丘垄，问寝高堂痛离阔。", "县官日夜戒行李，驿使交驰讯车辙。男儿肯作里中老，直臣更树台端节。", "同时吴赵艾与邹，騄駬飞黄并腾踏，沈郎讵得终岩穴。", "天上仙查溯河汉，腰下刀环耀明月。扬鞭再过五陵豪，击筑重招蓟门侠。", "蓟门楼殿花三千，尚记公车抱长铗。对策明光亦草草，敝履短衣行䠥𨇨。", "中原邂逅吾共尔，白眼红颜寸衷合。诵余连璧心已醉，示我郊居思横发。", "苍茫大雪华阳街，拂袖徐生馆中别。风尘倾盖古则有，宇宙论心近谁洽。", "即今汝燕余复越，抗手胡能不悲咽。沈伯子，酌汝蒲萄之美酒，系汝珊瑚之宝玦。", "一言赠汝中自知，此去中外望掀揭。儿童走卒尽道汝，凛凛刚肠石与铁。", "腰金拖玉宁汝事，义胆忠肝岂虚设。三公九列贵易保，万姓千秋口难辍。", "重华尚纳大禹戒，仲甫亦补周王阙。朝多善政禄可飧，事有当言槛仍折。", "风云况遇大行日，努力群龙树勋业。竹帛旂常两光绝，一旦抽身蚤林樾。", "丈夫出处须伟烈，呜呼丈夫出处须伟烈，异日儒生秉鈇钺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵胡彦明同年羇旅京师寄李子飞三章一章道","p":"","d":"宋代","a":"黄庭坚","c":["看除日月坐中铨，一岁应无官九迁。", "葱韭盈盘市门食，诗书满枕客床毡。", "留连节物孤朋酒，恼乱邻翁谒子钱。", "谁料丹徒布衣得，困穷且忍试新年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"摊破丑奴儿 纪艳","p":"","d":"清代","a":"陈维崧","c":["隔帘挼碎相思苣，斜著乌云。漾著红巾。袅袅亭亭一段春。", "是耶，难道是、昨宵人。", "戟门阖却葳蕤锁，花气氤氲，月色缤纷。墙角猧儿吠夜分。", "非耶，谁道是、昨宵人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"先忠端公祠堂落成王明府蒿伊命广文沈令辰摄二月丁祭 其三","p":"","d":"清代","a":"黄宗羲","c":["黄竹浦间几劫灰，祠门正对舜江开。土人不识忠魂返，但讶天边雪浪来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题周鲲仿唐寅终南十景图 其八 涤烦矶","p":"","d":"清代","a":"弘历","c":["万木郁蜚云，众泉泌鸣玉。拂轸试一写，不作招隐曲。", "境寂夫何妨，高人乐事足。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙　横铺泳归作","p":"","d":"当代","a":"卢青山","c":["日暮清流泳始还，河中剩有一痕山，岸边随手摘荷玩。", "谁要苍烟浮稻陇？渐无夕照下鱼湾，蜻蜓独自过桥栏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送刘玉桥北上","p":"","d":"明代","a":"文嘉","c":["岁晚江空岸草枯，故人舟楫向皇都。相逢不尽相违意，写得天寒欲雪图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟曹子建赠白马王彪六首 其四","p":"","d":"清代","a":"缪祐孙","c":["明哲本犹人，涕泪对昊天。幸赖人命长，豫顺久则然。", "洒泪伤子弟，雕零蒲柳先。戕责属伊谁，未免徒自怜。", "魂魄返旧居，应识路绵绵。大海汇百川，乃有精卫填。", "高岸虽崔嵬，为谷伤他年。逝者不复追，此恨畴能捐。", "懿德良不渝，努力志圣贤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其九","p":"","d":"宋代","a":"魏了翁","c":["一位肴羞酒一卮，祠官熏灌祝陈词。降升六拜焚词罢，六日精神用一时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"茅山书屋为项德懋题","p":"","d":"明代","a":"罗玘","c":["满山生白茅，茅白山亦白。维翁养默惯，分与尘世隔。", "拔茅覆山椒，牵萝缉茅壁。面壁梦周孔，冥心契羲画。", "茅疏壁缭多，缺月瞰深夕。百年翁骨寒，山鬼夜敲石。", "鼻耳真贯穿，诛茅掘遗磶。见磶如见翁，护磶如护璧。", "一磶复一柱，吾当陋晋籍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读史三首 其二","p":"","d":"元代","a":"何中","c":["嬴法四海热，震荡昏三光。云飞大风起，赤子沐清凉。", "当时周旋人，一瞰罹身殃。悠悠赤松子，不识为何祥。", "千年有崔浩，前修持自彰。岂知愧所事，乃是元家王。", "恐非凤衔图，但见雁求梁。伊尔山中人，勿弃兰蕙芳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉泉山杂咏十六首 其四 观音洞","p":"","d":"清代","a":"弘历","c":["何处飞来此落伽，默然不更转三车。设云义谛无馀转，者个非忘见转差。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题月夜鸣琴图为庄知州赋","p":"","d":"明代","a":"倪谦","c":["空山无人秋夜凉，银河荧荧流月光。苍龙百尺落松影，松梢露滴沾衣裳。", "幽人中夜耿不寐，起抱丝桐幽思长。坐据苔石不知泠，横膝对月调宫商。", "山高水深趣未已，谁其知者同徜徉。七弦不尽太古意，下听独有仙娥嫦。", "调高馀响振山谷，啼鸟惊起争飞翔。夜深欲鼓广陵散，斜月半落山苍苍。", "呼童抱琴且归去，净扫白云眠石床。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归至镇远次祁石阡荅家人相慰藉韵","p":"","d":"明代","a":"周瑛","c":["一官飘泊共遐荒，文事驱人偏自忙。藜杖远分天禄火，梅诗旋入镇阳装。", "形骸莫逆怜同道，萍水相逢忘异乡。为语家人莫惊讶，鬓毛原带去时霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"锦镜池","p":"游雪窦杖锡七首","d":"宋代","a":"陈著","c":["万仞崖擎碧玉台，中閒一镜帖天开。", "四时自与幽花对，一点时妆不照来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题资福院平绿轩","p":"","d":"宋代","a":"曾揆","c":["终日劳劳雁鹜行，偶然来访赞公房。", "扶疏草木四围合，萦绕溪流一带长。", "倚槛岂能成杰句，把杯多是说名方。", "问师乞取安心法，宴坐蒲团对佛香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿土坊驿寄孔世长","p":"","d":"宋代","a":"王安石","c":["烧夜郊原百草荒，弊裘朝去犯严霜。", "残年意象偏多感，回首风烟更异乡。", "往返自非名利役，辛勤应见友朋伤。", "章江犹得同游处，最爱梅花蘸水香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"如果","p":"","d":"近代","a":"席慕容","c":["四季可以安排得极为暗淡", "如果太阳愿意", "人生可以安排得极为寂寞", "如果爱情愿意", "我可以永不再出现", "如果你愿意", "除了对你的思念", "亲人和朋友", "我一无长物", "然而", "如果你愿意", "我将立即使思念枯萎", "断落", "如果你愿意", "我将", "把每一个河流都切断", "让荒芜干涸延伸到无穷远", "今生今世", "永不再将你想起", "除了", "除了在有些个", "因落泪而湿润的夜里", "如果", "如果你愿意"],"tags":["爱情", "思念"],"z":"","y":"","s":"","k":"诗"},
  {"t":"驿骑传诗图为黄太守丈题","p":"","d":"清代","a":"姚燮","c":["潮阳多悍民，蚁斗恣愚蠢。刑法藐官吏，有司策惶窘。", "丁年闰五月，野啸动荒巘。一鬨蹈危刃，老稚半墨膑。", "太守率虎旅，峨冠驻罘䍐。名熟军中韩，胆已慑强忍。", "斯时霉伏交，苦瘴郁蛮蜒。烟箐坐蛇穴，日炙气凄紧。", "军书间旁午，陟冈揽牛纼。揭阳指烟郭，瓦屋故人近。", "大风啸林薄，长歌振颓坋。纵笔草龙蛇，擘笺束如笋。", "急羽授铃骑，空匆走羊坂。一瞬四十里，云天落飞隼。", "丛溪虎贴尾，北斗照䉋箘。霜声奏传鼓，城马忽传返。", "屯兵镇沈肃，文光耀焱焜。雅歌谁投壶，草檄几磨盾？", "不意驰突中，华辞出警敏。披图相其势，岩栈互嶾嶙。", "佳话后谁继，壮怀去无尽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感怀","p":"","d":"清代","a":"于豹文","c":["四十年来事，凄然暮雨中。飞腾惭去鸟，萧瑟近衰翁。", "敢谓诗书误，羞云篆刻工。寥寥千载上，此意竟谁同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"閒居","p":"","d":"明代","a":"王宠","c":["绕舍扶疏千树林，古台莺语昼沉沉。山童佐舞调双鹤，病客閒居戏五禽。", "阮籍猖狂雠礼法，仲长乐志薄朝簪。凭高更觉青冥远，弋者徒闻黄鹄音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洞仙歌 去冬无雪，新岁乃稍稍见，正月二十","p":"","d":"元代","a":"袁易","c":["与勉夫对坐萧齐，即景漫赋江枫汀树，挂寒云零乱。天阔谁填莫愁满。散玉尘千斛，装□柴门，堪笑处、天女多情恨晚。灞桥丝样柳，恰试鹅黄，笛里东风便吹断。莫话剡溪船，乘兴归来，早闲了落梅庭院。爱搀占西园做飞花，又不道春光，"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题沈启南赠尹孟容画","p":"","d":"明代","a":"史鉴","c":["天水吴兴两地悬，椷诗遥作买山钱。峰峦满纸新题遍，乔木依然在涧边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵湖山居士见过","p":"","d":"宋代","a":"释德洪","c":["平昔云岑在怀抱，而今怀抱在云岑。闻泉偶尔成诗句，班草相看坐木阴。", "古鼎自然无俗韵，朱弦真是有遗音。羊欣不肯踏城市，背郭江村独见寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金丹诗四十八首","p":"","d":"宋代","a":"张继先","c":["不觉年年撚指过，急如催浪转长河。", "鼎中日月知人少，世上阴阳识者多。", "尽为资财损真性，皆因女色逐流波。", "□□半有归泉路，忍把真元乱鬼魔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"某顷知黄州墨卿为州司录今八年矣邂逅临川送别二首 其二","p":"","d":"宋代","a":"韩驹","c":["盗贼犹如此，苍生困未苏。今年起安石，不用哭包胥。", "子去朝行在，人应问老夫。髭须衰白尽，瘦地日携锄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"时雨三首 其一","p":"","d":"宋代","a":"张侃","c":["旬日风消雨，今朝山出云。柳深开润色，荷靓匝清芬。", "江燕新调语，沙鸥自引群。农人相贺语，田亩可耕耘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"下元节后省试进奏院吏","p":"","d":"宋代","a":"洪咨夔","c":["推云不动雨声苦，醖雪未成风力乾。", "瘖鹜一庭淘墨汁，也烦老子坐深寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李遵道海岳图","p":"","d":"元代","a":"郑元祐","c":["李黄岩，疏眉瘦体满臆秋崭崭。似厌分符涧谷底，折腰督邮面皱须毵毵。", "竟骑鲸鱼上天去，帝悯人间留不住，乃令笔底飞墨如云雾。", "王维郑虔本有素，早年临摹米颠海岳图。黄岩非有颠非无，庵空月落山木拥，是中疑有穷猿呼。", "二子风流俱不泯，宝月夜夜生珊瑚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居志感（二首）","p":"","d":"明代","a":"石林瑛公","c":["嘉蔬值我园，好鸟巢我树。", "树枯鸟惊栖，园荒蔬委路。", "寒气肃山林，新芳飒然故。", "物理有固然，于何起欣恶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵赵明叔喜雨不寐","p":"","d":"宋代","a":"周紫芝","c":["云忽油然雨沛然，黄童白叟尽成颠。唤晴鸠妇鸣屋角，饱水秧孙明稻田。", "御史平冤魂亦喜，弘羊言利死谁怜。草玄窗下子扬子，凉入孤灯夜不眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日闲居作四声诗寄袭美。平声","p":"","d":"唐代","a":"陆龟蒙","c":["荒池菰蒲深，闲阶莓苔平。江边松篁多，人家帘栊清。", "为书凌遗编，调弦夸新声。求欢虽殊途，探幽聊怡情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居杂兴五首 其五","p":"","d":"明代","a":"郑潜","c":["读书岂在多，适用一编足。君听刍荛言，可备太史录。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游长安诸寺联句。崇义坊招福院。赠诸上人联句","p":"","d":"唐代","a":"段成式","c":["翻了西天偈，烧馀梵宇香。撚眉愁俗客，支颊背残阳。 ——段成式", "洲号惟思沃，山名只记匡。辨中摧世智，定里破魔强。 ——张希复", "许睿禅心彻，汤休诗思长。朗吟疏磬断，久语贯珠妨。 ——段成式", "乘兴书芭叶，闲来入豆房。漫题存古壁，怪画匝长廊。 ——张希复"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和邠老郎官湖怀古五首","p":"","d":"宋代","a":"贺铸","c":["昔人泯黄壤，陈迹变沧波。", "劫火洞然坏，无如嘉句何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄曹参军 其二","p":"","d":"明代","a":"佘翔","c":["结客谈兵幕府才，蹉跎宦迹转堪猜。独醒总为风尘忌，湖上兰桡醉几回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠鹤林上人","p":"","d":"明代","a":"刘崧","c":["日日涧边寻茯苓，岩扉长掩凤山青。归来挂衲高林下，自剪芭蕉写佛经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"无题次邱工部韵八首 其三","p":"","d":"清代","a":"林朝崧","c":["品在环肥燕瘦间，三千粉黛料难攀。梦中几度经沧海，镜里何由保蕣颜。", "乌鹊无依空绕树，蘼芜欲采懒登山。平生待字深闺日，肯信丹青尔许閒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送谢祭酒之任南雍","p":"","d":"明代","a":"王鏊","c":["峻节高怀自可亲，两年史馆况为邻。久甘静退元非病，稛载诗篇亦未贫。", "台右人才多近古，当今师道复何人。看详学制伊川在，士子东南要一新。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自槜李至毗陵道中","p":"","d":"宋代","a":"杨冠卿","c":["满目江山无限情，夫差城郭暮云平。", "当时不竞黄池长，一再何由致越兵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"人有为石梁谣者录成 其十五","p":"","d":"明代","a":"郑真","c":["别来三月不见郎，夜灯明灭泪成行。妾身许得单衣愿，不怕穷冬有雪霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词一百首","p":"","d":"宋代","a":"岳珂","c":["洛京韫椟起儒珍，地讲忠规德日新。", "禁苑金丝舞垂柳，万方已被发生仁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"如梦令","p":"","d":"清代","a":"濮文绮","c":["昨夜晓窗寒甚。紫燕弄巢不定。何处觅东风，梦过月塘烟径。", "休问。休问。耽误梅花春病。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"惜寒梅","p":"","d":"清代","a":"汪东","c":["万卉凋零，有江梅、独许雪霜盟约。粉艳天真，苒苒香浮绣幕。", "满樽芳酒共谁酌。望天际、轻阴旋作。家园无恙，忘了归来，细看红萼。", "相思未是断却。柰江关赋愁，不堪落寞。花下前欢，此景羞人问著。", "拟凭鳞羽诉离索。怕纸尽、越添意恶。十分清瘦，南枝渐坼，莫近高阁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"桃源忆故人（春愁）","p":"","d":"宋代","a":"郑域","c":["东风料峭寒吹面。低下绣帘休卷。憔悴怕他春见。一任莺花怨。", "新愁不受诗排遣。尘满玉毫金砚。若问此愁深浅。天阔浮云远。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"曹纬","c":["日依平野没。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题林宗鲁校书所藏宣和御画","p":"","d":"宋代","a":"楼钥","c":["周公多艺孔多能，徽庙才高更倍增。", "除却万机都不会，至今遗老话昭陵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"明卿自楚驰信相问云秋后当访我金陵以一诗贺儿骐豋第以六诗苦旱答之","p":"","d":"明代","a":"王世贞","c":["楚波如黛泻潺湲，美有双鱼尾更殷。中散已申秋后驾，巨卿从破别时颜。", "乍悲云汉黎民咏，忽羡星辰父子班。解道起然无物念，人间忧乐也相关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和西湖竹枝词","p":"","d":"元代","a":"张简","c":["鸳鸯蝴蝶尽双飞，杨柳青青郎未归。第六桥边寒食雨，催郎白苧作春衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠吴煦","p":"","d":"明代","a":"顾璘","c":["绿树凉生十亩阴，柴门永日少相寻。纨衫不碍跏趺坐，石砚聊随散诞唫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登苏门山泛舟百泉 其一","p":"","d":"明代","a":"袁宏道","c":["食罢共成饭，来观泌水泉。废桥穿竹屿，小舫载茶烟。", "方外清溪寺，人间好畤田。那能营二项，风雨啸台眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冷泉亭","p":"","d":"元代","a":"周权","c":["昔人来自天竺国，缥缈孤云伴飞锡。天风吹落凝不去，化作奇峰耸空碧。", "至今裂峡馀云髓，桂冷松香流未已。翠光围住玉壶秋，不放晴雷度山趾。", "道人宴坐无生灭，炯炯层胸照冰雪。夜深出定汲清泠，寒猿啼断西岩月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"壬申见沪报载吴佩孚蛰居故乡，触景生情，感伤时局，咏诗八章，足徵英雄末路之胸怀。余步原韵藉以消遣 其三","p":"","d":"清代","a":"薛昂若","c":["无事隐居山水隈，渔樵耕读任徘徊。不知弹雨枪林下，怕看江边劫后灰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和陶彭泽归田园居 其三","p":"","d":"明代","a":"童轩","c":["偶影自成酌，知音相与稀。山深日将夕，坐看孤云归。", "疏柳荫前除，凉风吹我衣。衣单亦何恤，所恨愿多违。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春寒","p":"","d":"宋代","a":"朱槔","c":["人道春寒早系舟，楚山一夜雨浏浏。", "此生削迹江边路，嫩绿纷红只自愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"平谷杂诗十八首 其十八","p":"","d":"清代","a":"曾习经","c":["楚泽哀时命，田园归去来。室庐无定处，风雨犹深怀。", "短策支颐久，单衣至骭裁。比邻逢李叟，还讯菊花开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"仙兴","p":"","d":"宋代","a":"吴惟信","c":["宫殿高高在五云，鹤摇松露滴行人。洞门不放东风过，留得桃花一院春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观澜亭","p":"","d":"宋代","a":"许将","c":["危亭高处倚岩隈，西望蒲菖海浪回。", "山戴鳌头天外出，水浮鳅穴地中来。", "千重侧崦扶摇没，万里分流混沌开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"北上留别泾皋同志","p":"","d":"清代","a":"夏孙桐","c":["断送秋光又一年，芙蓉寂寞冷江烟。登山临水将归客，破浪乘风未了缘。", "对酒歌成宜楚调，载书装重笑吴船。牢愁别绪何须诉，日日孤云落照边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"皇帝阁","p":"端午帖子","d":"宋代","a":"周必大","c":["令月初登黍，嘉辰旧沐兰。", "宸心思解愠，时取舜琴弹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄太守元授挽词二首 其二","p":"","d":"宋代","a":"杨万里","c":["我忝通家子，公如父行亲。一书虽不欠，半面遂无因。", "旅榇千江远，铭旌两竹新。庆门宁有此，造物岂其仁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"念昔游四首 其二","p":"","d":"宋代","a":"胡仲弓","c":["昔游金山寺，一苇破沧溟。怒涛正拍天，风雨歘晦冥。", "江豚急吹浪，水面轰雷霆。满船失颜色，莫辨死与生。", "此时娄师德，高卧看长鲸。过午忽开霁，济岸犹登瀛。", "清风泛我衣，阳光射檐楹。舟人相慰劳，山僧笑出迎。", "行行金鳌背，月鉴浮空明。波平濛天影，潮静闻经声。", "殿阁耀金碧，守护真龙形。系缆少沉吟，红轮江西倾。", "炬火烁江面，直使潜鳞惊。因成一宿觉，问津维扬城。", "重来知几时，未计岁月成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"到南昌呈宋愿父伯仲黄子鲁诸丈","p":"","d":"宋代","a":"戴复古","c":["一秋无便寄平安，新雁声声报早寒。", "昨夜检衣开故箧，去年家信把来看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吾家","p":"","d":"宋代","a":"姜特立","c":["吾家何处住，一嶂独成围。", "莫遣通樵斧，应嫌减翠微。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"采桑曲","p":"","d":"宋代","a":"曹勋","c":["鸣鸠初拂羽，桑叶破新萌。", "采采不盈菊，攀多力未生。", "春服浥朝露，晓日映妆明。", "语学流莺巧，身同飞燕轻。", "使君劳借问，夫婿自专城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居 其二","p":"","d":"明代","a":"王邦畿","c":["高居若天外，茅屋不劳扃。避石松形古，当泉竹脚青。", "虫声秋入户，山色晚宜亭。更自闻寒籁，林僧夜教经。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢马程先","p":"","d":"宋代","a":"林逋","c":["数幅丹霞夹白云，封题何事寄幽人。亏君视草禁中客，乞我浣花溪上春。", "且与巾箱为玩好，更无篇什写清新。我来卧病还多感，一笔蛛丝满砚尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"客有为予言笋不可食食之令人瘦者戏作二绝为解嘲 其一","p":"","d":"宋代","a":"周紫芝","c":["庾郎三韭坐清贫，眼看将军肉十斤。会遣胸中有千亩，不妨人似沈休文。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"华容十咏为毛同府赋 其五 南山远翠","p":"","d":"明代","a":"史鉴","c":["湖水流无际，山形荡欲漂。云生齐北斗，脉衍自南条。", "朱凤高飞尽，苍梧别望遥。禹功垂万古，祠宇亦萧萧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿新升圩港","p":"","d":"清代","a":"陈熙治","c":["欲宿投何处，驱车任所之。野花村女鬓，红杏酒家旗。", "犬吠寒云外，人归暮雨时。凄凉谁共诉，倚枕泪如丝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戚氏（此词始终指意，言周穆王宾于西王母事）","p":"","d":"宋代","a":"苏轼","c":["玉龟山。东皇灵媲统群山。绛阙岧峣，翠房深迥，倚霏烟。幽闲。志萧然。金城千里锁婵娟。当时穆满巡狩，翠华曾到海西边。风露明霁，鲸波极目，势浮舆盖方圆。正迢迢丽日，玄圃清寂，琼草芊绵。争解绣勒香鞯。鸾辂驻跸，八马戏芝田。瑶池近、画楼隐隐，翠鸟翩翩。肆华筵。间作脆管鸣弦。宛若帝所钧天。稚颜皓齿，绿发方瞳，圆极恬淡高妍。", "尽倒琼壶酒，献金鼎药，固大椿年。缥缈飞琼妙舞，命双成、奏曲醉留连。云璈韵响泻寒泉。浩歌畅饮，斜月低河汉。渐渐绮霞、天际红深浅。动归思、回首尘寰。烂漫游、玉辇东还。杏花风、数里响鸣鞭。望长安路，依稀柳色，翠点春妍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过束河同和书香、木秀元龙潭小酌即事","p":"","d":"清代","a":"牛焘","c":["携酒壕梁上，班荆野趣饶。鸟枝花自落，蛇蔓叶初□。", "□□□□水，灵山秋药苗。年来深契阔，于此共逍遥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"摸鱼儿 寿留仙","p":"","d":"清代","a":"严绳孙","c":["似仙源、桃花零乱，武陵一棹重驻。玉堂铃索花砖日，旧是先生游处。", "愁如絮。消受尽、五湖烟月三湘雨。君恩再许。教领袖词流，双椽烛底，洒翰继迁固。", "喜不改，张绪当年风度。柳弧依旧悬户。交疏月转传筹饮，坠遍玉河红露。", "支机浦。早看取、七香车上山眉妩。离情休诉。只此恨重偿，双纹簟展，肯放早朝去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送朱大使朝京回迎父往福建任所","p":"","d":"明代","a":"程通","c":["三载官南闽，寸心恋北阙。玉佩朝龙颜，斑衣迎鹤发。", "山青云自閒，梅黄雨初歇。别后天一方，相思共明月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归云洞","p":"奉和滁州九咏九首","d":"宋代","a":"曾巩","c":["野草山花夹乱流，桥边旌旆影悠悠。", "即应要地无人见，可忍开时不出游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书事","p":"","d":"宋代","a":"陆游","c":["北征谈笑取关河，盟府何人策战多？扫尽烟麈归铁马，剪空荆棘出铜驼。", "史臣历纪平戎策，壮士遥传入塞歌。", "自笑书生无寸效，十年枉是枕琱戈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小画 其二","p":"","d":"元代","a":"丁鹤年","c":["翠黛浮晴汉，虬枝立暝烟。回舟不用楫，江上水吞天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二月十一日晓发龙山风顺","p":"","d":"宋代","a":"方回","c":["繁华销歇市朝空，此地何堪着固穷。", "久似坎蛙居井底，忽如野鹤出笼中。", "宿酲夜解催花雨，归棹春乘上水风。", "及得清明到家否，新芽茶绿牡丹红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽陈县尉歌词","p":"","d":"宋代","a":"戴栩","c":["欲裁薤曲问耆贤，见说声华四十年。", "六馆已推天下士，一官向羡吏中仙。", "白砂旧事渔樵老，缥轴新铭蜡墨鲜。", "便觅当今徐穉笔，榜知如玉在松阡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"落花流水篇","p":"","d":"清代","a":"弘历","c":["荏苒韶华过百六，羲轮电迅谁能逐。试探幻影绕花堤，还缀芳痕在溪澳。", "溪流宛转曲复斜，刺舟追赏幽兴遐。谁家亭榭无流水，何处风光不落花。", "落花流水春无赖，锦脂千片环一带。武陵见说引渔人，天台几度刘郎会。", "刘郎去后无消息，渔人再寻寻不得。残英依旧恋回波，辞枝恰借封姨力。", "封姨非是妒艳春，桑田海水迁移频。乍令琼姿沦碧沼，不教玉质埋黄尘。", "蜂衙蝶阵喧嘈甚，清流暂托参无眹。红紫都来做一团，李桃何必分两品。", "西子湖边纱独浣，天孙机上云方满。亦有佳人欲黯魂，漫誇词客纷撩眼。", "愁人万点曲江头，乘波绿珠初坠楼。尽道女夷嫁河若，不须解佩通蹇脩。", "铅华洗尽芳芬调，忘言默契无形妙。恍忆耆阇窟会时，如来拈起迦叶笑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吴中柳枝（四首）","p":"","d":"元代","a":"陈秀民","c":["长洲宫苑草离离，中有吴王旧沼池。", "至今二八吴中女，为人歌舞学西施。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"明月亭下作","p":"","d":"宋代","a":"孔武仲","c":["杳杳芜城起暮钟，亭亭华月照秋容。", "便疑碧海依墙堑，云水情知隔万重。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新月","p":"","d":"清代","a":"弘历","c":["魄彩吐寒空，中秋月未中。塞光偏觉异，恒质迥难同。", "结念香闻桂，游睎影飏枫。玉台高倚镜，奁帕半犹蒙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题真娘墓","p":"","d":"宋代","a":"徐照","c":["骨成泉下土，何物是游魂。", "一代颜容尽，千年名姓存。", "善缘依佛地，巧咏任人言。", "几听钱塘曲，风松静似喧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"无题","p":"","d":"明代","a":"吴鼎芳","c":["绮疏微透晓光寒，欲贴鸦黄展镜鸾。", "错怪桃花似侬面，一番风雨便春残。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送木宗院","p":"","d":"宋代","a":"徐照","c":["此职司天派，员分南与西。", "事稀从吏懒，诗好笑人低。", "丹荔开屏画，青榕盖鹤栖。", "必思随侍日，曾有旧留题。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"李庆孙","c":["四夷妙赋无人诵，三酌酸文举世传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和史樵云春兴三首 其三","p":"","d":"明代","a":"乌斯道","c":["山深路僻少人过，早晚惟凭七字哦。归思不随流水急，閒情浑似白云多。", "花开踯躅红千树，笋长筼筜绿数窠。想得此时如杜甫，池亭对酒爱新鹅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双髻岭","p":"","d":"明代","a":"胡文路","c":["谁把芙蓉海上栽，一枝两枝何日开。青苍今古不摇落，岩岈天地空崔嵬。", "圭璋削玉齐云立，银管冲霄碇斗极。根盘五指南溟深，花放四时娇欲滴。", "团团日月磨巑岏，飘飘风雨净婵媛。欲从蓬岛看正萼，直须鳌极探真源。", "汉武好奇闻自昔，开疆辟土寻端的。安期海上竟贪看，遂使君王长叹息。", "我家住在此花东，日日看花得正宗。最爱晴奇雨亦好，偏于夜月更情浓。", "逆从浩劫数分至，几见伸葩泄灵异。有时放出五色云，有时腾起丹霞气。", "我昨乘风九华游，烟云袅娜似瀛洲。匡庐五老藏彭蠡，何如渤海浮天球。", "乡人不识花模样，双髻马鞍名孟浪。从今援笔写花神，看花祇在青霄上。", "青霄头角何昂藏，笑向川原眉眼张。气吞鲸海凌风举，三年一度献君王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送周天叙出使于闽顺道省亲","p":"","d":"明代","a":"江源","c":["我爱君家鬓未华，可人文采际亨嘉。八千里外新持节，三百人中旧探花。", "征旆远飞闽海月，綵衣仍过越南家。平生却叹乘槎客，肯把蒲萄载使车。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答唐济武太史用来韵","p":"","d":"清代","a":"袁藩","c":["夜凉静听秋声起，篱外草虫鸣不止。挑镫坐对松影寒，明月乍出疏林里。", "少年华发惊时节，便欲学仙归贝阙。十载劳心思探珠，半生失计空磨铁。", "神仙何必厌妻子，秦楼弄玉随箫史。织女黄姑会有时，别床异被徒为尔。", "先生闻道何其早，红尘莫惜知音少。须从火底现莲花，肯向秋原同腐草。", "与君试访殷七七，至道不烦惟守一。天台有路度石桥，水流定泛桃花出。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感怀 其三","p":"","d":"元代","a":"王冕","c":["写字不适俗，读书难疗饥。", "蘧蘧尘网中，遑遑欲可之？仁风霜原隰，草树发幽姿。", "群动正翕集，游云未来归。", "怀哉鹤上人，徘徊感良时。", "无以慰蹇劣，樽酒聊自怡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄子将诗及拟骚见贻酬赠二首 其二","p":"","d":"明代","a":"王世贞","c":["天末空长剑，人间自曲钩。啖名殊代事，吞恨大江流。", "妙手斲轮得，雄心伏枥收。君看扬马后，馀子尽悠悠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"失题","p":"","d":"唐代","a":"杨巨源","c":["何事慰朝夕，不逾诗酒情。山河空道路，蕃汉共刀兵。", "礼乐新朝市，园林旧弟兄。向风一点泪，塞晚暮江平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"牡丹四首 其二","p":"","d":"唐代","a":"薛能","c":["万朵照初筵，狂游忆少年。晓光如曲水，颜色似西川。", "白向庚辛受，朱从造化研。众开成伴侣，相笑极神仙。", "见焰宁劳火，闻香不带烟。自高轻月桂，非偶贱池莲。", "影接彫盘动，丛遭恶草偏。招欢忧事阻，就卧觉情牵。", "四面宜绨锦，当头称管弦。泊来莺定忆，粉扰蝶何颠。", "苏息承朝露，滋荣仰霁天。压栏多尽好，敌国贵宜然。", "未落须迷醉，因兹任病缠。人谁知极物，空负感麟篇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用韵答何大镛朱学渊","p":"","d":"明代","a":"邓雅","c":["才俊纷纷总入朝，此生祗合老渔樵。春秋未解穷三传，大学徒能究八条。", "物外无心超世网，閒中有味酌山瓢。故人亦肯怜幽独，寻访频能过石桥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苦热行 其二","p":"","d":"明代","a":"黎民表","c":["云里楼台白玉京，龙绡飘动引飞琼。凉风更奏哀蝉曲，十里荷花碧浪生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"云亭萧氏园池杂兴次韵四首 其三","p":"","d":"明代","a":"刘崧","c":["小小窗轩溪水头，石门古路转斜丘。野林丹碧风初起，山橘青黄露未收。", "鸟下平原飞雨夕，猿啼孤嶂断云秋。读书台近招提境，思见当年隐者流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题鸂𪅍竹雀萱堂图","p":"","d":"明代","a":"陶安","c":["珍禽文采明金沙，相顾似怜毛羽嘉。托邻喜傍君子竹，忘忧更有宜男花。", "良工笔意何处好，林雀哺雏心使饱。北堂留得此图看，依旧春晖照幽草。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乙未元夕坐上用东坡上元韵二首 其一","p":"","d":"宋代","a":"胡铨","c":["胜游宝箓记吾曾，五十年来一衲僧。昼短莫吟千岁烛，年丰聊看九华灯。", "一毬未放寒星坠，万炬浑惊烈日升。诗酒虽堪驱使在，照愁佳句愧坡能。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初春邀诸固寅集小桃源","p":"","d":"明代","a":"陈迪祥","c":["帝城佳丽自畴昔，余生似带烟萝薜。不羡搴芳逐冶游，偏喜寻幽来野僻。", "白门桥西一径斜，中衍山林与阡陌。引著胜地兴不禁，等閒试理游春屐。", "侧身恍入武陵源，百道香光迷所适。玉树堂前兰蕊新，慈航堤畔柳芽碧。", "千树梅花绕径开，红白相错如绣襞。立望幽芬欲断魂，坐对落英屡沾帻。", "脩竹摇青似翠帏，方沼凝寒浸幽石。遥遥塔影出空林，隐隐梵音动深夕。", "我来静对已忘言，况复开樽引群益。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送尹给谏君润册封秦世子","p":"","d":"明代","a":"欧大任","c":["关城百二汉咸阳，捧册亲藩重夕郎。桐叶剪圭河水白，莲花开阁岳云苍。", "铜驼一别茏葱色，金马重来剑舄行。归日正逢停辇待，可无封事奏明光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题黄初平叱石图","p":"","d":"明代","a":"胡应麟","c":["古木苍藤挂风雨，白石峨峨洞门倚。黄家儿曹不解事，叱作群羊遍空起。", "胡生较汝差长年，俯窥五岳石五拳。他时一叱五羊起，白云飞尽罗浮巅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和张少卿丈再到洛阳","p":"","d":"宋代","a":"邵雍","c":["当年曾任青春客，今日重来白雪翁。", "今日当年已一世，几多兴替在其中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"正月初十日恭奉皇太后幸圆明园","p":"","d":"清代","a":"弘历","c":["银海光摇界道斜，乘时茂对乐昭华。物标太皞青旗旆，气转苍寅玉斗车。", "一道垂虹朝贝阙，万年春酒进仙家。输他羯鼓传佳话，俄顷瑶林尽发花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"分寄方广避乱诸缁侣八首","p":"","d":"明代","a":"王夫之","c":["麋晨鹘夜昼鸺鹠，足覆寒蓑听未休。此自答恩还圣代，山僧莫只话惊鸥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冰壑平生","p":"沁园春","d":"宋代","a":"佚名","c":["冰壑平生，如伯伦狂，似希乐豪。喜观书不用、菊茶明眼，登山不倩、藜杖扶腰。豆粥萍齑，脍羹鳞脯，湖海人常折简招。谁云老，有满怀风月，藏在诗瓢。凌晨向鹄冲霄。道昴宿于今又应萧。记垂弧令节，恰当後日，下元好景，正属前朝。冷胆如天，刚肠如剑，须把千杯寿酒浇。那堪更，是梅花时月，烂熳溪桥。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"商子引语","p":"","d":"先秦","a":"佚名","c":["愚者暗于成事。智者见于未萌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜宿永古寺与孤峰上人谈诗","p":"","d":"明代","a":"刘崧","c":["莲花池上月如霜，金地无尘夕景凉。海藏暗浮龙影动，露盘微注鹤声长。", "云栖梵钵留僧共，风隐铢衣护佛香。一夜不眠听说法，雨花撩乱满禅床。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"直指叶公枉顾赋谢四章 其二","p":"","d":"明代","a":"胡应麟","c":["灿烂西台白玉珂，频年直指向关河。丰城剑抱双龙出，瀫水桥乘驷马过。", "作赋风云回缥缈，飞章山岳动嵯峨。宁知一代苍生寄，几向清溪问绿蓑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水调歌头（和赵景明知县韵）","p":"","d":"宋代","a":"辛弃疾","c":["官事未易了，且向酒边来。君如无我，问君怀抱向谁开。但放平生丘壑，莫管旁人嘲骂，深蛰要惊雷。白发还自笑，何地置衰颓。", "五车书，千石饮，百遍才。新词未到，琼瑰先梦满吾怀。已过西风重九，且要黄花入手，诗兴未关梅。君要花满县，桃李趁时栽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观宗室伯山司户诗卷","p":"","d":"宋代","a":"释道潜","c":["参军暂辍簿书忙，为我聊开古锦囊。玉骨已能含秀气，珠玑那解不辉光。", "王孙挟策真难事，妙质如君岂易量。它日雠书天禄阁，声名端可继刘郎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"《绮疏遗恨》之绣床","p":"","d":"明代","a":"唐寅","c":["月沈花谢事堪伤，春树红颜梦短长；", "只有绣床针线在，残绒留得口脂香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八声甘州 其四 眠","p":"","d":"清代","a":"易顺鼎","c":["忆眠时凤帐掩娇颦，脸印枕痕新。任金钗压扁，罗衫摺蹙，休唤真真。", "只恐和人和梦，都化作梨云。梦里何滋味？犹咽香津。", "那日迥廊中酒，有猩红万点，铺作重茵。被檀奴欺负，偷解茜纱裙。", "甚东风相扶不起，被春愁困了柳腰身。凭仗着三生恩眷，消受横陈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"万法寺喜书","p":"","d":"元代","a":"谢应芳","c":["客来喜得平安信，萧洒楼居日掩扃。", "潮近浪摇窗影白，地偏苔没履痕青。", "群贤方结莲花社，小楷尤抄贝叶经。", "岁晚归舟经甫里，好寻渔父过寒汀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朝阳穿破衲赞","p":"","d":"宋代","a":"释慧开","c":["冷时急用之物，趁暖著些针线。", "忽然腊月到来，免致脚忙手乱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"花时遍游诸家园","p":"","d":"宋代","a":"陆游","c":["枝上猩猩血未曦，尊前红袖醉成围。", "应须直到三更看，画烛如椽为发辉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"孙季章无愧郑季奕徐斯远以仆留智门载酒见过坐中雪作三诗 其一","p":"","d":"宋代","a":"赵蕃","c":["出山已与晓寒冲，下马频欣束缊逢。已见南山行更钝，到时山寺已昏钟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵陈侍郎李察院潇湘八景图 江天暮雪","p":"","d":"宋代","a":"喻良能","c":["群山总入玉壶中，只有沧波映远空。独钓寒江晚来雪，凭谁画我作渔翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东城马上","p":"","d":"宋代","a":"贺铸","c":["綵虹桥下水关东，接畛园林狭径通。繁杏半开随半落，短墙无计碍春风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寒食","p":"","d":"宋代","a":"释居简","c":["才见茅檐插柳条，便知寒食是今朝。春应不恨相寻晚，应恨常阴一半消。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"胡宗肃世德堂","p":"","d":"明代","a":"倪谦","c":["肇迹由妫汭，传家自越州。万支原共本，一派转分流。", "瑗族今承宋，陈封远绍周。邓林多杞梓，卞椟剩琳璆。", "兰茁阶庭秀，麟从薮泽游。宦门足诗礼，儒业守弓裘。", "省解名方显，师资望更优。阿翁荣荐秀，夫子乐林丘。", "方伯难兄贵，科名令器收。青云联济美，懿德允垂休。", "循理全中得，为仁岂外求。学皆敦古训，行总肖前修。", "厚泽何能斩，芳声孰与侔。绵绵若瓜瓞，翼翼著谋猷。", "乔木光闾里，恩波下冕旒。子孙钦厥世，复始见公侯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其二","p":"","d":"元代","a":"吴当","c":["祠庙出东城，风云拱百灵。神光通御阙，天影抱彤庭。", "隙地多幽事，芳辰聚德星。道人偏爱客，更许制茅亭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"依韵和正老自叹之什二首 其二","p":"","d":"宋代","a":"强至","c":["我无尺地可耕锄，君有高田占具区。若论生涯犹厚薄，独于宦意等分铢。", "壮年未建鸿毛利，寸禄聊甘稚齿孥。不学庸庸自持者，高冠空食上农夫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将雪有怀","p":"","d":"明代","a":"何景明","c":["长安十万户，骑马欲何之。已动寻梅兴，空成采葛诗。", "雪心知霰集，云意怯风吹。今夜西堂烛，萧然有所思。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀古","p":"","d":"元代","a":"王冕","c":["会稽岩壑今犹古，王谢经行何所之？感慨传人有余思，风流异代不同时。", "春来野水生蒲柳，雨过空山长蒺藜。", "异代无人知禹穴，游人来往到今疑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽郑淑人","p":"","d":"宋代","a":"刘克庄","c":["忆生军中为记室，谢公门馆事皆知。", "谦卑若妇初嫔日，检素犹夫未贵时。", "病了死生惟点首，晚忧家国每颦眉。", "旧人独有任安在，揽涕西风献些词。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李氏爱山楼","p":"","d":"宋代","a":"薛嵎","c":["境自吾心会，於焉识所存。", "鸟声喧后寂，树色郭中付。", "静寿备仁理，乾坤悟易门。", "白云同此意，相对亦无言。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"招隐操 反招隐","p":"","d":"宋代","a":"朱熹","c":["南山之中桂树秋，风云冥濛。下有寒栖老翁，木食涧饮迷春冬。", "此间此乐，优游渺何穷。我爱阳林，春葩昼红。我爱阴崖，寒泉夜淙。", "竹柏含烟悄青葱。徐行发清商，安坐抚枯桐。不问箪瓢屡空，但抱明月甘长终。", "人间虽乐，此心与谁同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登九江长江决口处新堤","p":"","d":"当代","a":"傅义","c":["谁使狂蛟舞爪牙，生灵巨万倏倾家。而今纵是金汤固，莫忘曾为豆腐渣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送孙山长谒皮参政","p":"","d":"宋代","a":"许月卿","c":["授銊天教锦故乡，公心泉石不旂常。", "沙堤正自恐不免，野渡安能久退藏。", "羡子白刘从绿野，顾予鸡犬愧旌阳。", "衮衣会趁春风入，野服犹堪谒道傍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别驾刘景华甫下车即署海阳篆不三月以入觐行漫赋五绝为赠 其五","p":"","d":"明代","a":"林熙春","c":["二月垂杨满地花，东人翘首望回槎。赐金一橐归来解，料得儿童拥道誇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"减租诗","p":"","d":"明代","a":"朱瞻基","c":["官租颇繁重，在昔盖有因。", "而此服田者，本皆贫下民。", "耕作既劳勤，输纳亦苦辛。", "遂令衣食微，曷以赡其身。", "殷念恻予怀，故迹安得循。", "下诏减十三，行之四方均。", "先王亲万姓，有若父子亲。", "兹惟重邦本，岂曰矜斯人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉麈尾","p":"","d":"宋代","a":"谢翱","c":["客持麈尾柄，色夺环与玦。尘心随影袪，一片若行雪。", "神兽潜空山，何年探灵穴。忽失落人手，遂为谈者悦。", "阴崖起白气，篆古踰轩颉。一拂沉藓文，再拂字不灭。", "三拂蛟螭腾，世眼不能别。投尔阴崖颠，惊怪吐其舌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏鲁仲连诗","p":"","d":"南北朝","a":"阮卓","c":["鲁连有高趣，意气本相求。笑罢秦军却，书成燕将愁。", "聊弃南金赏，方从沧海游。寄言人世客，非君能见留。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄醇民先生","p":"","d":"清代","a":"钱廷文","c":["茂树有高枝，清弦无细响。素交见生平，曾不为标榜。", "自我与夫子，幽巷通来往。散发坐茅亭，信宿得心赏。", "清梵激松风，禅寺邻书幌。主客共藜羹，闵子过周党。", "尺素隔层城，烟月劳梦想。嗟我倦游人，十年在草莽。", "书剑局高天，壮躯空慨慷。何处豁尘心，溪流晒渔网。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感怀二首 其一","p":"","d":"元代","a":"刘基","c":["新晴杨柳散春丝，长路行人有所思。愁上容颜青镜识，寒生亭馆落花知。", "高云送雨来无定，独鸟惊风去自迟。闷对亭前紫荆树，同根那得却相离。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赵芷生提学投诗即行次韵答和","p":"","d":"清代","a":"李稷勋","c":["朝事惊心累叹欷，君胡掉首向岩扉。朝辞帝女过巫峡，夜唤湘累下秭归。", "归后江潭几秋树，山中日月尽春晖。彝陵郭畔匆匆语，目极神州涕满衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄旧同游","p":"","d":"宋代","a":"李复","c":["去乡甲子四十二，归路山川九百三。", "长河无鲤来东北，远梦随月转西南。", "檐花雨落春独酌，窗竹灯寒夜对谈。", "石上精魂能阅世，欲寻前事兴方酣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送仁山主兼寄西堂园澄禅师","p":"","d":"宋代","a":"陈师道","c":["未仕宁论马少游，虚名非复韩潮州。", "祖师若问西来信，为说苍头与白头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上元","p":"解语花","d":"宋代","a":"周邦彦","c":["风消绛蜡，露浥红莲，灯市光相射。桂华流瓦。纤云散，耿耿素娥欲下。衣裳淡雅。看楚女纤腰一把。箫鼓喧，人影参差，满路飘香麝。", "因念都城放夜。望千门如昼，嬉笑游冶。钿车罗帕。相逢处，自有暗尘随马。年光是也。唯只见、旧情衰谢。清漏移，飞盖归来，从舞休歌罢。"],"tags":["宋词三百首", "元宵节", "抒情"],"z":"","y":"","s":"","k":"词"},
  {"t":"九月十一日疾小间夜赋二首 其一","p":"","d":"宋代","a":"陆游","c":["清夜房栊灯火微，此心病起更依依。空惊床下莎虫语，不见梁间巢燕归。", "苍砚有池残墨在，白头不栉乱书围。可怜未遽忘风月，犹梦华觞插羽飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题福清八景寿叶师相","p":"","d":"明代","a":"李云龙","c":["青鸾东归阿母老，三山飞入七闽道。瀛洲仙客骑云还，长啸山头拾瑶草。", "南极光芒接上台，帝师应谢赤松回。凭将池上黄金液，先上君王万寿杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"芙蓉五绝呈景仁 其二","p":"","d":"宋代","a":"韩维","c":["小沾清露细摇风，养得新花次第红。客至莫教樽酒燥，朝吟夕赏未知穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"石屏歌为商丘先生作","p":"","d":"清代","a":"吴士玉","c":["群峰奔云涌座隅，下有烟艇浮江湖。是何淋漓足元气，得非米家海岳图。", "细看乃是浑成一片石，天然妙迹非人摹。昔闻巧匠斫山骨，未闻山水粉绘生石肤。", "若云造物作狡狯，却愁混沌凿死将何如。万里烟云藏咫尺，壁开天地超寰区。", "渔舟个个齐荡桨，烟波云岫聊相娱。我思米颠工画兼嗜石，整冠再拜以丈呼。", "石之嶙峋足以壮笔势，画之奔峭与石争盘纡。石癖画巧两不灭，画留石上永永成形模。", "君不见欧公当年石月屏，子美放歌穷虚无。又不见孤松溟濛石屏上，子瞻长句搜根株。", "今公兹屏亦奇绝，愧无大手如两苏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冰雪神人","p":"点绛唇","d":"元代","a":"元好问","c":["冰雪神人，岁寒时节争初诞。照溪梅绽。秀岭孤松远。香雾氤氲，不放重帘卷。歌声缓。酒杯深劝。此会年年见。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"舟中杂咏二首 其一","p":"","d":"明代","a":"徐霖","c":["绿树坐黄鹂，青秧点白鹭。睡起倚船窗，知是江南路。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读曲歌八十九首 其七十","p":"","d":"隋代","a":"佚名","c":["执手与欢别，欲去情不忍。馀光照已藩，坐见离日尽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过涧歇 海棠","p":"","d":"清代","a":"曾廉","c":["天意。为海棠、尚肯两日留晴，不许风欺憔悴。倚苔砌。", "映得书窗更媚。是养花天气。约嘉客、比似红裙对酣醉。", "燕子疏帘隔断，怜香问谁替。风恣宜笑，思量贴云髻。", "何处红楼，三月春深，玉台妆罢，六幅云锦方垂地。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归来二周岁","p":"","d":"唐代","a":"白居易","c":["归来二周岁，二岁似须臾。池藕重生叶，林鸦再引雏。", "时丰实仓廪，春暖葺庖厨。更作三年计，三年身健无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送戴生","p":"","d":"明代","a":"陶安","c":["姑孰亭前绿藻肥，会稽山上白云飞。四郊兵气频闻警，一榻灯光只梦归。", "舟子争潮喧熟路，海鱼修馔奉重闱。姚江在望浑非远，肯踏梭船访钓矶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题记事册","p":"","d":"宋代","a":"范成大","c":["划破虚空一剑闲，六根同转上头关。", "如今宴坐庵中事，政在凡夫道法间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋萍","p":"","d":"清代","a":"汪中","c":["寒流如镜碧烟和，贴贴青萍出涧阿。影动疏星秋欲曙，风回落木水生波。", "潜鱼坠散冲无数，古岸潮平聚更多。自是浮生易漂泊，不因霜露怨蹉跎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"弹广陵散","p":"","d":"元代","a":"耶律楚材","c":["居士闲弹止息时，胸中郁结了无遗。乐天若得嵇生意，未肯独吟秋思诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"记象入室事 其二","p":"","d":"明代","a":"严嵩","c":["猛象咆哮君合避，只须屏息坐帷中。汉舟几覆心无怖，记取程家主一翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送刘长舆","p":"","d":"明代","a":"薛蕙","c":["刘子今年少，文章欻老成。青春动才调，总角已聪明。", "父党同交辈，前贤畏后生。翻然兼鲍照，不啻似阴铿。", "历代流传体，千秋著作名。词场予有托，他日尔横行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"凉风至","p":"","d":"明代","a":"陶益","c":["何处凉飙发，庭前落木知。初秋争淅沥，薄暮转凄其。", "感旧心千里，迎寒酒一卮。霜花摇未见，吹帽接疏篱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"安期岩","p":"","d":"明代","a":"苏学程","c":["花落猿啼削壁间，升真元迹渺难扳。白云封后无鸡犬，流水声中有佩环。", "草树不知蝉蜕去，烟霞长伴鹤胎间。飘飘玉舄知何处，且掇菖蒲学驻颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"凝碧晚望","p":"","d":"宋代","a":"李弥逊","c":["秋来何必送将归，落日高台意自悲。", "一壑未容追法漫，三钟犹得饱支离。", "黄花对客如相笑，白发寻人似有期。", "时序不堪翻覆手，每逢佳处亦开眉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"回风波吊孔明先生","p":"","d":"元代","a":"萨都剌","c":["大江东流日夜白，已矣英雄不堪说。朔风挟雨过江来，犹向矶头溅腥血。", "汉家神气四海摇，奸雄贼子相贪饕。二龙雌雄尚未决，将军战骨如山高。", "先生谋略满怀抱，坐视狂尘不为扫。若非蜀主三顾贤，终只如龙卧南亩。", "仰天一出摧奸锋，纶巾羽扇生清风。许君义气肝胆裂，兵枢尽在掌握中。", "赤壁楼船满江夏，伏剑登坛唯叱咤。忠心耿耿天必从，烈火回风山亦赭。", "可怜一炬功未成，将星已坠西南营。力吹汉水灰未醒，呜呼天命何不平。", "伫立矶头盼吴越，感慨令人生白发。先生虽死遗表存，大义晶晶明日月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上林殿院次公 其九","p":"","d":"宋代","a":"徐积","c":["林氏家藏万帙书，五船便可当五车。别顾客舟施坐榻，更谋官舫作行厨。", "写时教子烘青竹，读处呼童捉蠹鱼。悔不早知都借取，终身挟策灌园蔬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"萤","p":"","d":"宋代","a":"刘敞","c":["翩翩岂自知，历历眩群飞。故作穿疏牖，时来鉴薄帷。", "助明清夜永，除害一身微。秋草隋宫路，茫茫旧赏非。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏时事","p":"","d":"近代","a":"洪存恕","c":["到处横行闯将先，何图好古得灾偏。郑家带草无馀绿，邺架书芸尽化烟。", "谁为斯文忧扫地，居然大圣号齐天。腐儒章句知干禁，百卷丹黄自弃捐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西藏杂诗之将赴西藏宿成都","p":"","d":"当代","a":"王引","c":["舆图新入藏，驿路锦官城。山想岷峨外，湖连星宿平。", "有僧分显密，无肆卜阴晴。灯下观遗事，唐蕃本舅甥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送神","p":"","d":"宋代","a":"葛闳","c":["丹霞飘渺海三峰，归去琼台第几重。", "仙骥一声风驭远，月明清露滴金松。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"茶公惠陋室吟忆旧，遂次其韵","p":"","d":"近代","a":"俞律","c":["杯空生尘久，室漏水浸膝。往事虽梦寐，记之可盈箧。", "人各有其天，天意有祸福。漫漫二十年，百哀不一乐。", "生死如草菅，思之肝肠裂。风雨江南归，文苑逢场入。", "春风偶一吹，秋雨常淅沥。青灯对残稿，旧事不堪述。", "倚枕不成眠，痛泪倾堤决。文章或不朽，老矣力难接。", "七十今有二，余生计无出。达者随世缘，闭目即安息。", "佛云四大空，神乎游八极。天上何所有，寒星与月日。", "知君正曲肱，病卧方力学。太息陋室吟，好诗称古拙。", "何当绍兴酒，与君长醉乐。南北东西天，日从何方出。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清明登胶山四首 其三","p":"","d":"清代","a":"安道","c":["莓苔称坐翠沾衣，对景无因问是非。幽谷藏春樵径没，古碑封藓字痕稀。", "人来绝顶双峰抱，云落平芜一鸟飞。咫尺家山游兴熟，那堪佳节更相违。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"卜算子","p":"","d":"清代","a":"郭则沄","c":["眉萼月弯环，心絮云撩乱。误了前期又后期，筝柱参差雁。", "梅落子犹酸，莲拗丝难断。不是狂香入梦悭，夜夜秋心懒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"代送张仲明兵备宪副致政还楝庄二首 其二","p":"","d":"明代","a":"苏葵","c":["策马亨衢尽付天，冰清玉洁自家坚。邈从霄汉勾前业，刚与云霞结暮年。", "寄兴楝花看作始，盖身荷叶想依前。人间快意知谁在，七贵五侯徒管弦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元日立春三绝","p":"","d":"宋代","a":"秦观","c":["此度春非草草回，美人休著剪刀催。", "直须残腊十分尽，始共新年一并来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"招彦国仲登二子入社得欢字","p":"","d":"明代","a":"欧大任","c":["翩翩华盖啸双鸾，翠壁丹厓欲见难。社待陶公应肯入，坐无车胤不成欢。", "兰湖正拟同纫佩，蒲涧曾期共考槃。雪后东来一乘兴，扁舟无惜剡溪寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送别二首(1) 其二","p":"","d":"清代","a":"费墨娟","c":["日催槐影上帘旌，快整征衫趁晓晴。此去劝君休惜别，男儿所志在功名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 其五 倬盦得画扇，复叠韵书一词于金笺扇见诒。五叠前韵谢之","p":"","d":"清代","a":"姚华","c":["清韵连翩如集凤。笺称金华，似带琼楼冻。睡里呼婆春是梦。", "青芜又促东皇鞚。", "仙蝶何堪词意重。洒翰亲书，信使更番送。秉烛须游良夜共。", "晓钟渐裂群山缝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"缘识 其五","p":"","d":"宋代","a":"赵炅","c":["时流求法界，问取本真诠。了悟空皆寂，心明海月圆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"罗隐宅","p":"","d":"宋代","a":"许仲蔚","c":["吟魂散何处，旧居荒可嗟。江山间白日，图籍落谁家。", "野烧寒煨■，春风暖自花。诗名蟠不得，埋没任桑麻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庚戌下第就沈阳陈监掣洪绪聘出山海关用杜少陵秋兴八首韵 其八","p":"","d":"清代","a":"安吉","c":["奉天城廓自逶迤，荡荡平平远险陂。圣寿八旬调玉烛，欢呼万岁半金枝。", "怀人日下音书隔，去雁江南节序移。西望长安似乡国，茫茫海立复云垂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏双白鹭（一作崔少府池鹭）","p":"","d":"唐代","a":"雍陶","c":["双鹭应怜水满池，风飘不动顶丝垂。立当青草人先见，", "行榜白莲鱼未知。一足独拳寒雨里，数声相叫早秋时。", "林塘得尔须增价，况与诗家物色宜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"代书寄谈鍊师","p":"","d":"唐代","a":"徐铉","c":["朱山松桂翠边云，中有清虚小隐居。", "密养丹砂存正气，静披琼蕴育真文。", "埙篪金石心常在，圭组烟霞路自分。", "凭仗乡人传尺素，山前惊起白羊群。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"武邑署中偶作舫屋诗以落之","p":"","d":"清代","a":"王元常","c":["屋也舟耶结此庐，得闲小憩在公余。志存作楫安天下，心拟乘槎入太虚。", "对雪欲移王子棹，焚香静玩米家书。亭轩小筑聊成趣，浮宅何妨且暂居。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"钱仲耕殿撰侍郎挽诗二首 其一","p":"","d":"宋代","a":"杨万里","c":["易髓三爻表，恩波九里强。贯珠程氏传，炊玉范家庄。", "荷橐中年紫，芸签到老香。不应踰耳顺，便返白云乡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠张祜","p":"","d":"唐代","a":"杜牧","c":["诗韵一逢君，平生称所闻。粉毫唯画月，琼尺只裁云。", "黥阵人人慑，秋星历历分。数篇留别我，羞杀李将军。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陶侃惜谷","p":"","d":"宋代","a":"司马光","c":["陶侃尝出游，见人持一把未熟稻，侃问：“用此何为？”人云：“行道所见，聊取之耳。”侃大怒诘曰：“汝既不田，而戏贼人稻！”执而鞭之。是以百姓勤于农植，家给人足。"],"tags":["初中文言文", "寓理", "故事"],"z":"","y":"","s":"","k":"文"},
  {"t":"冬至阳生","p":"万年春","d":"元代","a":"马钰","c":["冬至阳生，迎春拨雪黄芽好。人惊早。香如芝草。玉碾胜磨捣。神水烹煎，自是除阴耗。金童报。绝品珍宝。啜罢游蓬岛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雁媒","p":"","d":"元代","a":"郝经","c":["云衢眇飞鸿，往来解随阳。序当夜有所，次进朝有行。", "瀚海天山西，卵育岁为常。八月秋风高，雍雍共南翔。", "水国足汀洲，江湖多稻粱。晻霭带残芦，老岸青草长。", "哀鸣洞庭月，乱点潇湘霜。太和开冰天，北去颃穹苍。", "信禽法天运，断不为炎凉。偶为篝灯误，缚足离江乡。", "饮啄养为媒，朋俦总相忘。嗷嗷解愁人，乃反无愁肠。", "弋人见冥鸿，矰缴潜施张。置媒使号呼，投网来抢攘。", "奄忽一举尽，羽毛皆摧戕。厌然束缚去，又向云间望。", "嗟嗟罔民徒，诡计不可防。被获反为用，竭力如鬼伥。", "有信复无智，终自为身殃。误己更误人，不悟真可伤！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"分韵送孙从之司业使湖南得千字","p":"","d":"宋代","a":"楼钥","c":["夫君静而敏，人十已则千。", "读破万卷书，操笔思涌泉。", "古事与今事，一一探本源。", "蚤蜚场屋声，作吏志益坚。", "朅来上清班，汉庭谁在先。", "雍容行秘书，史馆躬椠铅。", "片言寤明主，立使登谏垣。", "拳拳忧国心，倾倒十三篇。", "司成天下选，归志已浩然。", "赤日送妻子，襆被寻谿船。", "诸生慕阳城，欲挽不得专。", "竟持湖南节，征袂何翩翩。", "忆昨忝同登，于今三十年。", "朝行喜相会，终恨非官联。", "请益殊未餍，匆匆启离筵。", "始以长官来，今以绣衣还。", "书生素安分，岂问却与前。", "第惟公辈流，自应留日边。", "德星聚南楚，予环当茹连。", "事体有关系，临岐欲无言。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王荆公","p":"","d":"宋代","a":"罗大经","c":["错认苍姬六典书，中原从此变萧疏。", "幅巾投老钟山日，辛苦区区活数鱼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和沈进可检法秋夜饮客待月","p":"","d":"宋代","a":"王之道","c":["欲雨云容合，濒江水气浮。", "笑谈初入夜，灯火适逢秋。", "巧借三豪便，还成一醉谋。", "投琼酬木李，只使老夫羞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜过吴江忆华终之","p":"","d":"宋代","a":"吕寅伯","c":["更深既尽烛，清气满山川。沙上风鸥聚，烟中霜草鲜。", "故人别何处，新月照孤眠。欲寄相思意，征鸿未可传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"老菊次时所性韵","p":"","d":"宋代","a":"何基","c":["独步东篱餐落菊，一幅乌纱漉浮玉。悠然谢客欲醉眠，懒拾枯枝炮脱粟。", "靖节先生骨已寒，回生何必须神丹。紫阳一字冠青史，名节恃此安如山。", "义熙一去知几变，金钿翠葆犹年年。我生因循颠已华，甚矣今年脱左车。", "嘲红弄绿少时态，岁晚相对惟寒花。雨荒深院黄金尽，谁谓颜色埋尘沙。", "高风雅致随遇见，帘外玉立横枝斜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄李忠定公","p":"","d":"宋代","a":"郑昌龄","c":["雅望三朝第一流，端如砥柱屹清秋。", "爱君炯炯无他志，许国堂堂不自谋。", "梦绕苍龙新阙角，凉生黄鹤旧楼头。", "中兴真主须真相，未雪双鸾耻未休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜雨倏霁月色清朗起视天宇怅然有故人之想遂赋此奉呈娄君仲实为翌日游岩之约云","p":"","d":"明代","a":"邓雅","c":["向夕篝灯风雨声，中宵启户月华明。青天万里看无尽，旅馆三更睡不成。", "才薄岂堪明主用，交深长忆故人情。重岩细菊仙家酒，明日相期作伴行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"生张说","p":"","d":"清代","a":"洪亮吉","c":["才脱稿，已立碣，死姚崇算生张说。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"履道书斋植竹甚茂用韵寄之十首 其七","p":"","d":"宋代","a":"释德洪","c":["虽住城隍寺，而无迎送烦。清风如有素，时复到南轩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋日寄舅弟贞宇","p":"","d":"明代","a":"张子翼","c":["历历秋旻隐翠屏，高轩何处隔江城。山斋寂寞天涵影，谷口清泠涧有声。", "听雨悬灯蛩自语，看云倚槛句还成。不嫌地僻回车马，肝鬲拚为信宿倾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"濠梁杂咏六首 其三","p":"","d":"明代","a":"郭谏臣","c":["丰沛濠梁俱帝乡，尽凭三尺定封疆。本朝自用周官制，不似炎刘杂霸王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其七","p":"","d":"宋代","a":"宋祁","c":["再来戴公宅，客过孝王家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"强甫西上","p":"","d":"宋代","a":"刘克庄","c":["平进差贤似躁求，乃翁岂不为儿谋。", "今寒畯士难京秩，古子男邦亦小侯。", "翘馆讵宜频造请。孤山虽好勿淹留。", "谁言此老心如铁，临别无端作许愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宣城劝农","p":"","d":"宋代","a":"吴泳","c":["一分东作五分春，相汝耕夫更在勤。", "七月诗成种田法，庶人章作劝农文。", "祈蚕必使蚕如瓮，卜稼须观稼似云。", "老守别无新治行，只将丰岁答吾君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月十二日晚雨因取渊明诗微雨洗高林清飚矫","p":"","d":"宋代","a":"滕岑","c":["去岁所种竹，今岁望成林。", "竹萌犹未见，时节春已深。", "逮茲一雨润，犊角庶可寻。", "切勿轻剪馘，长养令萧森。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"端午贴子词 皇后阁五首 其五","p":"","d":"宋代","a":"周麟之","c":["剪就冰绡月影团，不须多羡女乘鸾。君王瑶札亲题处，一样蟾花点点丹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"见陈月观二首","p":"","d":"宋代","a":"王奕","c":["仲尼日月几曾昏，自古君师岂必存。", "水陆三千游圣域，风云万里望天阍。", "燕台接武何多隗，吴国孤骞未见云。", "观上又分明月影，漫漫长夜与谁论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢面","p":"","d":"宋代","a":"谢枋得","c":["丰年自古说来牟，四月麦熟胜秋收。天厨送食不待求，有面本饦吾何忧。", "安得化身为儿童，戏沙作面可报答。授记或为阿育王，请铸八万四千塔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"万太宜人七十寿诗","p":"","d":"明代","a":"尹台","c":["华发金钿映晚晖，自天纶诰下重闱。悬知赤绂牵新梦，不奈斑衣阻独归。", "七十宴开青雀至，八千路绕白云飞。题诗寄祝庭萱寿，瑞婺光芒动紫微。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风入松 次虞邵庵韵别友","p":"","d":"明代","a":"黄润玉","c":["先生和气似春酣，一见盍明簪。太平无讼霜台静，榕阴里、时与联骖。", "瓜代早装行李，兰熏重整朝衫。", "雨余山色净于蓝，秋燕更喃喃。凄凉风月阳关道，和离思、摹入诗缄。", "一曲骊歌人去，月明千里闽南。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"幽居杂咏七十四首，自洪武十一年平原还家作也 其五十一","p":"","d":"明代","a":"孙蕡","c":["欲铸钟期未买金，断丝寒縆案头琴。虚堂月底弹清曲，别鹤离鸾自赏音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"会真诗四首 其二","p":"","d":"明代","a":"谢晋","c":["漙漙玉露湿庭莎，不觉凉侵袜底罗。自是夜深心胆怯，却嫌行处月明多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乱山乔木","p":"","d":"近代","a":"范天烈","c":["饱瞰春秋岁八千，参天老树自年年。风来干掩疑催雨，月白林空欲化烟。", "野鹤闲云踪不定，寒鸦古木色无边。谁为唤醒南柯梦，万壑森森一杜鹃。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨中梦故山","p":"","d":"宋代","a":"葛起耕","c":["冥冥细雨湿江城，掩映书窗翳复明。", "倦客一中杯顿减，故乡千里初成。", "金华洞口羊惊起，石佛山头鹿伴行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"邦瑞乞访亲因用其韵","p":"","d":"元代","a":"耶律楚材","c":["干戈扰扰战交侵，一纸安书值万金。凡子生还愁未解，萱堂仙去恨尤深。", "涕零倚木西风怨，肠断闻铃夜雨淋。养老送终真有憾，号天如割望云心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"瑞鹧鸪 收家书","p":"","d":"元代","a":"马钰","c":["家书接得急开封。正值糊窗要避风。我愿难随你意去，道心不与俗心同。行功未满大千数，云水须游太一宫。传语儿孙并弟侄，后来书至＊墙"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饮许龙石学士园亭短述三首 其一","p":"","d":"明代","a":"孙承恩","c":["桂楫依沙渚，茅堂共酒卮。经年劳注想，此日慰深思。", "槛竹吟风细，流云渡苑迟。尘襟喜披豁，坐久欲忘辞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"芗林五十咏 其三十一 梨花原","p":"","d":"宋代","a":"杨万里","c":["禁火晓未暖，踏青昏恰归。何堪一原雪，将冷入春衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大将军宴会被命作诗","p":"","d":"魏晋","a":"陆云","c":["在昔奸臣。", "称乱紫微。", "神风潜骇。", "有赫兹威。", "灵旗树斾。", "如电斯挥。", "致天子届。", "于河之沂。", "有命冉集。", "皇舆凯归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"遇风出陆金陵道中次程及甫韵","p":"","d":"宋代","a":"洪咨夔","c":["留滞周南命使然，莫疑上水逆风船。乡山故故随人后，客月依依堕我前。", "半夜索樽同决计，五更回柂不成眠。笋舆吹面新凉入，须信封姨正自贤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戊辰春 其二","p":"","d":"明代","a":"倪元璐","c":["贵鹤贵其唳，厌蝉厌彼喧。喧经霜塞默，唳与天通言。", "贾传诚初学，留侯岂美媛。无将绛灌语，去与圮翁论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归去来集字十首，并引 其四","p":"","d":"宋代","a":"苏轼","c":["云岫不知远，巾车行复前。仆夫寻老木，童子引清泉。", "矫首独傲世，委心还乐天。农夫告春事，扶老向良田。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金陵三首","p":"","d":"宋代","a":"梅尧臣","c":["恃险不能久，六朝今已亡。", "山形象龙虎，宫地牧牛羊。", "江上鸥无数，城中草自长。", "临流邀月饮，莫挂一毫芒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄题沈逸人故居","p":"","d":"明代","a":"朱睦㮮","c":["修竹湘沅畔，会闻有避喧。叶香馀在户，翠影尚临轩。", "野日怅谁语，江云愁与繁。自君腾驾后，阒寂此丘樊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次绪山韵五首 其二","p":"","d":"明代","a":"杨爵","c":["双鹳飞来圜树梢，看他春到便衔巢。显庭常若俨宾际，幽世必须藉白茅。", "心果合天真浩浩，狂非作圣但嘐嘐。会教身世全无我，方寸才能免物交。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送苏召叟秀才入蜀效宛陵先生体","p":"","d":"宋代","a":"陆游","c":["士勇赴知己，义重身固轻。", "尊公况有命，子得辞此行？结庐出门去，迢迢过蛮荆，泝江卜风色，入峡听猿声。", "万里一纸书，南寄孤雁征，山阴在何处？计子难为情。", "愿言早来归，邻曲当出迎。", "檥舟柯桥市，一榼手自倾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨鬘","p":"","d":"清代","a":"易顺鼎","c":["玉{竹/氐}响动文窗锁。郎来故傍红鹦坐。贪看碧桃花。险些忘却他。", "梦嫌帘路窄。春影层层隔。侬自要销魂。嫩寒深闭门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"李侍御墓","p":"","d":"明代","a":"殷奎","c":["李公读论语，探道悟渊微。政推守令最，名重谏诤司。", "生平信跌荡，之死气不衰。表树限樵牧，善政固在兹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠林仰之迁南京国子监丞","p":"","d":"明代","a":"林光","c":["叉手东风月一更，我来君去最关情。天机转弼南都教，人事难逃月旦评。", "四海英豪频属望，八闽衣线念非轻。乡书首发他年解，谁道吾侪眼亦明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"海藏楼杂诗 其十二","p":"","d":"清代","a":"郑孝胥","c":["雨过云亦归，林气重不散。满月如帷灯，隐约出天半。", "须臾碧将合，粉彩发璀璨。银波渐流空，湿雾涨瀰漫。", "园林遂平沉，楼阁若隔岸。登台揽明镜，照胆不可玩。", "寒光来逼身，左右晃凌乱。凛然赴奔潮，露顶白虹贯。", "一凉遽至此，始有秋风叹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偕洪觉山登沙贝钓台次韵二首 其二","p":"","d":"明代","a":"庞嵩","c":["不见溪翁坐石年，钓台云暮眼空穿。持竿欲学任公子，志大无功漫费钱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郊庙歌辞。五郊乐章。肃和","p":"","d":"唐代","a":"佚名","c":["玄鸟司春，苍龙登岁。节物变柳，光风转蕙。", "瑶席降神，朱弦飨帝。诚备祝嘏，礼殚珪币。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"牧牛昼睡图","p":"","d":"明代","a":"胡奎","c":["草软坡平午树凉，人牛此际两相忘。曾知亦有无眠者，马上鸡声满路霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红九首 其七","p":"","d":"清代","a":"奕绘","c":["滚滚黄流，是禹迹、神功初奠。极远目、乱峰西北，潮头一线。", "燕赵河山多感慨，金元事业空交战。想平沙、毡帐竖黄旗，标行殿。", "七百载，风云变。古今事，波涛卷。剩长桥顽石，平拖如练。", "税局喧哗争过客，堤城嵲屼依村店。叹年时、骑马往来频，英雄倦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"慈云岭","p":"","d":"宋代","a":"董嗣杲","c":["叠叠流云步步苔，九霄紫气限蓬莱。", "后唐刻石初开路，南宋郊天别築台。", "慰眼江湖空岁月，伤心陵寝堕尘埃。", "桃花争趁春风老，又引游人一度来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重九偕衡甫少帆三游云巢","p":"","d":"清代","a":"许传霈","c":["满郭霜林唤野舲，芦花深处偶然停。无边木叶随时落，不断山光为我青。", "佳节何妨人淡菊，仙寰长许鸟听经。遨游三度忘知止，愿老前溪止止亭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题扇寄山西潘春谷子抑","p":"","d":"明代","a":"湛若水","c":["天南天北梦难通，春谷风同云谷风。舒卷乾坤一箑耳，莫教春信断来鸿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"竹溪直院盛称起予草堂诗之善暇日览之多有可恨","p":"","d":"宋代","a":"刘克庄","c":["静院闭花时，沉沉昼漏移。偶然声出户，应是客围棋。", "夜寂推枰响，机深落子迟。恼禅天女去，入定老僧知。", "鹄至难传艺，莺啼许借枝。须臾分局势，何待烂柯为。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"即事","p":"","d":"宋代","a":"晁补之","c":["半刺还为权刺史，朝衙不坐坐铃斋。", "按头通事通何事，昨夜东园芍药开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄答曰庐诸子","p":"","d":"明代","a":"释函可","c":["书来知汝未曾离，竹杖麻鞋好护持。我罪已深衰更甚，不须翘足看松枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"台阳八景","p":"","d":"清代","a":"谢家树","c":["上沃三春润，洋宽一望迷。风驯芳草浪，雨酿落花泥。", "司馌童携筥，忘机鸟集犁。西成先可庆，不辨地高低。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚凉散策二首 其二","p":"","d":"宋代","a":"杨万里","c":["半点轻风泛柳丝，忽吹荷叶一时欹。芙蕖好处无人会，最是将开半落时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东楼落成二绝","p":"","d":"宋代","a":"吴芾","c":["荒郡城楼久已倾，我来聊复为经营。", "南楼已是增雄观，今日东楼又落成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七夕集何龙友宅","p":"","d":"明代","a":"李孙宸","c":["天阶坐七夕，银汉望虚无。雅会烦襟涤，新凉暑病苏。", "月斜蟾影澹，星返鹊桥孤。此夕相怜意，人间总未殊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"放下庵即事三绝 其二","p":"","d":"宋代","a":"范成大","c":["病后天魔不战降，梦中千顷白鸥江。心空境寂声尘尽，却爱秋蝇扑纸窗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"知宗送玉友酒","p":"","d":"宋代","a":"王十朋","c":["铃斋昼寝梦初醒，忽见双罂眼欲惊。谁送瓮头新玉友，人言天上老宗英。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵仲明举西郊别墅","p":"","d":"宋代","a":"郭印","c":["我闻修竹阴，清邃不受暑。", "安得十亩馀，其中创幽墅。", "日长惟鸟声，昼静无人语。", "习习来微风，萧萧堕寒雨。", "呼儿出柴扉，垂纶坐沙渚。", "斯志久未遂，世路今弥阻。", "新诗何起予，风味胜清醑。", "自怜拘一官，隐逸愧前古。", "好梦只林泉，覉踪犹粪土。", "岂能学贪夫，忘身徇圭组。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"平谷秋兴六首 其一","p":"","d":"清代","a":"曾习经","c":["苌楚阿娜枝自摇，荒山无树著凌霄。惊风尽日吹骡铎，积雨连旬覆燕巢。", "此地旧馀边塞月，归心遥望海东潮。江南信美哀吾土，虚为羁旅赋大招。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋闺","p":"","d":"明代","a":"李孙宸","c":["金风披拂绣罗裳，吹我相思到异乡。不见铁衣辞雁塞，仍闻鼙鼓戍渔阳。", "合欢裛露开盈砌，促织惊寒鸣近床。最怪流黄机上月，秋来偏照瓦鸳鸯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"花朝二首 其二","p":"","d":"清代","a":"王季珠","c":["引我红愁却几株，放歌那说不关渠。花奴诗隶供闲遣，福分三生修到无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵阎甥伯温池上八首 其二","p":"","d":"宋代","a":"晁补之","c":["昔吾卜城东，今吾卜城中。祇畏盗贼迫，安知廛市同。", "畚锸运渤海，操蛇应未穷。无乃遭此笑，君如北山翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"定寨望洋","p":"","d":"清代","a":"陈玉衡","c":["三秋策杖卦山巅，一望重洋思渺然。作楫安澜如此日，乘风破浪是何年。", "氛消绝岛鱼游泳，气结全台象万千。门户而今开鹿港，依稀争看估人船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蓟州","p":"","d":"明代","a":"白范","c":["西来山尽处，始见蓟州城。", "地拱三门峻，天回一面平。", "人烟多戍卒，市语杂番声。", "回首松亭道，秋风几日程。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荡子从军","p":"","d":"明代","a":"欧必元","c":["飞扬出苏城，辛苦事幽并。拚尽英雄骨，输谁荡子名。", "但知谋国事，不复顾家声。藉甚图形阁，麒麟总未成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"伍长卿","p":"","d":"明代","a":"李孙宸","c":["长卿秉逸尚，妙龄事幽讨。灼彼春华姿，被服纨与缟。", "时援绿绮琴，一理清商操。中怀那可喻，含情欲谁告。", "申言属所欢，勖哉维此道。大音一以倡，颓风日以扫。", "人生易奄忽，长夜漫浩浩。千秋良在兹，胡宁但衰老。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"近代杂歌 浔阳乐","p":"","d":"南北朝","a":"鲍令晖","c":["稽亭故人去。", "九里新人还。", "送一便迎两。", "无有暂时闲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠董明府迎侍四首 其二","p":"","d":"明代","a":"卢楠","c":["昊天列光景，清辉缅赤县。少微垂高云，婺彩明河甸。", "𦕈眇寰宇间，习习祥风煽。兹匪巨孝蒸，孰能拨灵变。", "回头语中州，大养非珍馔。持此金石开，会膺紫泥眷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春晚五首","p":"","d":"宋代","a":"曹勋","c":["春过花飞不可寻，空余新叶翠光深。", "炉香袅袅轩窗静，时有珍禽啭好音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题谢氏双溪阁","p":"","d":"宋代","a":"郭祥正","c":["谢家山下双溪阁，水远山深夏亦凉。霜练两条初合影，菱花一鉴泻馀光。", "樽罍日日邀宾客，仓廪年年富稻粱。更约诸孙勤问学，桂科将见绿衣郎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"嘉州舟行至渝","p":"","d":"清代","a":"顾光旭","c":["纤月上青衣，迢迢春水肥。如何万里道，不借一帆归。", "夜静鱼龙卧，沙平雁惊飞。半江星斗外，疑是旧渔矶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"释简长","c":["烟垒沉寒笛，霜空击怒雕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜寓舟中","p":"","d":"宋代","a":"徐德辉","c":["秋气清如水，推篷夜不眠。", "芦花新有雁，莎叶尚鸣蝉。", "断梦疑堪续，哀吟最可怜。", "渔童看月上，吹笛舵楼前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"神泉海市居人谓重现日寇兵伍","p":"","d":"当代","a":"陈永正","c":["无尽时空驻此奇，云中广厦是耶非。不知沧海成田未，却幻金戈铁马驰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题静仪张夫人百花卷子","p":"清平乐","d":"近代","a":"马叙伦","c":["璇闺罢咏。又写群芳影。染翠渲红生意迥。的是描生上乘。", "奇葩强半难名。劳他搜遍潮汀。偏少合欢一朵，为憎夫婿多情。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"过牛伏岭","p":"","d":"明代","a":"舒頔","c":["牛伏岭高高且远，崎岖羊肠路百转。", "仲冬跋涉汗流浆，每叹时危历艰险。", "阴厓惨惨生悲风，极目四顾山巃嵸。", "人生能着几两屐，踪迹不异无根蓬。", "我家居山南，别业寄山北。", "群凶势纵横，往返苦行役。", "山中天气温如春，绝壁遥见梅花新。", "梅花年年见春色，不见多少行路人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂曲歌辞 其三 踏歌词","p":"","d":"唐代","a":"谢偃","c":["夜久星沈没，更深月影斜。裙轻才动佩，鬟薄不胜花。", "细风吹宝袂，轻露湿红纱。相看乐未已，兰灯照九华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宴李氏宅","p":"定风波","d":"清代","a":"曾廉","c":["卷石为山斗水池。俨然湖上绿沦漪。昨夜吹箫声满院。", "相见。生绡如雪照花枝。", "荷叶苞羞持劝客。殽核。半红频果酒盈卮。雅会乘今宜笑乐。", "惊咢。西风又是授衣时。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"新菊","p":"","d":"宋代","a":"陆游","c":["老去流年不耐催，微霜又见菊花开。", "莫言冷落西风晚，也有飞飞小蝶来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红 浣花草堂","p":"","d":"清代","a":"左锡嘉","c":["凭吊苍茫，衰草外、夕阳残堠。空留得、浣花诗老，草堂依旧。", "幕府十年栖息强，兵戈满地仓皇走。只乡愁、并入啼鹃，频骚首。", "花径外，春星瘦。茅屋底，秋风吼。叹词人漂泊，古今谁偶。", "忧国文章知己泪，倦游身世成都酒。甚而今、景仰说诗王，君知否。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"调笑令 白门雨夕有怀亚子","p":"","d":"近代","a":"林庚白","c":["无睡。无睡。又惹几多诗思。残钟一夜西楼。梦落吴淞晚秋。秋晚。", "秋晚。寒雨连江人远。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答何积中","p":"","d":"宋代","a":"李流谦","c":["先生古心寄玄漠，老松矫矫石凿凿。", "已欣净社得胜友，更枉高轩出奇作。", "山林轩冕无间然，造物从公意所便。", "决科纵未吞余子，著书亦足垂千年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻邻家琵琶有感","p":"","d":"明代","a":"高启","c":["清唱合琵琶，当年碧玉家。", "弄残催酒急，抱重向灯斜。", "久别愁江树，重听隔院花。", "泪多思旧事，不是客天涯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄宇文判官","p":"","d":"唐代","a":"岑参","c":["西行殊未已，东望何时还。", "终日风与雪，连天沙复山。", "二年领公事，两度过阳关。", "相忆不可见，别来头已斑。"],"tags":["抒情", "思乡", "愁苦"],"z":"⑴殊：很，极。\n⑵阳关：古关名，西汉置，在今甘肃省敦煌县西南古董滩附近。\n⑶斑：斑白。","y":"往西前行已经很远了，仍然没有穷尽之时，回首东望又不知何时才能返回家乡。\n成天面对的都是狂风和暴雪，放眼望去直达天际的是连绵重叠的沙漠和山丘。\n我从事公职已历两年，曾两度经过阳关。\n想念你却见不得你，分别之后，我的头发都已经斑白了。","s":"","k":"诗"},
  {"t":"高山寺","p":"","d":"明代","a":"憨山大师","c":["山城枕江流，梵刹云中起。", "钟鸣万户开，人在莲华里。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"漫书答唐观察四首 其二","p":"","d":"明代","a":"汤显祖","c":["县小河阳花遍开，金盘露冷醉人来。也知不厌山公启，解事长亏女秀才。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄葛秋岩","p":"","d":"宋代","a":"林景熙","c":["吴地繁华半劫灰，故山秋远梦频回。", "琵琶亭老春风棹，桑落洲寒夜雨杯。", "岁月悠悠人几换，关河渺渺雁空来。", "酒酣欲寄登临眼，黄叶斜阳满废台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浪淘沙 登阳明山有感","p":"","d":"近代","a":"陈逸云","c":["未觉雁鸣秋。已惹乡愁。斜风细雨过危楼。极目山川无限意，故国神游。", "壮志未曾休。事业何酬。笃行实践苦思筹。两鬓不辞添白发，誓复神州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"律转黄钟","p":"满江红","d":"宋代","a":"范飞","c":["律转黄钟，尧蓂尚、零星一叶。人尽道、当年此日，诞生豪杰。我是君家门下士，三年屡献阳春雪。更此行、骑鹤上扬州，恩稠叠。君有子，文章伯。君有女，夸才色。更风流酝藉，东床佳客。婿祝长生儿祝寿，玉杯举罢金杯接。愿年年、长醉腊前梅，梅梢月。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"金廷标秋英十二种 其九 金钱","p":"","d":"清代","a":"弘历","c":["买断三秋也足豪，不从四字不从刀。成诗已自闻卢肇，著论宁妨诮鲁褒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洪州矮张歌","p":"","d":"元代","a":"杨维桢","c":["洪州矮张如矮瓠，大帛深衣没双屦。", "自言矮瓠不食酒，惟贮先天九宫数。", "早年侠气慕朱郭，轻财屡倒千金囊。", "得道人疑李士宁，滑稽时效东方朔。", "双瞳注射金蟆精，口如急雨倾建瓴。", "卒然一语中人隐，王公错愕面发赤。", "乌乎王谢误苍生，天下乌用尔宁馨。", "居中可乏汲长孺，使边甲用苏子卿。", "我本先皇赐进士，十年不调钱塘市。", "宦程那敢问雄飞，国法新蒙脱胥靡。", "西湖西，南山南，水华落日清而酣。", "画船载酒遁名姓，三尺长喙金人缄。", "嗟乎五鬼贼，三尸谗，矮瓠矮瓠无多谭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书感","p":"","d":"宋代","a":"陆游","c":["老荷宽恩许退耕，丝毫无报亦何情。", "民贫乐岁尚艰食，道丧异端方肆行。", "党祸本从名辈出，弊端常向盛时生。", "古人骨冷青松下，谁起英魂与细评？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"李伯先","c":["一门萃忠孝，竹锦写家声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汴之水三章送淮南提刑李舍人","p":"","d":"宋代","a":"梅尧臣","c":["汴之水，入于泗，", "黄流清淮为一致。上牵下橹日夜来，", "千人同济兮万人利。利何谓，", "国之漕，商之货，", "实所寄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元日书怀","p":"","d":"宋代","a":"王炎","c":["年光除日又元日，心事今吾非故吾。", "两板不须书郁垒，一杯亦强饮屠萝。", "添丁解事寻王母，内子伤时念老姑。", "欲报情深恩罔极，不终反哺愧林乌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"四月三日初到临海县 其二","p":"","d":"清代","a":"李枝青","c":["前瞰灵江后枕屏，章安锁钥控东溟。楼台晴压蛮烟湿，城郭朝浮海气腥。", "潮上鱼虾罗市白，雨余笋蕨出林青。比邻吾土同风物，莫把华胥梦便醒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄子戴京邑","p":"","d":"清代","a":"俞庆曾","c":["当时曾踏软红尘，茅店荒鸡送客轮。锦瑟年华东逝水，银釭风雨苦吟身。", "天涯杨柳初匀碧，江畔蘼芜已换春。不说相思深几许，平安聊慰远游人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和寄问刘白　时梦得与乐天方舟西上。","p":"","d":"唐代","a":"白居易","c":["正与刘梦得，醉笑大开口。", "适值此诗来，欢喜君知否。", "遂令高卷幕，兼遣重添酒。", "起望会稽云，东南一回首。", "爱君金玉句，举世谁人有。", "功用随日新，资才本天授。", "吟哦不能散，自午将及酉。", "遂留梦得眠，匡床宿东牖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵答于谷山宗伯见怀四首 其四","p":"","d":"明代","a":"杨巍","c":["莫理城南汶水船，于今诸塞起狼烟。已知宵旰劳明主，不记仙曹侍从年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天二首 其二","p":"","d":"近代","a":"刘东父","c":["十载恩情怅别离，愁来怕写断肠诗。梦魂不到相思路，酒盏谁温絮语时。", "还劝我，与君期。来生鸳牒可相宜。春风吹遍蘼芜路，未抵愁心杀卷葹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送汪进士以虚宰金华","p":"","d":"明代","a":"欧大任","c":["汪子少年才莫匹，奉对丹墀期第一。试令俄从通籍年，理人初遇分符日。", "浙西大邑瀫江涯，八咏楼前几万家。城临三洞山山雪，春过双溪树树花。", "子也蕲黄士，国宝荆州记。嘉鱼吴献臣，巴陵邓宗器。", "名世千秋表钜公，起家百里为循吏。何羡庞元蒋琬乎，召归可待锋车使。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和黄咏雩榄溪杂诗即用原韵 其三","p":"","d":"近代","a":"李洸","c":["忍读遗诗日几回，商声哀飒纸窗来。空降白刃输肝胆，荒冢黄花特地开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"对菊","p":"","d":"唐代","a":"齐己","c":["蝶醉风狂半折时，冷烟清露压离披。欲倾琥珀杯浮尔，", "好把茱萸朵配伊。孔雀毛衣应者是，凤凰金翠更无之。", "何因栽向僧园里，门外重阳过不知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春晚书村落闲事","p":"","d":"宋代","a":"陆游","c":["千古会稽城，闾阎乐太平。", "丰年观米价，霁色听禽声。", "俗俭憎浮侈，民淳力钓耕。", "豳诗有七月，字字要躬行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莫端身","p":"苏幕遮","d":"元代","a":"王哲","c":["莫端身，休打坐。摆髓摇筋，嘘咽稠粘唾。外用修持无应和。赢得劳神，枉了空摧挫。要行行，如卧卧。只把心头，一点须猜破。返照回光亲看过。五色霞光，覆焘珠明颗。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"幽趣十二首 其二","p":"","d":"宋代","a":"郑刚中","c":["幽趣无人会，闲居趣自成。孤舟横水静，宿鹭入烟明。", "风絮低还起，苔钱断复生。小门无客款，睡犬不闻声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏八仙 栉发","p":"","d":"宋代","a":"韦骧","c":["搔首意不满，聊凭象栉功。高情唯自适，岂恤鬓如蓬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大朝门同午楼复建百官朝贺二首 其二","p":"","d":"明代","a":"胡直","c":["轩阁看仪凤，尧阶俯濯龙。宸聪从此达，猎疏拟谁封。", "燎火光云汉，珂声接曙钟。定应门下省，承问独从容。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同梁思伯讯陈贵吾卧病","p":"","d":"明代","a":"黎民表","c":["怪尔经旬卧，疏灯对影孤。药曾因病识，身岂为名拘。", "叹逝从星鬓，安贫任泽癯。莫愁过往绝，人自访潜夫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用韵答廖梅南二守 其一","p":"","d":"明代","a":"区越","c":["春棹破江清，春山叠送迎。暮滩遗宿鹭，寒柳带迁莺。", "蓬鬓已含雪，尘冠未解缨。时和思赈贷，朝夕寸心萦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送别戴肩吾","p":"","d":"明代","a":"曹于汴","c":["七月凉风来，雨罢蔬苗广。戴子访吾庐，陇畔谈今曩。", "不道生计微，但询学问长。手持李翁言，作圣示吾往。", "珠玉挥四壁，坐玩襟期爽。送子远行游，归视吾禾穰。", "子行怀自佳，天宇秋正敞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠天台老樊","p":"","d":"宋代","a":"白玉蟾","c":["别后俄经几许春，相逢一笑挹南薰。灰头土面无人识，木食草衣嫌俗纷。", "在浙之台今已久，姓樊名邴寂无闻。为君传此新诗去，寄与铅山赵翠云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"应尽须尽吟 其七","p":"","d":"明代","a":"顾允成","c":["应尽须尽，非尽亦尽。太极无极，何始何竟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚步","p":"","d":"宋代","a":"陆游","c":["晚步清溪上，微阴忽快晴。", "鸦栖先小泊，鱼暖已群行。", "药饵扶垂老，耕桑乐太平。", "非关恋乡社。", "久客倦遐征。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山行晚归","p":"","d":"宋代","a":"释善珍","c":["药径入云林，晚晴扶杖吟。照泥星复雨，经朔月犹阴。", "树折怜巢覆，泉清见叶沈。爱闲自如此，不是学灰心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"经历司暮春即事","p":"","d":"元代","a":"萨都剌","c":["霞飞海燕拂帘过，风卷鱼鳞剪绿波。閒倚石阑数春事，满池红雨落花多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大恒招集南屏分韵","p":"","d":"清代","a":"全祖望","c":["试看南山色，连朝倍老苍。青霜封曲磴，黄叶下空廊。", "旅客游方倦，寒虫蛰渐忙。昨闻开酒戒，来过远公房。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梦大人","p":"","d":"清代","a":"张鹏翮","c":["亲老时萦念，身安不厌贫。青云长作客，白发未归人。", "夜雨和愁落，家山入梦频。故园归未得，西望正伤神。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉题付珠二首 其一","p":"","d":"宋代","a":"刘克庄","c":["象罔得来还失了，寒斋拾去閟藏之。临行此物犹难忍，不付他人付二儿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗六首 其五","p":"","d":"元代","a":"徐贲","c":["飞鸿渡衡湘，游戏寒江浔。携群复挈侣，浩荡同浮沉。", "一鸿忽失意，矰缴乃见侵。众鸿不忍去，徘徊发哀音。", "悲风何所恶，积水而又深。欲渡那不得，徒存恤鸿心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和沈述之赠权干诗","p":"","d":"宋代","a":"王质","c":["江枫不敌寸心丹，何待霜雄吏自寒。满眼空空无一佛，举头在在有三官。", "毛端解运三千界，脚底常飞九万抟。凫茈馀根挑欲尽，莫忧鲁巷有颜箪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酬方司法一首","p":"","d":"宋代","a":"释居简","c":["五字堪呈佛，投珍颇惜哉。汤汤大雅后，衮衮建安来。", "逸思属万象，空庭步几回。海陵藕花幕，已为故人开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪次大涧","p":"","d":"宋代","a":"郭祥正","c":["连山接野冷光铺，望望村烟问道涂。不似在家蓬户闭，妻儿欢笑拥红炉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七夕感旧 其一","p":"","d":"近代","a":"僧果玲","c":["袈裟半袒坐层檐，仰看星桥香懒添。猛忆那年今夜月，如花人对读楞严。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八归 中秋","p":"","d":"当代","a":"陈永正","c":["当秋露重，横空河淡，堤外璧月低挂。茫茫水影愁空阔，还见乱乌惊树，雪浪连野。", "恰似暮潮拦海至，怯百幅、云帆都卸。怀故宇、冷泪如波，悄悄入怀泻。", "应念天涯鼓角，世间灯火，几日西风楼榭。隔帘难见，但闻微叹，那管容华轻谢。", "问年年此际，达曙谁同美清夜。还休倩、断翰零羽，再度关山，相思无处写。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"承坡山东郊之约借马日昃不至","p":"","d":"明代","a":"黄衷","c":["东郊雨后更芳华，出郭无过二里赊。石径尘收凡界远，绳枢星散野桥斜。", "闲情未少青林寺，并辔何曾白鼻騧。日夕有怀空徙倚，寂寥无奈瀼西家。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"经古战场","p":"","d":"明代","a":"徐熥","c":["萧条残垒不胜悲，此地曾经几乱离。恨血尚馀春草里，游魂多出夕阳时。", "潇潇寒雨闻刁斗，漠漠阴云见羽旗。满路干戈愁转战，胡笳休向马头吹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满庭芳","p":"","d":"宋代","a":"陈晔","c":["翠竹阴团，绿荷乡嫩，朝来和气盈盈。薰风楼阁，玉燕梦初成。便有功名壮志，持符节，麟虎频。更归来后，挂冠神武，四海□高名。", "今年，方八十，莱衣舞处，岨拜霞觥。想笙歌递奏，鼎沸欢声。何用渠渠颂祝，自应合、福禄安荣。丹台上，玉清山籍，金字注长生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送刘克柔尚宝祭告南行","p":"","d":"明代","a":"罗钦顺","c":["朱函分捧内廷香，旆指西南驿路长。将祀有诚宜受福，登高能赋更飞觞。", "鹤楼晚照熏残席，牛渚春潮接故乡。须忆明良千载遇，昼游虽乐未容荒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"通州雨夜寄孙中叔","p":"","d":"宋代","a":"郑獬","c":["黑雨喷薄阴云驱，昏林号风秋声粗。海气熏煮怒不泄，彭彭十月推雷车。", "湿衣悯默瞠无睡，起对樽酒谁为娱。此心岂复有双羽，一夜飞去不可拘。", "昔与子同入京师，借屋共寄西城庐。爱我议论有可采，携草就我誇染濡。", "鍊出五色补天漏，拈笔蘸墨纵横涂。子云朋友当如是，脱然意快如狞驹。", "京师天子之所宅，楼殿堆叠骑天衢。瓦光流碧滑欲走，缋画颠倒横相舁。", "东风薰浓一千里，黄蜂蝴蝶飞蘧蘧。高楼张旗斗煮酒，沉香满榼金真珠。", "玉盆一饮醉不醒，落花满衫行相扶。未几子去游西洛，嗟我出门独骑驴。", "晚落尘埃两袖泪，望子不见风吹裾。三月殿前试不中，青冥失计游五湖。", "抚剑东南看沧海，大江正值秋风初。我疑海神怒天热，直欲上薄东日乌。", "乾坤顿撼壮人意，揭竿便欲寻狂奴。九月归来已霜蚤，肥膏紫蟹溶金酥。", "南窗灯火夜可喜，箧中卷册聊铺舒。读倦抱膝一吐气，契阔各在天一隅。", "相别于今二百日，飞雁南来无北书。游从欢喜似旧否，洛下为学安稳无。", "虽然贫窘少倚赖，空肠慎勿多悲吁。圣贤独立以待用，提出日月还唐虞。", "天地当中贯一柱，孟子所谓大丈夫。躁儿跳跃不足数，插翅强欲飞蟾蜍。", "纵子不遇乃至死，勉之学为荀杨徒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王考功江东漕","p":"","d":"宋代","a":"魏了翁","c":["分部设将漕，黊旒寄聪明。", "直须撼山岳，亡但采畸赢。", "而况江以东，襟淮翼吴荆。", "民力九十空，所恃人为城。", "南宫辍望郎，方输饷连营。", "荧煌鹊锦袍，明日趋遐征。", "阳春脚未到，淑气先流莺。", "向来嵇中散，仅试薶九京。", "阿兄亦未究，有书今在楹。", "驱车踏前轨，若木以为程。", "千里隔香案，洗目观澄清。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"探春慢 寓楼对雪，颇动羁愁。季刚次韵先成此解，邀余同赋","p":"","d":"清代","a":"汪东","c":["岁晚登楼，寒深拥几，羁怀零乱无序。风剪琼瑶，云昏天地，顿觉销沈平楚。", "南雁音书少，但梦趁、江乡归橹。最怜笠泽苍茫，樵青心事谁付。", "旧著烟蓑在否。甚锁却松筠，空闭柴户。庾信生涯，梁园宾客，愁动黄昏钟鼓。", "况只萧条极，似阴积、龙沙深处。赖有天工妆点，梨花千树。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蔡玑先铉升携过东园看菊作 其二","p":"","d":"明代","a":"屈大均","c":["江左重来日，萧条益怆神。黄花犹有汝，白首更无人。", "意气期之子，文章托此身。溪流如有意，曲曲入西邻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西原晚望","p":"","d":"唐代","a":"白居易","c":["花菊引闲行，行上西原路。原上晚无人，因高聊四顾。", "南阡有烟火，北陌连墟墓。村邻何萧疏，近者犹百步。", "吾庐在其下，寂寞风日暮。门外转枯蓬，篱根伏寒兔。", "故园汴水上，离乱不堪去。近岁始移家，飘然此村住。", "新屋五六间，古槐八九树。便是衰病身，此生终老处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"已亥杂诗 232","p":"","d":"清代","a":"龚自珍","c":["诗谶吾生信有之，预怜夜雨闭门时。", "三更忽轸哀鸿思，九月无襦淮水湄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"龙泉李宗儒师儒兄弟槐阴书院","p":"","d":"宋代","a":"周必大","c":["君不见汉京辟雍载黄图，博士直舍三千区。", "分行数百曰槐市，下有诸生讲唐虞。", "又不见本朝肇启迩英阁，稽古隆儒号经幄。", "西清枝翠似交舞，日暖花黄时细落。", "君家欣慕名书斋，伯仲方将与计偕。", "桥门且陪亿万计，朝路终驰十二街。", "义郴文章妙天下，引喻牛行相君舍。", "勉君植德企前修，他日儿孙攀逸驾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题湘君图","p":"","d":"明代","a":"高启","c":["怅望南巡竟不还，泪和湘雨暮斑斑。", "须知竹死愁方尽，莫恨秦人鞭赭山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 秋衾","p":"","d":"清代","a":"周贻繁","c":["红隐芙蓉香欲透。叠处层层，巧制夸金绣。薄薄吴棉轻里就。", "嫩寒恰称清秋候。", "小病连朝如殢酒。攲枕相依，蝶梦伶俜瘦。记得残春风雨后。", "惜花长是抛难骤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"阮朗归","p":"","d":"宋代","a":"张辑","c":["孤鸿遥下夕阳寒。秋清怀抱宽。篱根香满菊金团。", "客中邀客看。", "呼浊酒，共清欢。五弦随意弹。西窗仍见好溪山。几年谁倚栏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梁思伯过洲上","p":"","d":"明代","a":"欧大任","c":["三径蓬蒿长，谁寻仲蔚门。箪瓢忘晏设，文史入宵言。", "散帙或焚蒳，钓鱼时放䑳。问津人罕到，不必记桃源。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题卧屏十八花 黄菊","p":"","d":"宋代","a":"葛立方","c":["秋入重阳气倍清，东篱采菊眼偏明。杯中要作茱萸伴，不是湘累餐落英。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庆郑敏善先生年八十应诏冠带","p":"","d":"明代","a":"黄仲昭","c":["年跻八秩未龙钟，又沐清时宠渥隆。华发谩添乌帽雪，酡颜不藉锦衣红。", "已看敬老循周典，还见优贤有汉风。况遇圣明弘治日，蒲轮早晚召申公。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古七十六首 其四十四","p":"","d":"宋代","a":"释士圭","c":["睦州只爱锥头利，这僧不见凿头方。直饶转得百千藏，这般供养也寻常。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"广雅尚书招同姚园探梅","p":"","d":"清代","a":"郑孝胥","c":["看遍官梅爱野梅，自麾驺从踏莓苔。入春风色连林觉，过雨山园一半开。", "赏会未妨饶胜事，忧勤终是靳深杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠天台郑道士","p":"","d":"宋代","a":"韩淲","c":["霞杯为奏阮咸曲，怅望十年湖水烟。闻过东嘉看雁荡，野云留宿话翛然。", "谭诗忽见蒋云出，今去洞庭衡岳前。能说鍊师神不老，识全元是赤城仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登忠勤楼听久孚贺架阁弹琴","p":"","d":"明代","a":"汪广洋","c":["画栋栖朝霞，层檐宿秋雾。", "振衣坐前楹，援琴写中素。", "幽泉鸣涧深，落花荡春莫。", "油然闻至音，令人起遐慕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"翠蛟亭","p":"","d":"宋代","a":"金坚","c":["怒猊抉石骥奔泉，谁挽河流下九天。", "倾泻琼珠三万斛，从师乞作买山钱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉真仙人词","p":"","d":"唐代","a":"李白","c":["玉真之仙人，时往太华峰。", "清晨鸣天鼓，飙欻腾双龙。", "弄电不辍手，行云本无踪。", "几时入少室，王母应相逢。"],"tags":["写人", "赞美"],"z":"玉真仙人：玉真公主。\n太华：华山。\n鸣天鼓：道家的一种法术。\n飚欻（biāoxū）：迅疾貌。腾龙，犹驾龙，乘龙。\n弄电：《太平御览》卷一三引《汉武内传》：“西王母曰：东方朔为太山仙官，太仙使至方丈，助三天司命，朔但务山水游戏，擅弄雷电，激波扬风，风雨失时。”\n少室：在河南省登封县北，主峰玉寨山为篙山最高峰。\n王母：即西王母。","y":"玉真公主真是真人啊，时时来往于华山太华峰修道。\n一清早就起来叩齿鸣天鼓，练气时双龙迅速腾起。\n不断将全身元气聚集，如电如虹，行踪如白云来去飘忽。\n何时去少室山？在那里一定可以与王母娘娘相逢。","s":"","k":"诗"},
  {"t":"人物盛乾淳","p":"唐多令","d":"宋代","a":"魏了翁","c":["人物盛乾淳，东嘉最得人。费江山、几许精神。我已后时犹遍识，君子子、又相亲。", "秋入塞垣新。风寒上醉痕。万百般、倚靠苍旻。只愿诸贤长寿健，容老我、看闲身。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"赵季茂通判惠诗走笔奉和十篇","p":"","d":"宋代","a":"岳珂","c":["天巧与天宜，雕锼焉用诗。", "冥鸿吾自爱，隐豹彼何知。", "牧笛方堪听，胡笳不奈吹。", "伤时烛之武，老矣不能为。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂七十二首","p":"","d":"宋代","a":"释祖钦","c":["步行骑水牛，空手把锄头。", "人从桥上过，桥流水不流。", "一理足，万事周。", "一尘起，大地收。", "机先别有活路，开口不在舌头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"己卯十月五日予入燕狱今三十有六旬感兴一首","p":"","d":"宋代","a":"文天祥","c":["石晋旧燕赵，钟仪新楚囚。", "山河千古痛，风雨一年周。", "过雁催人老，寒花送客愁。", "卷帘云满座，抱膝意悠悠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙","p":"","d":"当代","a":"蔡淑萍","c":["几许事儿忙了，悠闲好对孤灯。瓶中栀子送芳馨。", "旧书重捡读，字字有馀情。", "最喜旷怀高抱，还吟句丽词清。幽思远绪漫回萦。", "披衣推户牖，星朗夜天清。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄陈县尹可斋","p":"","d":"明代","a":"郑真","c":["烂柯仙客思翩翩，献赋曾闻近御筵。鸾诰香浮朱印湿，鹓班光映赭袍鲜。", "生逢明圣焦劳日，寿介慈亲喜惧年。色养望遥千里道，忠心誓答九重天。", "化覃海邑声威肃，名动枢廷礼貌专。山市春深闻促仗，官衙昼静听鸣弦。", "东风柳影青丝扬，长日萱花锦绣妍。潘岳岂能长作县，陶潜未可赋归田。", "囊中诗帙寻常看，肘后医方次第编。尚想轩居新画幛，依依情动白云篇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"经金绳废寺","p":"","d":"明代","a":"戴良","c":["寂寞唐朝寺，频年客到稀。", "空山孤殿在，荒径一僧归。", "苔色骄秋雨，松声振夕褷。", "惊乌初有托，近亦出林飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南湖二亭落成各书长句一首 其一 野芳","p":"","d":"宋代","a":"张镃","c":["望处阴云纵复横，落梅那更两关情。清愁入梦时飞蝶，远树和烟欲啭莺。", "多病半春诗债满，经旬无客酒缘轻。湖亭记取初成日，正是菖蒲斫水生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"斗湖道人诗","p":"","d":"明代","a":"杨士奇","c":["家临斗湖滨，门对斗湖上。明镜影香台，文波绣仙氅。", "诵经无辍口，谭道若指掌。为霖从潜虬，飞符驱魍魉。", "止水涵湛然，可以喻心想。一谢湖边人，终年罢来往。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠别王十七管记","p":"","d":"唐代","a":"高适","c":["故交吾未测，薄宦空年岁。晚节踪曩贤，雄词冠当世。", "堂中皆食客，门外多酒债。产业曾未言，衣裘与人敝。", "飘飖戎幕下，出入关山际。转战轻壮心，立谈有边计。", "云沙自回合，天海空迢递。星高汉将骄，月盛胡兵锐。", "沙深冷陉断，雪暗辽阳闭。亦谓扫欃枪，旋惊陷蜂虿。", "归旌告东捷，斗骑传西败。遥飞绝汉书，已筑长安第。", "画龙俱在叶，宠鹤先居卫。勿辞部曲勋，不藉将军势。", "相逢季冬月，怅望穷海裔。折剑留赠人，严装遂云迈。", "我行将悠缅，及此还羁滞。曾非济代谋，且有临深诫。", "随波混清浊，与物同丑丽。眇忆青岩栖，宁忘褐衣拜。", "自言爱水石，本欲亲兰蕙。何意薄松筠，翻然重菅蒯。", "恒深取与分，孰慢平生契。款曲鸡黍期，酸辛别离袂。", "逢时愧名节，遇坎悲沦替。适赵非解纷，游燕往无说。", "浩歌方振荡，逸翮思凌励。倏若异鹏抟，吾当学蝉蜕。"],"tags":["送别", "抒怀", "怀才不遇"],"z":"⑴王十七：即幽州节度使张守珪的管记王悔。管记：掌管文牍的官员。\n⑵薄宦：居官低微。\n⑶曩：过去，以往。\n⑷产业：财产。\n⑸飘飖：即飘摇。\n⑹立谈：指时间短促之间。\n⑺月盛：月满之时。\n⑻冷陉：山脉名称，在今辽宁开原。\n⑼欃枪：彗星的别名。\n⑽已筑长安第：意指边将不关心国家边防，只关注自己的私产。\n⑾宠鹤：语见《左传·闵公二年》：“卫懿公好鹤，鹤有乘轩者。”\n⑿海裔：海边。\n⒀缅：思虑的样子。\n⒁临深：面临深渊。\n⒂褐衣拜：以平民的身份入拜朝中。\n⒃水石：清水、白石，比喻贤良清廉之人。兰蕙：两种香草，比喻品质高尚者。\n⒄薄：接近。松筠：松树和竹子，比喻志行高洁之人。\n⒅款曲：衷情。\n⒆适赵：反用鲁仲连为赵国排忧解难的典故。游燕：反用苏秦到燕国游说的典故。\n⒇鹏抟：大鹏展翅高飞，典出《庄子·逍遥游》。蝉蜕：喻指远离尘俗。","y":"我那些旧日的朋友都音信杳然，居官卑微，空度了几多年华。你的节操直追先贤，你雄浑的诗文的当世最好的。\n你的厅堂之中坐满了食客，对外还欠着许多酒债。你从不言及财产积累之事，与朋友共衣，即使穿破了也毫不在意。\n你供职幕府，随军转徙，出入于关隘山峰之间。苦战之时不以所谓豪情壮志为意，瞬息间并能拿出安定边塞的妙计。\n云雾、沙尘在风中回旋、聚散，天穹空旷高远。月盛星高，战斗十分频繁，当此之时唐军将领却十分骄纵，而胡人军队锐气正盛。\n沙漠渊深阻断冷陉，雪天里天光暗淡，辽阳城门紧闭。本来说要消弭兵患，却突然惊讶地发现自己已深陷敌阵。\n先期归来的军队回来时说是打了胜仗，而逃回的骑兵却传来战败的实况。军中远远地传来求援的文书，而主帅已在长安城中建起了自己的私第。\n朝廷徒有好士之名，受到朝廷恩宠的败军将领反而先行返回了长安。将领不要争抢部署的功劳，部署不应凭借将军的威势。\n我们的冬季之月相遇，惆怅地望着远方的海边。解下长剑送给你，你将整肃衣裳踏上远行之路。\n我离开家时就已充满了忧虑，到了这里又长期遭受阻绊。我虽没有周济当代的谋略，却还算兢兢业业。\n随着波浪或清或浊，和物体一样或丑或美。闭着眼睛想着那栖居于青岩之间，忘却那追逐功名之事。\n我一直都希望能与贤良清廉之人为伍，与品德高尚的贤者相伴。为何我与志行高远之人相伴，却仍然才质平平。\n我一直十分谨慎于义利的取舍，哪里敢怠慢平素做人的原则？此时我热情地招待你，可惜又要痛苦地和你分别。\n我虽遇上好时候，惭愧的是不能树立美好的名誉和节操。到了赵国却不是去排忧解难，到了燕国也没有达到游说的目的。\n浩大的歌声正回荡在天空，遒劲的鸟儿正想着凌空飞翔。你将如奇异的大鹏鸟那样，忽然间展翅高翔，我且学习那蝉蜕去外壳一般隐居去吧。","s":"","k":"诗"},
  {"t":"走笔谢张功父送似酴醾","p":"","d":"宋代","a":"杨万里","c":["西湖野僧誇藏冰，半年化作真水精。南湖诗人笑渠拙，不如侬家解乾雪。", "藏冰窨子山之幽，镵透九地山鬼愁。侬家藏雪有妙手，分明晒在翡翠楼。", "向来巽二拉滕六，玉妃夜投玉川屋。剪水作花吹朔风，揉云为粉散寒空。", "醉挥两袖拂银汉，梢头万斛冷不融。琼田挈月拾翠羽，砌成重楼天半许。", "盘作青蛟吐绿雾，乱飘六出薰沉炷。人间雪脆那可藏，天上雪落何曾香。", "三月尽头四月首，南湖香雪今谁有，分似诚斋老诗叟。", "碎挼玉花泛春酒，一饮一石更五斗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"社鼓","p":"","d":"宋代","a":"毕仲游","c":["社鼓鼕鼕南北村，老人相倚话柴门。自从嘉祐初年后，直至元丰有稻孙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日杂诗 其六","p":"","d":"近代","a":"温倩华","c":["柳烟分绿上眉头，水皱山颦不自由。已是閒愁愁未了，又因风雨替花愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"相如驷马桥","p":"","d":"明代","a":"王绂","c":["相如辞赋拟风骚，浪迹临邛逸气飘。犊鼻岂应亲涤器，驷车直欲预题桥。", "才名当世黄金重，志愿凌云碧汉遥。富贵如何才满意，白头吟里恨偏饶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别绪","p":"","d":"唐代","a":"韩偓","c":["别绪静愔愔，牵愁暗入心。已回花渚棹，悔听酒垆琴。", "菊露凄罗幕，梨霜恻锦衾。此生终独宿，到死誓相寻。", "月好知何计，歌阑叹不禁。山巅更高处，忆上上头吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪狮儿 本意","p":"","d":"清代","a":"陈维崧","c":["雕霜捏粉，作西域、万里狻猊，攫拿爪踞。侧脑平芜，猛气骁腾何怒。", "奔犀骇虎。更何论、田间狡兔。似鲍老、装成假面，筵前决赌。", "道上儿童戏汝。算冰澌雪尽，愁伊无据。恰遇狮王，微笑掷花而语。", "明驼洛下，费几许、铜山才铸。今何处。一样荒烟细雨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用李廷琼寓中都口号韵三首 其二","p":"","d":"明代","a":"郑真","c":["锦绣河山绕帝京，南来为客最多情。芸编慢忆三千牍，桂籍空惭第一名。", "燕寝声传城柝近，魫窗凉透水云轻。知君正得青春乐，有约清樽对月倾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荆树分阴","p":"","d":"明代","a":"吴宣","c":["荆花竟谁授，解复人心初。如何七尺躯，翻令百行疏。", "气聚天始完，流深海不墟。于兹竟莫悟，泣下收吾书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次静凤中秋薄阴韵","p":"","d":"当代","a":"傅义","c":["岁岁今宵月，何为分外圆？岂关多粉饰，竟可胜天然？", "玉洁知谁及，环游可自便？高明羡骚裔，别有梦中天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游燕喜次韵","p":"","d":"明代","a":"李邦义","c":["湟川山水旧传名，暇日来游燕喜亭。细扪萝藤寻古刹，徐穿岩洞觅仙灵。", "卧龙故址云常白，梦得遗墟草漫青。千载风流人不见，惟闻山下水泠泠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"齐世家","p":"","d":"宋代","a":"李觏","c":["莫以荒淫便责君，大都危乱为无臣。若教管仲身长在，何患夫人更六人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日感怀寄所知","p":"","d":"唐代","a":"刘得仁","c":["了了见岐路，欲行难负心。趋时不圆转，自古易湮沉。", "日正林方合，蜩鸣夏已深。中郎今远在，谁识爨桐音。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"君道篇","p":"","d":"明代","a":"胡奎","c":["君道天广大，王言出如纶。雨露及草木，万物皆阳春。", "九重坐南面，四海奉一人。禹稷犹已溺，唐虞视同仁。", "华盖当中天，列星环北辰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏玉韘","p":"","d":"清代","a":"弘历","c":["牙角徒传古，璆琳复见兹。虚中离象卦，圆外月盈规。", "讵止佩环用，兼成弓矢资。谁能连命中，差不愧瑰奇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"演雅十章","p":"","d":"宋代","a":"张至龙","c":["蚕饱办丝课，蜂忙供蜜工。", "役役为人劳，衣食还自空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春闺八首 其五","p":"","d":"明代","a":"郭之奇","c":["飞蓬辞膏沐，无复向妆谋。卉木犹春好，妾鬓独惊秋。", "鬒云终何似，已当吟白头。谁怜拥髻泣，愁绝自登楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自题渔舟写真二首 其二","p":"","d":"清代","a":"袁世凯","c":["百年心事总悠悠，壮志当时苦未酬。野老胸中负兵甲，钓翁眼底小王侯。", "思量天下无磐石，叹息神州变缺瓯。散发天涯从此去，烟蓑雨笠一渔舟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"唐磐石五世兄话别 其一","p":"","d":"明代","a":"黄公辅","c":["袂把天涯喜欲狂，且抛尘事共相将。子西遮莫前身是，彭蠡堪誇逸兴长。", "聒聒鸠声侵客坐，霏霏梅雨洒离肠。淡交不问弹冯铗，赖有南薰送远航。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乙老六十九岁生日祝词 其三","p":"","d":"清代","a":"陈曾寿","c":["敝帽欹徐整，深衣绝屡缝。外形从躐蹋，自哂托龙钟。", "雾豹深冥见，云龙合漠从。卿容晬书气，天语肖高宗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用强甫蒙仲韵十首 其九","p":"","d":"宋代","a":"刘克庄","c":["已傍先庐敞便斋，善和万卷与君偕。少时岁月真驰隙，圣处工夫未涉涯。", "海浅蓬莱疑可近，云深阊阖不容排。信书至老成何事，有酒聊浇磊块怀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"方日升杂画四首 其四 白雉","p":"","d":"明代","a":"边贡","c":["迢迢越裳国，万里献珍禽。不睹周王化，谁知姬旦心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"云仙引 秋云","p":"","d":"清代","a":"王易","c":["旋出巫峰，乍收秦岭，秋来无限轻盈。遮溪白，傍山青。", "汀洲荻花如雪，隔水相看分外明。独有愁人，虚窗深院，相对愁生。", "天孙巧锦堪称，问多少、功夫织得成。蜀绮轻匀，吴绫细密，自费心情。", "天末怀人，江干惜别，望去应知泪暗倾。一夕风高，残鳞断羽，何处飘零。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"得董汉苍北京信诗以答之","p":"","d":"近代","a":"杜关","c":["十年书恨寄柴扉，怅望天涯泪欲挥。一样流离之子在，等閒肝胆故人非。", "干戈送老行藏定，荆棘馀生去住违。见说官贫风雪厉，盼君病起不如归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"甲辰闰月初伏快雨凉风昼眠初觉庭前小栏花木各有意气效柏梁体","p":"","d":"宋代","a":"蔡襄","c":["闰夏天地热焰烘，崇朝快雨随清风。昼轩梦觉开前栊，画栏花草意气雄。", "侧枕遥问数异同，如子微物烦化工。盍各言尔之所从，繁葩富艳生朱红。", "枯条大蕊千万重，修干点缀赤日中。蠲去忧忿谁与功，采摘烹煮祛烦胸。", "秋霜钜实垂如瓮，横柯远引交加丛。叶抽绿剑端黄茸，直立开拂泉货通。", "叠绕翠羽翻虬龙，误入畦町非余公。助涤渴肺思匪躬，物物自名词不穷。", "愿当我意乃汝容，负汝不饮惭衰翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送方岩夫四首","p":"","d":"宋代","a":"方回","c":["同姓同年绾左符，岭南万里送孀孤。", "先君遗墨今犹在，为问封州有后无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江上值雪效欧阳体限不以盐玉鹤鹭絮蝶飞舞之","p":"","d":"宋代","a":"苏轼","c":["缩颈夜眠如冻龟，雪来惟有客先知。", "江边晓起浩无际，树杪风多寒更吹。", "青山有似少年子，一夕变尽沧浪髭。", "方知阳气在流水，沙上盈尺江无澌。", "随风颠倒纷不择，下满坑谷高陵危。", "江空野阔落不见，入户但觉轻丝丝。", "沾掌细看若刻镂，岂有一一天工为。", "霍然一挥遍九野，吁此权柄谁执持。", "世间苦乐知有几，今我幸免沾肤肌。", "山夫只见压樵担，岂知带酒飘歌儿。", "天王临轩喜有麦，宰相献寿嘉及时。", "冻吟书生笔欲折，夜织贫女寒无帏。", "高人著履踏冷冽，飘拂巾帽真仙姿。", "野僧斫路出门去，寒液满鼻清淋漓。", "洒袍入袖湿靴底，亦有执板趋阶墀。", "舟中行客何所爱，愿得猎骑当风披。", "草中咻咻有寒兔，孤隼下击千夫驰。", "敲冰煮鹿最可乐，我虽不饮强倒卮。", "楚人自古好弋猎，谁能往者我欲随。", "纷纭旋转従满面，马上操笔为赋之。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄景逊","p":"","d":"宋代","a":"文同","c":["别后西城上，来须到日曛。", "目迎秦塞雁，心过陇山云。", "寡合无如我，高怀少似君。", "相思只相望，徒尔托云云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"客寄天台月桂子","p":"","d":"宋代","a":"刘敞","c":["天上仙人月里栽，无端飘逐海风来。可能种作千寻树，岁看高花烂漫开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题墨竹四首 其四 老","p":"","d":"明代","a":"唐文凤","c":["潜虬跃重渊，鳞甲半脱落。未愁风云生，只恐雷雨作。", "变化不可羁，虹光射天末。含情望三湘，翠袖侵寒薄。", "皇英久未归，苍梧烟漠漠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闲居二首 其一","p":"","d":"明代","a":"鲁铎","c":["别墅仍书屋，闲居兴颇奇。野山争入座，田水暗通池。", "鸟语花深处，鱼游月上时。坐阑还散步，聊复有新诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"耆英会 其一","p":"","d":"宋代","a":"席汝言","c":["系国安危唐上宰，功成身退汉留侯。二公闲暇开高宴，九老雍容奉胜流。", "共接雅欢恩意洽，不矜崇贵礼容优。赏心乐事人间盛，岂谓今稀古莫俦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游庄严寺园","p":"","d":"宋代","a":"贺铸","c":["石楠花落小池清，独下平桥弄扉行。", "蔽日绿阴无觅处，不如归去两三声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"贤者之孝二百四十首 其一○○ 郭基","p":"","d":"宋代","a":"林同","c":["岂伊东閤里，无似督邮贤。直把孝行荐，今人少孟坚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和族祖紫岩翁谩兴十首 其九","p":"","d":"宋代","a":"汪炎昶","c":["桃李贵以色，兰蕙贵以香。蚌胎秘奇彩，萤火耀寸光。", "中心固了了，竟莫辨否臧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"日来欢意顿减幸秋雨既足中秋定晴预约南坡小集观月且属耘老弟董其事","p":"","d":"宋代","a":"虞俦","c":["酒熟床头已圣清，吟诗窗下莫悲鸣。故人明月从来共，今岁中秋定好晴。", "雨脚已随荷盖尽，风头还逐桂花生。试谋一笑君须会，谁道尊前笑不成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"芝兰章 其二","p":"","d":"明代","a":"韩上桂","c":["芝之生矣，维其荣矣。仙之游矣，维其灵矣。茹紫芝，乘云车。", "入参寥，历玄虚。上有太华之真经，元始之丹书。", "长相随，揽龙须。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟次唐行","p":"","d":"明代","a":"郭谏臣","c":["江乡逢暮春，一棹舣沙滨。客路看飞絮，行厨荐绿蘋。", "冠裳时暂远，鱼鸟渐相亲。长啸乾坤里，悠然著此身。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古战场","p":"","d":"唐代","a":"张蠙","c":["荒骨潜销垒已平，汉家曾说此交兵。", "如何万古冤魂在，风雨时闻有战声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新月光寒昨夜霜","p":"鹧鸪天","d":"宋代","a":"佚名","c":["新月光寒昨夜霜。三年不一奉瑶觞。朱颜大药知能驻，白日仙家岂计长。枫渐赤，橘初黄。五湖烟水动归航。且倾寿酒歌难老，便见除书出未央。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"春云","p":"","d":"元代","a":"马祖常","c":["高云起城阙，流离度庭树。依风拂回塘，波缬光影注。", "荒林带疏烟，照日乱萦缕。婉娈连浮阳，空明映凄雾。", "岚翠含玉晖，景采满岩屿。逍遥幽赏谐，缅邈世娱阻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"壬申元夜感赋二章 其二","p":"","d":"当代","a":"熊盛元","c":["半世飘零处处家，只从冷淡觅生涯。霜侵鬓发人千劫，诗写穷愁鬼一车。", "旧梦绿牵堤上柳，绮怀红幻镜中花。今宵酒酿他年泪，洒向心头绽苦芽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏物二十四首","p":"","d":"清代","a":"周凯","c":["肉角双双出蜗舍，壳纹细细似沈香。回环文理浑如木，性比蛼蚝分外凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题莫公台","p":"","d":"唐代","a":"杜光庭","c":["奇绝巍台峙浊流，古来人号小瀛洲。路通霄汉云迷晚，", "洞隐鱼龙月浸秋。举首摘星河有浪，自天图画笔无钩。", "将军悟却希夷诀，赢得清名万古流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈二首 其一","p":"","d":"宋代","a":"释清旦","c":["三世诸佛不知有，一一面南看北斗。狸奴白牯却知有，云外金毛正哮吼。", "个中隐显现全身，头头透脱无前后。拨转机轮向上关，八角磨盘空里走。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖山十景 其四 曲院风荷","p":"","d":"宋代","a":"王洧","c":["避暑人归自冷泉，步头云锦晚凉天。爱渠香阵随人远，行过高桥旋买船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"台中","p":"","d":"明代","a":"释函可","c":["无聊长寄一枝筇，悔不同君四百峰。旧榻尽容狞虎待，半铛常煮野云供。", "到家应共怜穷子，博饭无如学老农。从此入山惟稳睡，只愁僧打五更钟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和慧知微雪韵","p":"","d":"宋代","a":"释慧空","c":["覆盖乾坤似有功，洞然明白却无踪。", "其如未识无踪意。屑玉霏霏落眼中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"前之十首次诗","p":"","d":"宋代","a":"释行海","c":["十五游方今五十，骎骎白尽少年头。", "看来造物真儿戏，忆著平生冷汗流。", "宇宙何须三兔窟，山川总是一菟裘。", "眼前不见江湖处，终是相忘欠白鸥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"从田桥石径赴拂水","p":"","d":"明代","a":"皇甫冲","c":["江光开初霁，山云未全敛。", "轻烟尚栖花，积雨犹在藓。", "携屐遵回麓，援萝上修岘。", "环林何透迤，磴道几回转。", "游心自忘罢，策足乃知蹇。", "含章乐丘园，耽隐易台铉。", "顿使昔念舒，乃得今抱展。", "将寻出世人，一往不复返。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再次还鹤韵三首 其二","p":"","d":"宋代","a":"陈造","c":["啅鹊却陪新饮啄，啼猿俨识旧容仪。可须辩士诳荆楚，似喜逐臣还秭归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王至卿借骑入长安赋谢","p":"","d":"明代","a":"胡应麟","c":["未遘中涓访，犹勤上驷来。壮心悬伏枥，逸足借登台。", "䟤跋看龙种，飞腾羡骏才。天闲云五色，矫首见蓬莱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渡江云 寒食寄怀何磊任平","p":"","d":"近代","a":"邓桐芬","c":["初阳分远霭，晓寒渐薄，草色浸疏棂。数声啼鴂外，解事东风，布暖发深青。", "红香半砌，讶年光、寒食清明。春未阑，且留尊酒，重与话平生。", "消凝，茶瓯伴榻，药管施针，抱年年残病。空梦想、西江旧月，北国严城。", "故人咫尺天涯邈，枉目断、烟水迷冥。凭杖去，逡巡却恨伶俜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长饥","p":"","d":"近代","a":"洪传经","c":["三春花未发，蜂蝶合长饥。排闷倾深盏，抒怀得小诗。", "蓬门罗雀久，尘榻赖龟支。苦忆东陵子，瓜田何处随。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"永昭陵挽词三首","p":"","d":"宋代","a":"欧阳修","c":["干戈不用臻无事，朝野多欢乐有年。", "便坐看挥飞白笔，侍臣新和◇梁篇。", "衣冠忽见藏原庙，箫鼓愁闻向洛川。", "寂寞秋风群玉殿，还同恍惚梦钧天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渔家傲 夏日","p":"","d":"清代","a":"钱启缯","c":["六月荷花香十里。三秋桂子醉难倚。风过新蝉声细细。", "听归雁，呼环莫把纱窗闭。", "帘捲落花疑蝶视。阶前络纬初鸣际。凭栏笑把轻纨启。", "看青天，■香一缕随风至。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽张布政","p":"","d":"明代","a":"张宁","c":["万里云霄早致身，清时人物旧儒绅。四朝宠遇推良弼，一代勋名属老臣。", "青琐才高天上诏，紫薇花落梦中春。经纶未尽英雄死，海水东流夜月新。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和友人","p":"","d":"宋代","a":"王之望","c":["弟兄南渡各驰驱，向奉君王尺一除。", "黄耳音书寄怀抱，乌衣门巷惜丘墟。", "澄清孟博荣持节，雅量玄平静著书。", "五桂家风殊未艾，黄山佳气蔼如初。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"社西村 其五","p":"","d":"明代","a":"陈献章","c":["社西逢酒伴，埭北有花枝。讵识愚公意，聊同牧竖嬉。", "围棋松崦久，度马板桥迟。袖有葳蕤草，还家不告饥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初秋夜同林太史过萧太史书斋","p":"","d":"明代","a":"区大相","c":["结庐虽傍市，种竹近成林。乍到安禅地，终谐大隐心。", "开轩迎苑月，隔牖度城砧。已惬山泉赏，何须云壑寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过琴溪","p":"","d":"唐代","a":"杜伟","c":["州府谪宦居，邑城摄官涖。悠悠泾川适，佳期此相迟。", "灵溪知几曲，曲曲各殊致。仙岭多巉颜，前峰特超类。", "穹崇势旁倒，山客下无地。洞穴盘龙蛇，空岩隐魑魅。", "蘋开秋水绿，竹动寒山翠。远嶂数瀑悬，疏林一猿坠。", "依然弹素弦，流我望乡泪。席上红泉飞，樽前白云至。", "中山是隐居，缅想故心醉。忽睹邢武辞，聆其金石备。", "神交十载得，良愿三人遂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠赵山甫","p":"","d":"元代","a":"房皞","c":["寇盗连年剧猬毛，一身无处可奔逃。陈平自合西归汉，诸葛焉能北事曹。", "嗟我命兼才共薄，仰君名与德俱高。几时一笑沧浪畔，右手持杯左手螯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大行皇帝挽歌辞三首 其二","p":"","d":"明代","a":"李东阳","c":["圣朝偃武修文日，共道王言似六经。宋史重施新衮钺，孔庭增饰旧笾铏。", "垂衣共仰升龙象，赐墨皆成翥凤形。回首茂陵松柏树，春来还向裕陵青。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同王昌龄裴迪游青龙寺昙壁上人兄院集和兄维","p":"","d":"唐代","a":"王缙","c":["林中空寂舍，阶下终南山。", "高卧一床上，回看六合间。", "浮云几处灭，飞鸟何时还。", "问义天人接，无心世界闲。", "谁知大隐者，兄弟自追攀。"],"tags":["抒怀", "隐居"],"z":"","y":"","s":"","k":"诗"},
  {"t":"兰溪访吴圣与不遇","p":"","d":"宋代","a":"李纲","c":["夕次兰溪县，溪山照眼明。云端双塔耸，烟际一桥横。", "久旅易悽感，旧游如隔生。故人寻不值，飘泊若为情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寻梅三首 其一","p":"","d":"宋代","a":"张镃","c":["绀碧烘晴水照天，断槎荒葑牧羝田。数旬不踏苏堤路，专为梅花跨晓鞯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"相国赵公邸中夜谈因留宿斋头作","p":"","d":"明代","a":"胡应麟","c":["剧语深杯兴未阑，平章西第傍金銮。高斋敢谓青绫薄，煖阁浑忘白苧寒。", "密筱飞霜流藻井，疏桐移月下雕栏。无劳夜望三台色，万仞晴光烛翠峦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"薇山处过番石渡遭渡子无礼伤臂因韵","p":"","d":"宋代","a":"陈著","c":["卧如龙奋亮当贵，射可猿通广欲飞。谁料舟人为敌国，祇应山鸟怪儒衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"木芙蓉","p":"","d":"宋代","a":"邓深","c":["露冷烟凄草树荒，木芙蓉好试平章。", "蒲萄晚叶尤宜日，芍药秋花正耐霜。", "蜀锦卷帏妆院落，秦宫开镜照池塘。", "写容安得剑南老，聊复殷勤酹一觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"恭睹圣心勤劳颂扬不尽又成长句","p":"","d":"清代","a":"胤禛","c":["叨陪法驾阅新堤，夙夜辛勤悯庶黎。底定九河功媲美，时巡三辅典堪稽。", "烟村黯黯青帘扬，岸柳阴阴白马嘶。沉璧寘薪诚默契，神人应有绿图携。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洞庭新建厅事柱下获一瓮中有钱曰太平喜而口占","p":"","d":"明代","a":"王鏊","c":["一钱清白承先哲，八柱高明应宰司。天赐不多良自贺，国家重建太平基。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送寿山人","p":"","d":"明代","a":"胡应麟","c":["飘然沧海客，曾事紫阳君。袖里黄庭字，囊中赤伏文。", "放舲三泖月，携杖九峰云。后夜华亭梦，应同鹤唳闻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庆元二年皇后册宝十三首 其四","p":"","d":"宋代","a":"郊庙朝会歌辞","c":["帟旒云舒，金秀充庭。璇卫銮华，茜佩垂𦀚。皇容熙备，柔仪顺承。", "三宫齐欢，万福昭膺。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渡江云 十二月十三夜望月，和次香韵","p":"","d":"清代","a":"易顺鼎","c":["古愁流一发，冻华湿瓦，天影欲离青。婵娟初斗罢，密迩佳期，好事会圆成。", "微遮茜袖，想峭鬟窥树轻盈。须后夜瑶空雪意，补足二分明。", "吟声。花间暗度，唤起冰轮，悄催他端正。还只恐庞儿越瘦，不耐风棱。", "影娥池上无人到，管荒波半角枯菱。仙梦冷，寒簧被也霜凝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"武丘寺","p":"","d":"宋代","a":"释兴肇","c":["高僧危阁侵云际，尽日披襟濯好风。", "极目长川人不见，万株烟树接遥空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乙未正月初二大连客舍临孔子庙堂碑至解黻去佩书烬儒坑八字慨然有作","p":"","d":"当代","a":"程滨","c":["但有昏灯对一檠，当窗焰火动心兵。他乡临帖消长夜，末世裁诗了此生。", "华发皑皑天未雪，回肠隐隐剑初鸣。神州欲破千秋梦，秽史新书万岁名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元日","p":"","d":"宋代","a":"刘旦","c":["元日甘泉会，衣冠拜冕旒。", "图书一四海，玉帛万诸侯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"胡登仕送花","p":"","d":"宋代","a":"方岳","c":["一年春是牡丹时，不负花时只有诗。", "老去自知才思尽，枉分风月到山篱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨夜读书","p":"","d":"宋代","a":"陆游","c":["风雨澒洞吞孤村，读书拥褐不出门。", "历观忠邪见肝肺，直与治乱穷根原。", "博岩之野感帝梦，此事难以今人论。", "危冠长剑一见用，万里耕桑吾道尊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"写扇寄刘升","p":"","d":"明代","a":"杨士奇","c":["不到珠林五六春，閒窗书卷故殷勤。别时看种庭前竹，远想长枝已拂云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"世贸三歌 其二 飞机歌","p":"","d":"当代","a":"卢青山","c":["瞠彼西方兮，飞其机矣。以暴逗暴兮，自古之规矣。", "神农虞夏日自吹兮，世果安归矣。于嗟徂兮，文明之衰矣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"成帝时歌谣","p":"","d":"魏晋","a":"佚名","c":["邪径败良田，谗口乱善人。桂树华不实，黄爵巢其颠。", "故为人所羡，今为人所怜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梦横塘 简筜谷","p":"","d":"清代","a":"李符","c":["鸭头酥雨，雁背尖风，峭帆催别春市。几月秦淮，换细葛、芙蕖香里。", "秧珑耕蓑，柘村缲茧，顿牵乡思。上层楼试望，甚处家林，斜阳外、重重水。", "西邻旧筑渔矶。共棋灯笛月，今隔千里。银沫青笺，盼不到、一双花鲤。", "料只在、吴根越角，谁与衔杯伴吟袂。且待归来，约移秋艇，采菱红莼翠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古八首","p":"","d":"宋代","a":"释道颜","c":["椎锣擂鼓转船头，席卷波翻喊激流。", "洗脚上船乘快便，顺风相送下扬州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"张见甫自新蔡来访得情字书字二首 其一","p":"","d":"明代","a":"欧大任","c":["竹林残暑摄衣迎，揖客西来坐尽倾。异代河山扶片语，中原渔猎傍时名。", "马嘶讲肆非官舍，鸾啸高天岂世情。囊有酒钱君莫问，金鞍还许过孤城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再次上京杂咏韵十首 其七","p":"","d":"元代","a":"袁桷","c":["土驿高低置，苍茫七日程。马通分熠耀，牛酪注深清。", "残雪明珠阙，繁星列火城。前山黄白处，草药不知名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆潼关","p":"","d":"唐代","a":"徐夤","c":["洞壑双扉入到初，似从深阱睹高墟。天开白日临军国，", "山夹黄河护帝居。隋炀远游宜不反，奉春长策竟何如。", "须知皇汉能扃鐍，延得年过四百馀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"就正斋九日赏菊","p":"","d":"清代","a":"胤禛","c":["重阳高会幔亭张，阶下寒英正吐芳。为羡霜丛矜晚节，同来香径领秋光。", "嘉宾落帽风流在，绮席征歌雅兴长。却笑当年彭泽叟，东篱寂寞独倾觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉和竟陵王经刘瓛墓下诗","p":"","d":"南北朝","a":"柳恽","c":["西河寂高业，北海望清尘。音徽谁与寄，尚德在伊人。", "遗文重昭晢，绝绪复纷纶。露华尚朝日，兰生无久春。", "芳猷动渊思，抚轼履高辰。山风起寒木，野雀乱秋榛。", "垄草时易宿，素轨邈难遵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送杨司谏之南京","p":"","d":"明代","a":"徐溥","c":["同云漫漫未成雪，故人握手都门别。马蹄蹴裂沙河冰，雁声叫落淮阴月。", "关西自古清白声，甲科早掇超群英。手持风裁下南国，谏草日日来承明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"陟东门 其二","p":"","d":"明代","a":"霍与瑕","c":["陟东门，望望白云。安期一去，今几千春。白云长在，视安期之迹若飞尘。", "猗硕人之寿兮，寿若白云。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古七十六首 其四十三","p":"","d":"宋代","a":"释士圭","c":["雷火光中休草草，剑轮锋上莫忉忉。等闲放却全身入，终不当头犯一毫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"今我不乐三章章五句 其三","p":"","d":"元代","a":"张翥","c":["月白西南星宿稀，巷无行人蝙蝠飞。步檐萧萧露沾衣，目断天涯遍芳草，王孙不归春自归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送黄义庵还闽","p":"","d":"明代","a":"林廷选","c":["半生宦辙接清游，前是苏州后越州。桃李满门閒即乐，江湖驰阙远还忧。", "别愁晚浦闻鸣雁，归趣晴沙对懒鸥。试问六平旧同馆，白头林下几人休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读邵康节击壤集二十首 其十一","p":"","d":"明代","a":"薛瑄","c":["排风御气复鞭霆，历览无边造化情。随分自能安至乐，玩心谁复识高明。", "先天图有年年运，皇极书为世世经。首尾诗成多寓兴，调高白雪少人听。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"花心动 牵牛花，同子年韵","p":"","d":"清代","a":"郭则沄","c":["银汉分凉，误婵娟、仙衣五铢初试。露缀钿轻，风飐铃圆，扶上晚篱烟紫。", "锦棚一角秋来早，只閒伴、吟人无睡。蓦肠断、红墙浅梦，暗蛩啼碎。", "宛转愁丝自系。偏盼到星期，替人憔悴。妒煞汉宫夜月，鸳机虚伴，渚莲香坠。", "洗车消息前番雨，认绡碧、几痕残泪。数离绪年年，倩伊细记。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"口号呈问庞二少府","p":"","d":"明代","a":"边贡","c":["黄鹤楼前夜泊舟，苇花枫叶似江州。乐天本是多情客，卧听歌声起别愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"萤火","p":"","d":"明代","a":"孙作","c":["雨中萤火看不灭，入户潜行欲近人。槐市书生经满案，微光待汝续鸡晨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百四十一首 其四十二","p":"","d":"宋代","a":"释师范","c":["正觉山前，双林树下。弄假像真，弄真像假。临风哮吼戴嵩牛，顾影嘶鸣韩干马。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送黄亮垣先生还朝","p":"","d":"明代","a":"李孙宸","c":["凉飔飒飒惊秋节，三城官柳鸣蝉咽。越王台倚越山云，王气千秋可揽结。", "传呼候馆抗前旌，夜来南斗避文星。津亭冠盖不知数，共言祖送黄先生。", "先生三朝旧名德，神庙贤良策第一。藉冠宫寮侍从班，身依子舍承欢日。", "年来冲圣御龙楼，讲幄文儒礼数优。金匮两朝徵实录，前席时虚待校雠。", "以此征车难久驻，谢传东山起别墅。行边烟雨五陵花，望里春云万家树。", "到日金銮凤翼开，如椽史笔总鸿裁。谟烈显承光琬琰，始信龙门一代才。", "圣明有道勤宵旰，夔龙勋业盈霄汉。宣麻早晚拜先生，伯仲之间见伊旦。", "蹇予夙昔托追游，归来一病狎沧洲。临岐自怅典型远，飞梦长随入帝州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄刘秀才","p":"","d":"宋代","a":"释重显","c":["远远飞来一幅书，愈风诚重复何如。相逢相见未期日，目断千山插太虚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与小儿助子游江横作","p":"","d":"宋代","a":"蒲寿宬","c":["葺荷偶忆湘累句，築屋还寻杜若汀。", "孤树每留残日白，片帆徐度远山青。", "海鸥知我断机虑，渔父与谁分醉醒。", "何处扁舟横短笛，月明风袅不堪听。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"以嗜酒爱风竹卜居此林泉为韵作十小诗 其五","p":"","d":"宋代","a":"方岳","c":["周有说爱莲，陶有诗爱菊。吾居则谁与，其诸子猷竹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和程德裕颂五首","p":"","d":"宋代","a":"黄庭坚","c":["石田耕种难成稻，荼蓼栽来只苦辛。", "万物一家真富贵，使君见後却清贫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汉玉赤刀歌","p":"","d":"清代","a":"弘历","c":["出匣宝气腾葱郁，秋水一湾落霞拂。游刃恢恢岂少𠜾，疑有丁甲相呵㗵。", "蟠虬之而鼌采蔚，当年西序横陈物。介绍大训连朱芾，姬室文明此黼黻，遐思成康不可迄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红","p":"","d":"宋代","a":"陈之贤","c":["人物英雄，更独抱、无双才气。年正壮，文章武略，尽曾留意。破胆欲凭胸内甲，清原宴启舟中誓。笑区区、燕雀不能知，青云志。", "封侯貌，神人比。社下手，须荣试。况相门出将，君家常事。斗印垂金他日贵，寿杯浮玉今朝醉。看年年、南极倍明时，春明媚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜夜曲","p":"","d":"明代","a":"胡奎","c":["夜夜望明月，初若蛾眉弯。夜夜望明月，今如白玉盘。", "玉盘有时缺，蛾眉愁万结。月照闺中人，如何有离别。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百二十三首","p":"","d":"宋代","a":"释普度","c":["雨洗炎威，秋磨霄汉。", "风传{左禾右罢}稏香，鼓腹寒岩畔。", "位转功回木马嘶，劫外不须重借伴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"贺郑枢齐 其五","p":"","d":"宋代","a":"刘子寰","c":["紫闼黄枢功已著，苍生黔首望逾深。公施政术施仁术，公得人心得士心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵李明府上事初谒登源庙用苏黄门韵见示","p":"","d":"宋代","a":"汪晫","c":["缓引前诃度岭巅，真祠犹镇旧山川。", "县知幽德如存日，更有孤忠合老天。", "双炷炉香祈一稔，两诗题咏播千年。", "民安善政神应喜，桑荫儿童犊背眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古三十八首 其二十三","p":"","d":"宋代","a":"释慧方","c":["报客传言信已通，叉手低头便鞠躬。对面一双青白眼，当头蹉过住山翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重宿九莲寺","p":"","d":"明代","a":"吴与弼","c":["曾寓禅房十日居，重来不见旧时书。閒窗一榻春宵梦，细忆流年二纪馀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郡城阴雨","p":"","d":"清代","a":"牛焘","c":["节过中秋雨骑月，残秋徂冬泥滑滑。郡城风急不胜寒，掉臂归来煨榾柮。", "菊残不见傲霜枝，梅花数点香满池。任尔霜前弄喉舌，暖回黍谷日迟迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"癸未元日和许奉常作","p":"","d":"明代","a":"欧大任","c":["旧京元会傍丹霄，雪照青山玉作桥。双阙风云随剑舄，十年江海梦渔樵。", "长生岂但思餐柏，上寿惟能学颂椒。郎署冯唐头已白，自怜何补圣明朝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水龙吟 夜雨，晨霁，过宋家埂南桥，作此以寄贵阳熊建中，八叠前韵","p":"","d":"近代","a":"单人耘","c":["陂塘新绿初稠，泡桐花落经行处。粉云朱日，楼台倒影，天光融聚。", "谁料昨宵，侵窗暗湿，千丝万缕。纵平生侘傺，虽禁白发，满臆是，清狂句。", "行吟未负晴朝，任凭他、连城风雨。青山欲渡，春波又暖，似闻莺语。", "诗可怡人，挞愁浇恨，云何无补。寄乡情一片，迢迢千里，慰天南侣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"口号","p":"","d":"宋代","a":"舒岳祥","c":["敏求善酿能好客，喜与老潘相往还。", "今日敏求泉下卧，老潘无酒客姜山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"出门行","p":"","d":"明代","a":"皇甫汸","c":["君不见李生出门仰天笑，㐲剑直走长安道。又不见苏季还家人尽轻，敝裘再入咸阳城。", "丈夫义气横云海，局促宁为辕下态。白璧凋磨美益光，黄金百鍊精还在。", "身若藩羊触未安，心同塞马达能观。人情溪壑非云险，世路风尘本自难。", "魏尚朝闻起代门，夕看持节拥朱轩。解道圣明能使过，须知感激为衔恩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆陜西 其一","p":"","d":"清代","a":"玄烨","c":["长安城阙昔曾游，黄水名山宛在眸。清渭东流流自在，阳关远去去何休。", "民稠地险人难化，谷贱年丰信有收。衰老无能再一览，缅怀西顾愈添愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古四十四首","p":"","d":"宋代","a":"释师范","c":["大士错解注，志公错注解。", "臭肉积屠门，堪笑无人买。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王敦素","p":"","d":"宋代","a":"邓深","c":["龙蟠山色引衡庐，霜落江清影碧虚。", "鼓枻厌骑沙苑马，行厨饫食武昌鱼。", "缓歌玉树翻新曲，趣入金銮续旧书。", "官达故人稀会面，君来相见肯如初。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"如梦令","p":"","d":"清代","a":"叶俊杰","c":["篱畔红梅香透。又是赏春时候。不见咏诗人，辜负艳阳清昼。", "僝僽。僝僽。病骨畏寒花瘦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再游寒山别墅","p":"","d":"清代","a":"弘历","c":["灵岩纡䍐跸，所为游寒山。春晓宿雨收，千嶂泮轻烟。", "遵磴下高峰，天平在目前。此则姑舍是，已悉率戒盘。", "过岭不五里，别墅爰至焉。巀嶭屏陡壁，逶迤枕平峦。", "渟为半亩池，激为千仞湍。随宜置亭阁，面势抱林泉。", "昨去落梅英，今来绽牡丹。今昨信幻耳，来去亦傥然。", "凡夫果不凡，即境知人仙。中心以藏之，句留苍岩间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"盆池","p":"","d":"宋代","a":"欧阳修","c":["西江之水何悠哉，经历灨石险且回。", "余波拗怒犹涵澹，奔涛击浪常喧豗。", "有时夜上滕王阁，月照净练无纤埃。", "杨阑左里在其北，无风浪起传古来。", "老蛟深处厌窟穴，蛇身微行见者猜。", "呼龙沥酒未及祝，五色粲烂高崔嵬。", "忽然远引千丈去，百里水面中分开。", "收踪灭迹莫知处，但有雨雹随风雷。", "千奇万变聊一戏，岂顾溺死为可哀。", "轻人之命若蝼螘，不止山岳将倾颓。", "此外鱼虾何足道，厌饫但觉腥盘杯。", "壮哉岂不快耳目，胡为守此空墙隈。", "陶盆斗水仍下漏，四岸久雨生莓苔。", "游鱼拨拨不盈寸，泥潜日炙愁暴鳃。", "鱼诚不幸此局促，我能决去反徘徊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饮汪氏庄","p":"","d":"明代","a":"王廷陈","c":["芜秽贫家产，悲伤过客魂。野翁谈废坞，邻竖入颓垣。", "石鼎烧松叶，瓷罂藉竹根。那堪对摇落，寒日下孤村。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乐府变十九首 其十三 莫州谣","p":"","d":"明代","a":"王世贞","c":["兄何在，南伐吴。弟何在，北幽都。老父何在，呼役夫。", "少妇具晨餔，大妇行唤姑。行唤姑，姑不起。溺床下，波瀰瀰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登岳阳楼 其二","p":"","d":"当代","a":"卢青山","c":["轻鸥追帆影，长雾横空蒙。苍茫天穷处，天穷水未穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈二十七首 其七","p":"","d":"宋代","a":"释守净","c":["九夏炎炎火热，木人汗流不辍。夜来一雨便凉，莫道山僧不说。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再赋颂二首 其二","p":"","d":"宋代","a":"韩维","c":["阳景朝来释冻凘，水边林下好追随。灵山一会何曾散，莫学时人语别离。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庚寅岁乡居立秋偶占","p":"","d":"近代","a":"刘凤梧","c":["柴门临水稻花香，垂穗盈畴日渐黄。漫怅粗糠难果腹，须知新谷快登场。", "饱经烽火三边赤，又试秋风一味凉。人隔蒹葭从未得，独扶藜杖看斜阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠别望之兼寄诸相知十首 其九","p":"","d":"明代","a":"顾璘","c":["汶阳临大道，喜近赵东曹。窜地传书数，他乡念我劳。", "名高连泰岳，心远折江涛。拟共观周礼，无因接誉髦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乌什","p":"","d":"清代","a":"曹麟开","c":["戍士无劳夜枕戈，永宁城外散鸣驼。东回姑墨千峰雪，南下于阗九折河。", "五翕侯仍招旧部，二昆弥已靖沙陀。吹鞭争唱天鹅曲，不数摩诃兜勒歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再和送李大夫","p":"","d":"宋代","a":"吕陶","c":["莫听滩前涨水声，少迟樽酒话平生。堪嘉祁老初辞位，却笑樊须欲问耕。", "落日望君三舍远，西风惠我一襟清。江流自在悠哉兴，得得回船十里行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天 儿童节应纤纤邀作","p":"","d":"当代","a":"吴金水","c":["皓齿明眸黛未描。屏前话语倍妖娆。玲珑锦字怜苏惠，要眇清诗感薛涛。", "吹玉笛，抚兰皋。何时携手共花朝。今宵閒看儿童乐，暂忘山长岁月遥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋江晚泊","p":"","d":"清代","a":"虔礼宝","c":["极浦青苍湿未收，晚风吹槛更悠悠。半村黄叶斜阳里，一片闲云古渡头。", "清景可怜皆入画，孤心易感不关秋。水天无事容高卧，此意萧然便十洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游仙诗十首 其五","p":"","d":"魏晋","a":"庾阐","c":["荧荧丹桂紫芝。结根云山九疑。鲜荣夏馥冬熙。谁与薄采松期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题水仙","p":"","d":"明代","a":"杨士奇","c":["汉广之滨，清洛之汭。留此娟好，邂逅谁遗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书事二首 其一","p":"","d":"宋代","a":"刘克庄","c":["空空都没一行书，行行徒矜九尺躯。面上带妖真可耻，脚中有鬼不容扶。", "末年铁拐传仙诀，他日金锥抉冢珠。泉下定为明允笑，果能看破半山无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶成简任肃斋教论","p":"","d":"宋代","a":"黄庚","c":["贫病交攻久废诗，萧然一室独栖迟。", "酒钱已尽琴将典，瓶粟无储鹤亦饥。", "豪杰不多陈仲举，结交惟欠魏无知。", "箪瓢钟鼎都休计，毕竟穷通各有时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"旌德道中","p":"","d":"明代","a":"程可中","c":["底用嗟劳役，空山行自幽。", "晓云梳树出，清溜篆沙流。", "税毕收蚕市，场喧过麦秋。", "驿传东海信，政恐有征求。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读书","p":"","d":"明代","a":"王樵","c":["我性难谐俗，诗书独与亲。一楼堪累月，万事付诸人。", "会意辄忘食，起思如有神。停杯待明月，下榻为嘉宾。", "永日三茅顶，寒江一钓缗。愿言长若此，已谓乐无伦。", "貌以缨冠改，人添识面新。今时崇意气，骨肉在胡秦。", "尝笑陶元亮，何如郑子真。祗因三径费，失却葛天民。", "局蹐邯郸步，惭惶西子矉。浪从双眼白，生取几人瞋。", "物物私其假，生生总是尘。鷾鸸犹有智，鸥鸟固难驯。", "快意醒前梦，回头迹已陈。停云閒对户，堪与洗心论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清夜","p":"","d":"宋代","a":"施枢","c":["客身随取止，一室冷如冰。", "景远吟何托，情疏梦不曾。", "雨粘初藓壁，风谢欲花灯。", "岂是无家者，甘为有发僧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六月二十一日夜起","p":"","d":"清代","a":"郑孝胥","c":["林暗幽光起，楼高碧落通。微风成独夜，凉月亦凌空。", "草草随残劫，纷纷谁长雄？死棋聊插手，吾道若为东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上元前二日郑红泉钱百泉约斋汪云壑陈东川过集斋中","p":"","d":"清代","a":"王复","c":["淡宕试镫风，历乱催花鼓。盼春春已来，淑气盎亭午。", "南荣坐故人，清襟散蘅杜。瓶卉香细浮，幽禽屡窥户。", "对此景物和，欢言酌芳醑。笋韭愧粗供，厨乏络秀女。", "笑语粲烛花，暖意尊前煦。惟兹文字交，便拟醉乡侣。", "中覆暗自欣，战拇纷难数。百斛亦何辞，独醒真徒苦。", "婵娟月满帘，掩映色殊妩。工巷联臂歌，往来同织组。", "试教影吟三，未许更催五。狂思买良宵，那辨金如土。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"船过芳茂和三山二首 其一","p":"","d":"近代","a":"刘济农","c":["芳茂三山峰又峰，苍松翠柏郁葱葱。长堤十里婆娑柳，一叶扁舟烟雨中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"王随","c":["苔光浮乱石，花影倒寒潭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同诸公泛舟一首","p":"","d":"明代","a":"王渐逵","c":["春水生桃渚，扁舟遥自通。浦云低压岸，花雨细从风。", "鼓急疑牵濑，歌残欲罢钟。山人亦何幸，文会兴相同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏贺长公枕溪新筑","p":"","d":"明代","a":"陶益","c":["数亩园中独乐身，别从青野结溪邻。榆枝折罢吹藜火，柿叶书残岸葛巾。", "避俗已拚人共弃，投閒还许鹭相亲。镜湖一曲能如否，解说风流老季真。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古塞下曲四首","p":"","d":"唐代","a":"贯休","c":["古塞腥膻地，胡兵聚如蝇。寒雕中髇石，落在黄河冰。", "苍茫逻逤城，枿枿贼气兴。铸金祷秋穹，还拟相凭陵。", "战骨践成尘，飞入征人目。黄云忽变黑，战鬼作阵哭。", "阴风吼大漠，火号出不得。谁为天子前，唱此边城曲。", "日向平沙出，还向平沙没。飞蓬落军营，惊雕去天末。", "帝乡青楼倚霄汉，歌吹掀天对花月。岂知塞上望乡人，", "日日双眸滴清血。", "狼烟在阵云，匈奴爱轻敌。领兵不知数，牛羊复吞碛。", "严冬大河枯，嫖姚去深击。战血染黄沙，风吹映天赤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百四十一首 其二十六","p":"","d":"宋代","a":"释师范","c":["年年是好年，日日是好日。好事大家知，今朝正月一。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"穿杨亭","p":"","d":"宋代","a":"刘摰","c":["华构翚飞一望中，颜间篆墨飏秋风。休矜百步穿杨巧，未及当年射虎功。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词十首","p":"","d":"宋代","a":"张枢","c":["回廊隔树帘帘卷，曲水穿桥路路通。", "禁漏滴斜花外日，御香薰暖柳边风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"墨竹","p":"","d":"宋代","a":"白玉蟾","c":["虚舟惠我一墨竹，纸上森森一枝玉。", "展向庭前与鹤看，今宵不许枝头宿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月一日道中偶成","p":"","d":"清代","a":"黄景仁","c":["马上年华似掷梭，雨颠风驶奈愁何。三分花事二分去，九十春光六十过。", "几阵箫声山店远，一鞭柳色酒旗多。压鞍诗思何能遣，半为怀人感逝波。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戊午生朝和居厚弟五绝 其四","p":"","d":"宋代","a":"刘克庄","c":["灵龟曳尾防钻壳，老蚌潜光怕剖珠。史笔久无两龚传，画家曾有二疏图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"韩煦仲过镜园泛舟玩月先已共赋六言十绝复投赠八律步元韵奉酬 其四","p":"","d":"明代","a":"邓云霄","c":["潮催月满共扬舲，棹倚花阴且暂停。玉屑纷随挥麈下，石潭疑有睡龙听。", "人间胜会宜投辖，天上佳期欲度星。闻道咸池堪沐发，乘槎吾拟向东溟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐","p":"","d":"近代","a":"白敦仁","c":["雨昏烟锁。飞絮帘前堕。一枕绿云初梦破。万缕千条愁裹。", "人前不理丝桐。新妆垂手临风。三十六园朱李，燕归何处相逢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寓意十首次敬助韵 其七","p":"","d":"元代","a":"王冕","c":["蛮触杂奔竞，蝇蚋纷争喧。", "鸾凤巢枳棘，鸱鸮集琅轩。", "风雷久不作，野露生微寒。", "壮士万里怀，肯谢漂母餐。", "古来王佐才，多在耕钓间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题证道寺","p":"","d":"唐代","a":"唐彦谦","c":["弯环青径斜，自是野僧家。满涧洗岩液，插天排石牙。", "炉寒馀柏子，架静落藤花。记得逃兵日，门多贵客车。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同行归急困倦不能诗","p":"","d":"宋代","a":"陈藻","c":["行李放迟迟，周遭好拾诗。", "归程催我急，脚力与神疲。", "来往成虚费，科名未有期。", "流传堪脍炙，造物不相亏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过安仁县权令主簿同蔡尉见访二首 其一","p":"","d":"宋代","a":"孙觌","c":["莽莽缠兵气，蓬茅庇一邱。尚看蒙赤帻，不复卧黄紬。", "抱牍杭凫鹜，徵租聚沐猴。黄昏更萧瑟，风雨啸鸺鹠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朝房待命","p":"","d":"明代","a":"杨士奇","c":["正是临危处，深知负罪频。廷臣皆执法，天子尚垂仁。", "紫殿红云近，金河瑞彩新。恩波今浩荡，终忆借枯鳞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"癸未，一九四三年。和慈博市桥候潮，用梅溪韵","p":"秋霁","d":"近代","a":"黄咏雩","c":["结梦桐阴，又叶瘁云寒，渐老秋色。苇折鸠移，柳枯蝉噤，薄寒中人犹力。", "故山倦翼。海天南尽伤心碧。渺讯息。谁念白头多病茂陵客。", "听说夜语，几度潮生，半江鱼龙，依旧岑寂。夜何其、鸡鸣未已。", "潇潇风雨此何夕。蕙怅芰裳应记得。说与猿鹤，遮莫为我惊疑，草堂归去，露驰烟驿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西峰访范复庵不值留赠","p":"","d":"明代","a":"屈大均","c":["横天一壁惊无路，频骑夹岭空中度。栈边万壑沉青冥，桥下千峰出烟雾。", "我从玉井得真源，明星玉女招不顾。直向西峰攀所思，楼压莲花花倒垂。", "三闾披发同山鬼，四皓疗饥有紫芝。咫尺白云寻不见，先朝耆旧君堪恋。", "无悲帝座隔层城，自有天门通一箭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"香阴","p":"","d":"明代","a":"通润","c":["山中多药苗，往往发香气。不知采药人，曾嗅此香未。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红","p":"","d":"宋代","a":"佚名","c":["雪共梅花，念动是、经年离拆。重会面、玉肌真态，一般标格。", "谁道无情应也妒，暗香埋没教谁识。却随风、偷入傍妆台，萦帘额。", "惊醉眼，朱成碧。随冷暖，分青白。叹朱弦冻折，高山音息。", "怅望关河无驿使，剡溪兴尽成陈迹。见似枝而喜对杨花，须相忆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"前雁字诗十九首 其十","p":"","d":"明代","a":"王夫之","c":["此字无人识，空劳历九州。分明扶日月，因革自春秋。", "鸩篆删妖步，莺歌耻佞喉。冥飞谁弋篡，不坠草元楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"周漕泊舟寺前","p":"","d":"宋代","a":"释居简","c":["见说淮东使者归，耄鲵都作小儿啼。暂闲绿野停鸿鹄，小俟青冥骤駃騠。", "度外二三皆胜策，胸中十万未全提。浯溪尚有崭天石，颂德歌功尽可题。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"政和戊戌孟夏补试文武遣兴一首","p":"","d":"宋代","a":"李光","c":["一帘疏雨锁牢愁，小阁幽轩得暂留。漫说金瓯能破睡，不如玉局解消忧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暮春有感寄友人","p":"","d":"唐代","a":"鱼玄机","c":["莺语惊残梦，轻妆改泪容。", "竹阴初月薄，江静晚烟浓。", "湿觜衔泥燕，香须采蕊蜂。", "独怜无限思，吟罢亚枝松。"],"tags":["写景", "抒情", "孤寂"],"z":"轻妆：淡妆。\n薄：即淡薄之意。\n烟：指雾气。觜：即嘴。\n蕊：即花蕊。\n亚：通“压”，枝松呈低垂状态。","y":"黄莺的啼声惊扰了诗人的美梦，醒来之后眼泪冲淡了昨晚刚化的淡妆。\n夜晚时分，竹林熙熙，月亮也显得那么的渺小。江边是那么寂静，夜晚的烟雾也显得格外浓重。\n门外的燕子衔着泥土筑巢，蜜蜂在采花培养着蜂蜜。\n只有诗人一个人无限愁思，一个人低语压低了枝松。","s":"","k":"诗"},
  {"t":"咏梅花","p":"","d":"南北朝","a":"庾信","c":["常年腊月半，已觉梅花阑。", "不信今春晚，俱来雪里看。", "树动悬冰落，枝高出手寒。", "早知觅不见，真悔著衣单。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"如梦令 离情四首 其一","p":"","d":"清代","a":"宋琬","c":["刚到凤凰台上。无那骊驹三唱。愿作博山炉，魂逐沈烟游飏。", "罗帐。罗帐。高筑愁城千丈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"穷劫曲","p":"","d":"先秦","a":"佚名","c":["王耶王耶何乖劣。不顾宗庙听谗孽。", "任用无忌多所杀。诛夷白氏族几灭。", "二子东奔适吴越。吴王哀痛助忉怛。", "垂涕举兵将西伐。伍胥白喜孙武决。", "三战破郢王奔发。留兵纵骑虏京阙。", "楚荆骸骨遭掘发。鞭辱腐尸耻难雪。", "几危宗庙社稷灭。庄王何罪国几绝。", "卿士凄怆民恻悷。吴军虽去怖不歇。", "愿王更隐抚忠节。勿为谗口能谤亵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄陶仲调","p":"","d":"明代","a":"陈子升","c":["九畹兰边五柳家，沅湘归去阻瑶华。名山太史传青简，濒海诸生想绛纱。", "怀古独寻洲畔树，悲秋还听月中笳。上林摇笔空云梦，肯向游畋逐后车。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上巳日赠都上人","p":"","d":"唐代","a":"殷尧藩","c":["三月初三日，千家与万家。蝶飞秦地草，莺入汉宫花。", "鞍马皆争丽，笙歌尽斗奢。吾师无所愿，惟愿老烟霞。", "曲水公卿宴，香尘尽满街。无心修禊事，独步到禅斋。", "细草萦愁目，繁花逆旅怀。绮罗人走马，遗落凤凰钗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜收知旧书，复畏答，书二绝","p":"","d":"宋代","a":"范成大","c":["强裁尺互答相思，两目眵昏腕力疲。", "牵率老夫令至此，门前犹说报书迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天 赠医士沈德诚","p":"","d":"元代","a":"张雨","c":["东老传家道气浓。榴皮壁上有仙踪。耳孙阴德如何限，都在参苓药笼中。", "无贵贱，有穷通。活人心事契苍穹。吾家昆弟能无恙，须藉全生一匕功。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 其四 岁暮有咏","p":"","d":"清代","a":"徐树铮","c":["向晚风来天又雪。未是春归，已是春怀恶。百草千花愁寂寞。", "隔帘乍报梅英落。", "万种缠绵抛不却。便不思量，争不思量著。入夜霜钟敲更切。", "玉楼高梦浑惊觉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵答留台春卿集贤侍郎见寄","p":"","d":"宋代","a":"韩琦","c":["十稔违谈燕，区区混浊流。经时无一信，度夕是三秋。", "友会此难约，君恩尚未酬。何人伴高兴，洛棹与嵩楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同杨计公谒刁蒙吉先生","p":"","d":"清代","a":"张念圣","c":["三年曾有约，今岁始能复。携我同心人，登龙展私淑。", "入门炙道儿，閒庭一何肃。先生抱道深，元气如可掬。", "正议回狂澜，耻与时贤逐。圣也戆而狂，意行无边幅。", "三日坐春风，句萌学草木。洗耳聆铎音，谈经继白鹿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题横披竹","p":"","d":"宋代","a":"龚璛","c":["竹影平寻月落时，小舟移岸半蒿迟。参差化作一匹练，我独寒篷亲见之。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东都望幸","p":"","d":"唐代","a":"章碣","c":["懒修珠翠上高台，眉月连娟恨不开。", "纵使东巡也无益，君王自领美人来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和郭从范二首 其二","p":"","d":"宋代","a":"王质","c":["萱草摇清风，榴英焰方午。新燕披紫茸，低昂子随母。", "暄寒换时节，浓疏变庭树。杜老痴不归，空怜小儿女。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"禹庙 其二","p":"","d":"宋代","a":"王铚","c":["夏后东阶殡，遗踪照路隅。今观四山拱，犹似百神趋。", "功已百王冠，言尤万世谟。死生怀舜德，旧邑对姚虞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"访朱仲开","p":"","d":"明代","a":"欧大任","c":["献岁灯初试，寻君正此时。尺书劳夙约，斗酒赴佳期。", "江上观涛色，淮南揽桂枝。自今能策马，闲过习家池。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金钱花","p":"","d":"唐代","a":"卢子发","c":["轮廓休夸四字书，红窠写出对庭除。", "时时买得佳人笑，本色金钱却不如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"学书十绝 其四","p":"","d":"宋代","a":"李之仪","c":["闭门不语信深沉，岂可讥时作酒箴。料得门前无好事，解嘲聊复寄初心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"臧郎中挽歌二首","p":"","d":"宋代","a":"司马光","c":["素履存诚厚，虚怀待物真。", "乡闾昔相接，朋友世弥亲。", "遗札蝇头强，长阡马鬣新。", "九原那可作，空复想音尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠出塞客","p":"","d":"唐代","a":"薛能","c":["出郊征骑逐飞埃，此别惟愁春未回。", "寒叶夕阳投宿意，芦关门向远河开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"减字木兰花九首 其六","p":"","d":"清代","a":"李慈铭","c":["记曾相见，帘里惊鸿留一盼。待得重逢，腰瘦眉浓两病中。", "恹恹春闷，带一分愁偏有韵。恁地聪明，假作无情更有情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"岑年伯见和步韵称谢并谢周莓厓都堂","p":"","d":"明代","a":"霍与瑕","c":["正月连阴三十朝，且喜今朝见日色。忽然仙老送歌来，照日读之光无极。", "既似明霞流玉宇，又如碧涧飘红雨。杏树枝枝漱露丹，桃花朵朵笼烟紫。", "笼烟漱露竞新妍，一度一看一可怜。学海翻波襄太华，词源滚浪拍天边。", "阳春古调徽音远，余欲和之风力软。惊看三峡斗狂澜，自笑江沱空婉转。", "东园花气隔帘闻，迢递柔风细雨匀。自是春光春思好，况逢诗句十分春。", "独怜碧眼看花早，昨日花开今已老。得高歌处且高歌，有旨酒无吾颇好。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春词二首","p":"","d":"唐代","a":"张琰","c":["垂柳鸣黄鹂，关关若求友。春情不可耐，愁杀闺中妇。", "日暮登高楼，谁怜小垂手。", "昨日桃花飞，今朝梨花吐。春色能几时，那堪此愁绪。", "荡子游不归，春来泪如雨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"芙蓉花二首","p":"","d":"宋代","a":"欧阳修","c":["红芳晓露浓，绿树秋风冷。", "共喜巧回春，不妨闲弄影。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"奉送戚都护归田四首","p":"","d":"明代","a":"陈第","c":["承平日久不知兵，南北征师浪结营。", "独有鸳鸯明节制，堂堂中国振先声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送侄合赴省试三首 其一","p":"","d":"宋代","a":"张纲","c":["破的雄乡国，担簦上帝京。路夷骧逸骥，天阔转飞鲸。", "学就千人敌，名归四海争。莫言年少在，岁月易峥嵘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观莲","p":"","d":"元代","a":"胡天游","c":["清池莹人心，俯见荷叶背。南塘非不佳，无此青钱盖。", "沈沈古镜净，濯濯明妆对。凉风似留人，幽赏心独会。", "天公亦解事，一雨不破块。小呼巫阳云，浣此倾国态。", "高盘捧跳珠，错落无小大。恍疑逢二妃，迎笑争解佩。", "低昂巧簸弄，明月聚还碎。冯夷不相容，转盼何所在。", "人生总虚幻，伫立增叹慨。聊将一饷间，了我看花债。", "濂翁不我待，谁复同此爱。长啸归去来，馀芳满襟带。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送杨辟同年","p":"","d":"宋代","a":"刘敞","c":["昔在谷子云，语妙气纵横。遨游五侯间，谈笑临公卿。", "丈夫伸知己，未必老一经。怀宝迷其邦，古人谁谓平。", "杨侯东州客，三岁不飞鸣。杂沓二府书，缤纷委弓旌。", "结靷西入关，长揖谢诸生。风霜岂不永，意气故自轻。", "伊昔惟一剑，蒯缑吐悲声。当令代舍长，见我珠履荣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋风吟","p":"","d":"明代","a":"石宝","c":["惊飙振修麓，槁叶下乔林。怒号捲积霭，急转杨轻砧。", "翩翩孤凤雏，托身芳树阴。中夜感箫韶，激烈发清音。", "下有抱贞士，闻之援素琴。一弹南山高，再弹流水深。", "离鸾与别鹤，嘹唳声相寻。律吕转清切，壮怀伫萧森。", "谁言人生贵，无异巢中禽。得时应春鸣，遇寒亦哀吟。", "万动各有息，睹物悟人心。服我敝缊袍，安知辟寒金。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"牛首山夜饮","p":"","d":"当代","a":"吴金水","c":["豪筵未尽兴，乘夜上春山。径转松林下，樽开花影间。", "涧芳沾鬓重，月色上衣闲。可惜千杯罄，晓星相与还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登乌石寺","p":"","d":"宋代","a":"杨万里","c":["回头身忽在树杪，一览千山万山小。", "怪崖不落欹欲摧，令人仰看怯眼开。", "小亭解事知侬倦，翼然飞出青山半。", "上头最上却镜平，百亩金碧千衲僧。", "高峰高寺更高阁，进步竿头若为脚。", "兹游胜绝庸非天，山下虚行二十年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"壶中天（客中寄友）","p":"","d":"宋代","a":"张炎","c":["西秦倦旅。是几年不听，西湖风雨。我托长镵垂短发，心事时看天语。吟箧空随，征衣休换，薜荔犹堪补。山能招隐，一瓢闲挂烟树。", "方叹旧国人稀，花间忽见，倾盖浑如故。客里不须谈世事，野老安知今古。海上盟鸥，门深款竹，风月平分取。陶然一醉，此时愁在何处。"],"tags":[],"z":"","y":"","s":"","k":"诗"}
];